1	/**
2	 * VM_MOVE / VM_MOVE_CLEANUP — move one server's VM to another physical node.
3	 *
4	 * The engine (design in docs/VM-MOVE.md, operational plan in
5	 * docs/PRIMARY-OFFLOAD-PLAN.md). Facts and decisions come from lib/vm-move/*;
6	 * this file only sequences side effects and records what happened on the
7	 * server's VmMove row so a retried job resumes instead of restarting.
8	 *
9	 * Phase order and WHY it is this order:
10	 *   SNAPSHOT_LIVE → SEND_FULL      source keeps running; the big transfer costs
11	 *                                  the customer nothing.
12	 *   STOP_SOURCE                    dark window opens. Server.status is set to
13	 *                                  STOPPED here on purpose: vmRecoverySweep
14	 *                                  restarts any RUNNING server whose VM is off,
15	 *                                  which would resurrect the source mid-move.
16	 *   SEND_INCREMENTAL               only what changed since the full pass.
17	 *   CREATE_TARGET                  config via the Proxmox API + move-safe
18	 *                                  cloud-init snippet (lib/vm-move/plan.ts
19	 *                                  explains why the original snippet must NOT
20	 *                                  be reused).
21	 *   MOVE_IP (dedicated only)       the one step with an external side effect;
22	 *                                  deliberately last before start so everything
23	 *                                  before it rolls back locally.
24	 *   START_TARGET                   start + guest agent + SSH verify.
25	 *   COMMIT                         DB cutover, NAT reconcile on both nodes, DNS
26	 *                                  resync, source onboot=0, notices, audit.
27	 *
28	 * Failure policy: before STOP_SOURCE a failure just re-queues the job (the
29	 * source is still serving; the resume continues from the last checkpoint).
30	 * Between STOP_SOURCE and COMMIT a failure rolls back IMMEDIATELY (target
31	 * removed, IP routed back, source started) to keep the dark window short.
32	 * From COMMIT on the move is forward-only (the DB already points at the
33	 * target) and a failure re-queues for a retry of the idempotent remainder.
34	 *
35	 * The source VM is never destroyed here. VM_MOVE_CLEANUP, requested
36	 * explicitly after `keepSourceUntil`, does that — and only after re-verifying
37	 * the DB and the hypervisor both agree the target is the live one.
38	 */
39	import { writeFile, unlink } from "node:fs/promises";
40	import type { Job, Prisma } from "@prisma/client";
41	import { db } from "../lib/db";
42	import { SANDBOX } from "../lib/sandbox";
43	import { pveFor, waitForGuestAgent, destroyVmIdempotent, isVmAbsentError, type PveClient, type VmDestroyHost } from "../lib/proxmox";
44	import { allocateIp } from "../lib/ipam";
45	import { serverRootPassword } from "../lib/sftp";
46	import { sendMail } from "../lib/mailer";
47	import { agentWriteSnippet, agentDeleteSnippet } from "../lib/node-agent";
48	import { syncPortForwardsBestEffort } from "./network";
49	import { checkSshReachable } from "./provision-health";
50	import { buildMovePlan, loadMoveNode, loadMoveServer, type MoveNode } from "../lib/vm-move/preflight";
51	import { zfsHostFor, meter, type ZfsHost } from "../lib/vm-move/zfs-host";
52	import {
53	  buildTargetConfig,
54	  incrementalSnapshotName,
55	  liveSnapshotName,
56	  macFromNet0,
57	  moveSafeVendorSnippet,
58	  nextPhase,
59	  parseScsi0,
60	  rollbackAllowed,
61	  rollbackSteps,
62	} from "../lib/vm-move/plan";
63	import { ovhEnsureVirtualMac, ovhMoveIp, ovhReleaseVirtualMac } from "../lib/vm-move/ovh-ip-move";
64	import type { MoveCheckpoints, MoveLogLine, MovePhase, MovePlan, VmMoveCleanupJobPayload, VmMoveJobPayload } from "../lib/vm-move/types";
65	
66	const SNIPPET_DIR = process.env.NXEON_SNIPPET_DIR ?? "/tank/backup/snippets";
67	const KEEP_SOURCE_DAYS = Math.max(1, Number(process.env.VM_MOVE_KEEP_SOURCE_DAYS ?? 7));
68	const SHUTDOWN_TIMEOUT_S = 90;
69	
70	type Progress = (jobId: string, progress: number, step: string) => Promise<void>;
71	
72	type MoveRow = NonNullable<Awaited<ReturnType<typeof db.vmMove.findUnique>>>;
73	
74	// ---------------------------------------------------------------------------
75	// Row helpers
76	// ---------------------------------------------------------------------------
77	
78	function cpOf(row: MoveRow): MoveCheckpoints {
79	  return ((row.checkpoints as MoveCheckpoints | null) ?? {}) as MoveCheckpoints;
80	}
81	function planOf(row: MoveRow): MovePlan | null {
82	  return (row.plan as MovePlan | null) ?? null;
83	}
84	
85	async function appendLog(moveId: string, phase: string, msg: string): Promise<void> {
86	  console.log(`[vm-move] ${moveId} ${phase}: ${msg}`);
87	  const row = await db.vmMove.findUnique({ where: { id: moveId }, select: { log: true } });
88	  const log = ((row?.log as MoveLogLine[] | null) ?? []).slice(-400);
89	  log.push({ at: new Date().toISOString(), phase, msg });
90	  await db.vmMove.update({ where: { id: moveId }, data: { log: log as unknown as Prisma.InputJsonValue } }).catch(() => {});
91	}
92	
93	async function saveCheckpoints(moveId: string, patch: Partial<MoveCheckpoints>, phase?: MovePhase): Promise<MoveCheckpoints> {
94	  const row = await db.vmMove.findUnique({ where: { id: moveId } });
95	  const next = { ...cpOf(row!), ...patch };
96	  await db.vmMove.update({
97	    where: { id: moveId },
98	    data: { checkpoints: next as unknown as Prisma.InputJsonValue, ...(phase ? { phase } : {}) },
99	  });
100	  return next;
101	}
102	
103	// ---------------------------------------------------------------------------
104	// Proxmox helpers
105	// ---------------------------------------------------------------------------
106	
107	async function vmRunning(conn: PveClient, vmid: number): Promise<boolean | null> {
108	  try {
109	    const s = await conn.vmStatus(vmid);
110	    return s?.status === "running";
111	  } catch (e) {
112	    if (isVmAbsentError(e, vmid)) return null;
113	    throw e;
114	  }
115	}
116	
117	async function stopVm(conn: PveClient, vmid: number): Promise<void> {
118	  const running = await vmRunning(conn, vmid);
119	  if (!running) return;
120	  try {
121	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/shutdown`, { timeout: SHUTDOWN_TIMEOUT_S });
122	    await conn.waitForTask(upid, (SHUTDOWN_TIMEOUT_S + 30) * 1000);
123	  } catch {
124	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/stop`, {});
125	    await conn.waitForTask(upid, 120_000);
126	  }
127	  if (await vmRunning(conn, vmid)) throw new Error(`vm ${vmid} on ${conn.node} is still running after shutdown+stop`);
128	}
129	
130	async function startVm(conn: PveClient, vmid: number): Promise<void> {
131	  if (await vmRunning(conn, vmid)) return;
132	  const upid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
133	  await conn.waitForTask(upid, 180_000);
134	}
135	
136	function destroyHost(conn: PveClient): VmDestroyHost {
137	  return {
138	    probe: async (id) => {
139	      try {
140	        await conn.vmStatus(id);
141	        return "present";
142	      } catch (e) {
143	        return isVmAbsentError(e, id) ? "absent" : "unknown";
144	      }
145	    },
146	    stop: async (id) => {
147	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${id}/status/stop`, {});
148	      await conn.waitForTask(upid);
149	    },
150	    destroy: async (id) => {
151	      const upid = await conn.del(`/nodes/${conn.node}/qemu/${id}`, { "destroy-unreferenced-disks": 1, purge: 1 });
152	      await conn.waitForTask(upid, 600_000);
153	    },
154	  };
155	}
156	
157	async function writeSnippet(node: MoveNode, storage: string, filename: string, content: string): Promise<void> {
158	  if (node.isPrimary) await writeFile(`${SNIPPET_DIR}/${filename}`, content, "utf8");
159	  else await agentWriteSnippet(node, storage, filename, content);
160	}
161	async function deleteSnippet(node: MoveNode, storage: string, filename: string): Promise<void> {
162	  if (node.isPrimary) await unlink(`${SNIPPET_DIR}/${filename}`).catch(() => {});
163	  else await agentDeleteSnippet(node, storage, filename).catch(() => {});
164	}
165	
166	// ---------------------------------------------------------------------------
167	// The move
168	// ---------------------------------------------------------------------------
169	
170	type Ctx = {
171	  job: Job;
172	  move: MoveRow;
173	  plan: MovePlan;
174	  source: MoveNode;
175	  target: MoveNode;
176	  srcConn: PveClient;
177	  tgtConn: PveClient;
178	  srcZfs: ZfsHost;
179	  tgtZfs: ZfsHost;
180	  dedicated: boolean;
181	  progress: Progress;
182	};
183	
184	async function transfer(ctx: Ctx, snap: string, from: string | null, label: string): Promise<void> {
185	  const { plan, srcZfs, tgtZfs } = ctx;
186	  const total = plan.sourceUsedBytes || 1;
187	  let lastReport = 0;
188	  const stream = await srcZfs.sendStream(plan.sourceDataset, snap, from);
189	  const m = meter((bytes) => {
190	    const now = Date.now();
191	    if (now - lastReport > 5000) {
192	      lastReport = now;
193	      // Compressed bytes on the wire vs the uncompressed `used` figure —
194	      // a rough but monotonic indicator, good enough for a progress bar.
195	      const pct = Math.min(99, Math.round((bytes / total) * 100));
196	      void ctx.progress(ctx.job.id, pct, `${label}: ${(bytes / 2 ** 30).toFixed(2)} GB sent`);
197	    }
198	  });
199	  stream.pipe(m);
200	  stream.on("error", (e) => m.destroy(e));
201	  try {
202	    await tgtZfs.recv(plan.targetDataset, m);
203	  } catch (e) {
204	    stream.destroy(); // stop the source-side zfs send / ssh / agent stream
205	    throw e;
206	  }
207	}
208	
209	/** Must match worker/index.ts's MAX_ATTEMPTS — the job's attempts counter is
210	 *  incremented at claim time, so on the last permitted attempt a failure
211	 *  that would otherwise leave the VmMove row RUNNING forever is finalised. */
212	const MOVE_MAX_ATTEMPTS = 3;
213	
214	async function runPhase(ctx: Ctx, phase: MovePhase): Promise<void> {
215	  const { move, plan, source, target, srcConn, tgtConn, srcZfs, tgtZfs } = ctx;
216	  const log = (msg: string) => appendLog(move.id, phase, msg);
217	  await ctx.progress(ctx.job.id, 0, `${phase}`);
218	
219	  switch (phase) {
220	    case "SNAPSHOT_LIVE": {
221	      const name = liveSnapshotName(move.id);
222	      const existing: any[] = await srcConn.get(`/nodes/${srcConn.node}/qemu/${plan.sourceVmid}/snapshot`).catch(() => []);
223	      if (!(existing ?? []).some((s) => s?.name === name)) {
224	        // vmstate=0: disk-only. With the guest agent enabled Proxmox fs-freezes
225	        // the guest for the instant of the snapshot, so the full pass is
226	        // filesystem-consistent, not merely crash-consistent.
227	        const upid = await srcConn.post(`/nodes/${srcConn.node}/qemu/${plan.sourceVmid}/snapshot`, {
228	          snapname: name,
229	          vmstate: 0,
230	          description: `Nxeon VM move ${move.id} → ${target.name} (live pass)`,
231	        });
232	        await srcConn.waitForTask(upid, 300_000);
233	      }
234	      await saveCheckpoints(move.id, { liveSnapshotName: name });
235	      await log(`consistent snapshot ${name} on ${source.name}`);
236	      return;
237	    }
238	    case "SEND_FULL": {
239	      const cp = cpOf(move);
240	      const info = await tgtZfs.dataset(plan.targetDataset);
241	      if (info.exists && info.snapshots.includes(cp.liveSnapshotName!)) {
242	        await log(`target already holds ${plan.targetDataset}@${cp.liveSnapshotName} — skipping the full send`);
243	      } else {
244	        if (info.exists) {
245	          // A partial receive from an interrupted attempt — zfs leaves no usable
246	          // state behind; start the dataset over.
247	          await tgtZfs.destroyDataset(plan.targetDataset);
248	          await log(`removed partial ${plan.targetDataset} from an earlier attempt`);
249	        }
250	        const t0 = Date.now();
251	        await transfer(ctx, cp.liveSnapshotName!, null, "Full copy");
252	        await log(`full stream done in ${Math.round((Date.now() - t0) / 1000)}s (${(plan.sourceUsedBytes / 2 ** 30).toFixed(1)} GB used on source)`);
253	      }
254	      await saveCheckpoints(move.id, { fullSentAt: new Date().toISOString() });
255	      return;
256	    }
257	    case "STOP_SOURCE": {
258	      const wasRunning = await vmRunning(srcConn, plan.sourceVmid);
259	      await stopVm(srcConn, plan.sourceVmid);
260	      // STOPPED here keeps vmRecoverySweep from restarting the source (it only
261	      // looks at RUNNING rows) and is also the truth: the customer's server is
262	      // off for the duration of the dark window.
263	      await db.server.update({ where: { id: move.serverId }, data: { status: "STOPPED" } });
264	      await saveCheckpoints(move.id, { sourceStoppedAt: new Date().toISOString(), previousIpAddress: (await db.server.findUnique({ where: { id: move.serverId }, select: { ipAddress: true } }))?.ipAddress ?? null });
265	      await log(`source vm ${plan.sourceVmid} stopped (was ${wasRunning ? "running" : "already stopped"}) — dark window opened`);
266	      return;
267	    }
268	    case "SEND_INCREMENTAL": {
269	      const cp = cpOf(move);
270	      const name = cp.incrementalSnapshotName ?? incrementalSnapshotName(move.id);
271	      const src = await srcZfs.dataset(plan.sourceDataset);
272	      if (!(src.exists && src.snapshots.includes(name))) await srcZfs.snapshot(plan.sourceDataset, name);
273	      await saveCheckpoints(move.id, { incrementalSnapshotName: name });
274	      const tgt = await tgtZfs.dataset(plan.targetDataset);
275	      if (tgt.exists && tgt.snapshots.includes(name)) {
276	        await log(`target already holds @${name} — skipping incremental`);
277	      } else {
278	        const t0 = Date.now();
279	        await transfer(ctx, name, cp.liveSnapshotName!, "Final sync");
280	        await log(`incremental stream done in ${Math.round((Date.now() - t0) / 1000)}s`);
281	      }
282	      await saveCheckpoints(move.id, { incrementalSentAt: new Date().toISOString() });
283	      return;
284	    }
285	    case "CREATE_TARGET": {
286	      const cp = cpOf(move);
287	      const server = await loadMoveServer(move.serverId);
288	      if (!server) throw new Error("server row vanished mid-move");
289	      const srcCfg = await srcConn.get(`/nodes/${srcConn.node}/qemu/${plan.sourceVmid}/config`);
290	      const disk = parseScsi0(String(srcCfg?.scsi0 ?? ""));
291	      if (!disk) throw new Error("source scsi0 unreadable at CREATE_TARGET");
292	
293	      // Move-safe vendor snippet first — the config below references it.
294	      const snippetName = `nxeon-${plan.targetVmid}.yaml`;
295	      await writeSnippet(target, plan.targetSnippetStorage, snippetName, moveSafeVendorSnippet());
296	      await saveCheckpoints(move.id, { targetSnippetWritten: true });
297	
298	      let network: Parameters<typeof buildTargetConfig>[0]["network"];
299	      let targetPrivateIp: string | undefined;
300	      if (plan.addressing.kind === "DEDICATED") {
301	        // The Virtual MAC on the target server is created in MOVE_IP (it needs
302	        // the IP routed there first). Boot config gets a placeholder MAC that
303	        // MOVE_IP rewrites before START_TARGET — never start with it.
304	        network = { kind: "DEDICATED", address: plan.addressing.address, gateway: plan.addressing.targetGateway, virtualMac: cp.targetVirtualMac ?? "02:00:00:00:00:00", bridge: "vmbr0" };
305	      } else {
306	        // Reserve a private IP in the target's /24 (in-process reservation,
307	        // see lib/ipam.ts) — written onto the Server row only at COMMIT.
308	        targetPrivateIp = (cp as any).targetPrivateIp ?? (await allocateIp(target.id));
309	        network = { kind: "NAT", privateIp: targetPrivateIp!, gateway: plan.addressing.targetGateway, mac: macFromNet0(srcCfg?.net0), bridge: plan.targetBridge };
310	      }
311	      const cfg = buildTargetConfig({
312	        targetVmid: plan.targetVmid,
313	        carried: plan.carriedConfig,
314	        disk,
315	        targetStorage: plan.targetStorage,
316	        snippetStorage: plan.targetSnippetStorage,
317	        network,
318	        cipassword: serverRootPassword(server),
319	      });
320	      const exists = await vmRunning(tgtConn, plan.targetVmid);
321	      if (exists === null) {
322	        const upid = await tgtConn.post(`/nodes/${tgtConn.node}/qemu`, cfg);
323	        await tgtConn.waitForTask(upid, 120_000);
324	      } else {
325	        await log(`target vm ${plan.targetVmid} already exists — reusing`);
326	      }
327	      // The received dataset still carries this engine's two snapshots; the
328	      // target VM must start clean (Proxmox knows nothing about them).
329	      for (const s of [cp.liveSnapshotName, cp.incrementalSnapshotName]) if (s) await tgtZfs.deleteSnapshot(plan.targetDataset, s).catch(() => {});
330	      await saveCheckpoints(move.id, { targetVmCreated: true, ...(targetPrivateIp ? ({ targetPrivateIp } as any) : {}) });
331	      await log(`target vm ${plan.targetVmid} created on ${target.name} (${network.kind}${targetPrivateIp ? ` ${targetPrivateIp}` : ""})`);
332	      return;
333	    }
334	    case "MOVE_IP": {
335	      if (plan.addressing.kind !== "DEDICATED") return;
336	      const a = plan.addressing;
337	      const taskId = await ovhMoveIp(a.address, a.targetService);
338	      await saveCheckpoints(move.id, { ipMovedAt: new Date().toISOString(), ...(taskId !== null ? { ipMoveTaskId: taskId } : {}) });
339	      await log(`OVH routed ${a.address} → ${a.targetService}${taskId !== null ? ` (task ${taskId})` : " (already there)"}`);
340	      const mac = await ovhEnsureVirtualMac(a.targetService, a.address, `nxeon-${plan.targetVmid}`);
341	      await tgtConn.post(`/nodes/${tgtConn.node}/qemu/${plan.targetVmid}/config`, {
342	        net0: `virtio=${mac},bridge=vmbr0`,
343	        ipconfig0: `ip=${a.address}/32,gw=${a.targetGateway}`,
344	      });
345	      await saveCheckpoints(move.id, { targetVirtualMac: mac });
346	      await log(`virtual MAC ${mac} bound on ${a.targetService}; target net0 updated`);
347	      return;
348	    }
349	    case "START_TARGET": {
350	      await startVm(tgtConn, plan.targetVmid);
351	      await saveCheckpoints(move.id, { targetStartedAt: new Date().toISOString() });
352	      await ctx.progress(ctx.job.id, 90, "Waiting for the guest agent…");
353	      const agentOk = await waitForGuestAgent(tgtConn, tgtConn.node, plan.targetVmid, 240_000);
354	      await log(agentOk ? "guest agent answered on the target" : "guest agent did NOT answer within 240s");
355	      // External reachability — exactly what the customer will dial.
356	      let sshOk = false;
357	      let sshDetail = "";
358	      if (plan.addressing.kind === "DEDICATED") {
359	        const r = await checkSshReachable(plan.addressing.address, 22, { timeoutMs: 180_000 });
360	        sshOk = r.ok;
361	        sshDetail = `${plan.addressing.address}:22 ${r.ok ? "answered" : `no SSH banner (${r.error ?? "timeout"})`}`;
362	      } else {
363	        const cp = cpOf(move);
364	        const privateIp = (cp as any).targetPrivateIp as string | undefined;
365	        // NAT rules for the new address are installed at COMMIT (they key off
366	        // Server.nodeId/ipAddress); before that, probe the guest from the
367	        // target node itself is not possible from here, so verify via the
368	        // agent + a TCP probe once COMMIT has synced NAT (see COMMIT).
369	        sshOk = agentOk;
370	        sshDetail = `NAT guest ${privateIp ?? "?"} — external SSH verified after COMMIT's NAT sync`;
371	      }
372	      if (!agentOk && !sshOk) throw new Error(`target vm ${plan.targetVmid} started but neither the guest agent nor SSH answered (${sshDetail})`);
373	      await saveCheckpoints(move.id, { targetVerified: true });
374	      await log(`target verified: ${sshDetail}`);
375	      return;
376	    }
377	    case "COMMIT": {
378	      const cp = cpOf(move);
379	      const server = await loadMoveServer(move.serverId);
380	      if (!server) throw new Error("server row vanished mid-move");
381	      const targetPrivateIp = (cp as any).targetPrivateIp as string | undefined;
382	      const addressChanged = plan.addressing.kind === "NAT";
383	      await db.$transaction(async (tx) => {
384	        await tx.server.update({
385	          where: { id: move.serverId },
386	          data: {
387	            nodeId: target.id,
388	            vmid: plan.targetVmid,
389	            status: "RUNNING",
390	            ...(plan.addressing.kind === "NAT" && targetPrivateIp ? { ipAddress: targetPrivateIp } : {}),
391	          },
392	        });
393	        if (plan.addressing.kind === "DEDICATED") {
394	          await tx.dedicatedIp.updateMany({
395	            where: { address: plan.addressing.address },
396	            data: { nodeId: target.id, virtualMac: cp.targetVirtualMac ?? undefined },
397	          });
398	        }
399	        await tx.vmMove.update({
400	          where: { id: move.id },
401	          data: { addressChanged, keepSourceUntil: new Date(Date.now() + KEEP_SOURCE_DAYS * 86_400_000) },
402	        });
403	      });
404	      await saveCheckpoints(move.id, { committedAt: new Date().toISOString() });
405	      await log(`DB cutover: node ${source.name} → ${target.name}, vmid ${plan.sourceVmid} → ${plan.targetVmid}${targetPrivateIp ? `, private IP → ${targetPrivateIp}` : ""}`);
406	
407	      // Source must never come back on its own (a node reboot runs onboot
408	      // guests) — and is visibly marked as a moved leftover.
409	      try {
410	        const srcCfg = await srcConn.get(`/nodes/${srcConn.node}/qemu/${plan.sourceVmid}/config`);
411	        const tags = String(srcCfg?.tags ?? "").split(";").filter(Boolean).filter((t) => t !== "nxeon-moved");
412	        tags.push("nxeon-moved");
413	        await srcConn.post(`/nodes/${srcConn.node}/qemu/${plan.sourceVmid}/config`, { onboot: 0, tags: tags.join(";") });
414	        await saveCheckpoints(move.id, { sourceOnbootDisabled: true });
415	      } catch (e: any) {
416	        await log(`WARNING: could not set onboot=0 on the source vm: ${e?.message ?? e} — set it by hand before the next source-node reboot`);
417	      }
418	
419	      // NAT on BOTH nodes: the source chain loses this server's rules (its
420	      // nodeId changed), the target chain gains them. Dedicated-IP servers
421	      // have no rules. Reported, never swallowed.
422	      if (!SANDBOX) {
423	        const natErr = await syncPortForwardsBestEffort(`vm move ${server.hostname}`);
424	        await log(natErr ? `NAT sync reported: ${natErr.message}` : "NAT chains reconciled on every node");
425	        if (plan.addressing.kind === "NAT" && server.sshPort) {
426	          const r = await checkSshReachable(target.publicIp, server.sshPort, { timeoutMs: 120_000 });
427	          await log(`external SSH ${target.publicIp}:${server.sshPort} ${r.ok ? "answered" : `did not answer (${r.error ?? "timeout"})`}`);
428	        }
429	      }
430	      if (server.subdomain) {
431	        await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId: server.id } });
432	        await log(`queued SYNC_GAME_DNS for ${server.subdomain}`);
433	      }
434	
435	      // Customer notice — ONLY when the address really changed.
436	      if (addressChanged) {
437	        const title = `${server.hostname}: new connection address`;
438	        const body =
439	          `Your server ${server.hostname} now runs on upgraded hardware and has a new public address: ${target.publicIp}. ` +
440	          `Your SSH port${server.sshPort ? ` (${server.sshPort})` : ""} and any game ports are unchanged${server.subdomain ? `, and ${server.subdomain}.play.nxeon.cloud already points at the new address` : ""}. ` +
441	          `Please update any saved connections that use the old IP (${source.publicIp}).`;
442	        await db.notification.create({ data: { userId: server.userId, title, body, href: `/dashboard/servers/${server.id}` } }).catch(() => {});
443	        if (server.user?.email) {
444	          await sendMail({
445	            to: server.user.email,
446	            subject: title,
447	            html: `<p>${body}</p><p>Nothing else about your server changed — same data, same plan, same root password.</p>`,
448	            text: body,
449	            userId: server.userId,
450	          }).catch((e) => console.error("[vm-move] customer email failed", e));
451	        }
452	      } else {
453	        await db.notification
454	          .create({
455	            data: {
456	              userId: server.userId,
457	              title: `${server.hostname} was moved to upgraded hardware`,
458	              body: "A short restart happened during the move. Your IP address, ports and data are unchanged.",
459	              href: `/dashboard/servers/${server.id}`,
460	            },
461	          })
462	          .catch(() => {});
463	      }
464	
465	      await db.auditLog.create({
466	        data: {
467	          userId: move.requestedById ?? null,
468	          action: "server.vm_move",
469	          category: "server",
470	          target: server.hostname,
471	          detail: `${source.name}(vmid ${plan.sourceVmid}) → ${target.name}(vmid ${plan.targetVmid}) ${plan.addressing.kind}${addressChanged ? " address-changed" : ""} move=${move.id}`,
472	        },
473	      });
474	      await db.vmMove.update({ where: { id: move.id }, data: { status: "DONE", phase: "DONE", finishedAt: new Date() } });
475	      await log(`move complete; source vm ${plan.sourceVmid} kept STOPPED on ${source.name} until ${new Date(Date.now() + KEEP_SOURCE_DAYS * 86_400_000).toISOString().slice(0, 10)}`);
476	      return;
477	    }
478	    case "PREFLIGHT":
479	    case "DONE":
480	      return;
481	  }
482	}
