484	// ---------------------------------------------------------------------------
485	// Rollback
486	// ---------------------------------------------------------------------------
487	
488	async function rollback(ctx: Ctx, why: string): Promise<{ ok: boolean; errors: string[] }> {
489	  const { move, plan, source, target, srcConn, tgtConn, tgtZfs } = ctx;
490	  const cp = cpOf(move);
491	  const steps = rollbackSteps(cp, { dedicated: ctx.dedicated });
492	  const done: string[] = [];
493	  const errors: string[] = [];
494	  await appendLog(move.id, "ROLLBACK", `starting rollback (${why}); steps: ${steps.join(" → ")}`);
495	  await saveCheckpoints(move.id, { rollback: { startedAt: new Date().toISOString(), steps: [], errors: [] } });
496	  for (const step of steps) {
497	    try {
498	      switch (step) {
499	        case "MOVE_IP_BACK": {
500	          if (plan.addressing.kind !== "DEDICATED") break;
501	          const a = plan.addressing;
502	          await ovhReleaseVirtualMac(a.targetService, a.address, cp.targetVirtualMac ?? null);
503	          await ovhMoveIp(a.address, a.sourceService);
504	          // The source's Virtual MAC object may or may not have survived the
505	          // move; make sure one exists and that the source VM carries it.
506	          const mac = await ovhEnsureVirtualMac(a.sourceService, a.address, `nxeon-${plan.sourceVmid}`);
507	          await srcConn.post(`/nodes/${srcConn.node}/qemu/${plan.sourceVmid}/config`, { net0: `virtio=${mac},bridge=vmbr0`, ipconfig0: `ip=${a.address}/32,gw=${a.sourceGateway}` });
508	          await db.dedicatedIp.updateMany({ where: { address: a.address }, data: { nodeId: source.id, virtualMac: mac } });
509	          break;
510	        }
511	        case "STOP_TARGET":
512	          await stopVm(tgtConn, plan.targetVmid);
513	          break;
514	        case "DESTROY_TARGET_VM":
515	          await destroyVmIdempotent(destroyHost(tgtConn), plan.targetVmid);
516	          break;
517	        case "DESTROY_TARGET_DATASET":
518	          await tgtZfs.destroyDataset(plan.targetDataset);
519	          break;
520	        case "DELETE_TARGET_SNIPPET":
521	          await deleteSnippet(target, plan.targetSnippetStorage, `nxeon-${plan.targetVmid}.yaml`);
522	          break;
523	        case "DELETE_SOURCE_INCREMENTAL_SNAPSHOT":
524	          if (cp.incrementalSnapshotName) await ctx.srcZfs.deleteSnapshot(plan.sourceDataset, cp.incrementalSnapshotName);
525	          break;
526	        case "START_SOURCE":
527	          await startVm(srcConn, plan.sourceVmid);
528	          break;
529	        case "RESTORE_DB_STATUS":
530	          await db.server.update({ where: { id: move.serverId }, data: { status: "RUNNING" } });
531	          break;
532	      }
533	      done.push(step);
534	    } catch (e: any) {
535	      errors.push(`${step}: ${String(e?.message ?? e).slice(0, 300)}`);
536	    }
537	  }
538	  // The live-pass Proxmox snapshot is harmless but pointless now.
539	  if (cp.liveSnapshotName) {
540	    try {
541	      const upid = await srcConn.del(`/nodes/${srcConn.node}/qemu/${plan.sourceVmid}/snapshot/${cp.liveSnapshotName}`);
542	      await srcConn.waitForTask(upid, 120_000);
543	    } catch {
544	      /* best-effort */
545	    }
546	  }
547	  await saveCheckpoints(move.id, { rollback: { startedAt: cp.rollback?.startedAt ?? new Date().toISOString(), finishedAt: new Date().toISOString(), steps: done, errors } });
548	  await appendLog(move.id, "ROLLBACK", errors.length ? `finished WITH ERRORS: ${errors.join(" | ")}` : `finished cleanly (${done.join(", ")})`);
549	  return { ok: errors.length === 0, errors };
550	}
