556	/** VM_MOVE handler. `progress` is worker/index.ts's reportJobProgress. */
557	export async function vmMoveJob(job: Job, progress: Progress): Promise<void> {
558	  const payload = (job.payload ?? {}) as Partial<VmMoveJobPayload>;
559	  if (!payload.vmMoveId) throw new Error("VM_MOVE job has no vmMoveId");
560	  let move = await db.vmMove.findUnique({ where: { id: payload.vmMoveId } });
561	  if (!move) throw new Error(`VmMove ${payload.vmMoveId} not found`);
562	  if (move.status === "DONE" || move.status === "CLEANED") return;
563	  if (move.status === "ROLLED_BACK" || move.status === "FAILED") {
564	    // Terminal: say so on every retry so the job ends FAILED with the reason,
565	    // rather than quietly DONE.
566	    throw new Error(move.error ?? `move is ${move.status}`);
567	  }
568	  if (SANDBOX) {
569	    await db.vmMove.update({ where: { id: move.id }, data: { status: "FAILED", error: "VM moves are not simulated in sandbox mode", finishedAt: new Date() } });
570	    throw new Error("VM moves are not simulated in sandbox mode");
571	  }
572	
573	  // ---- PREFLIGHT (always re-run on a fresh move; dry runs stop here) --------------
574	  if (!move.plan || move.phase === "PREFLIGHT") {
575	    await progress(job.id, 2, "Preflight…");
576	    const plan = await buildMovePlan({ serverId: move.serverId, targetNodeId: move.targetNodeId, allowDropSnapshots: !!(move.checkpoints as any)?.allowDropSnapshots });
577	    await db.vmMove.update({
578	      where: { id: move.id },
579	      data: {
580	        plan: plan as unknown as Prisma.InputJsonValue,
581	        targetVmid: plan.targetVmid || move.targetVmid,
582	        sourceVmid: plan.sourceVmid || move.sourceVmid,
583	        sourceNodeId: plan.sourceNodeId,
584	      },
585	    });
586	    const failed = plan.checks.filter((c) => !c.ok && c.blocking);
587	    if (move.dryRun) {
588	      await db.vmMove.update({ where: { id: move.id }, data: { status: "PLANNED", phase: "PREFLIGHT", finishedAt: new Date(), error: failed.length ? `preflight: ${failed.map((c) => c.detail).join("; ")}` : null } });
589	      await appendLog(move.id, "PREFLIGHT", `dry run: ${plan.ok ? "all blocking checks passed" : `${failed.length} blocking check(s) failed`}`);
590	      return;
591	    }
592	    if (!plan.ok) {
593	      const error = `preflight failed: ${failed.map((c) => `[${c.id}] ${c.detail}`).join("; ")}`.slice(0, 1900);
594	      await db.vmMove.update({ where: { id: move.id }, data: { status: "FAILED", error, finishedAt: new Date() } });
595	      await appendLog(move.id, "PREFLIGHT", error);
596	      throw new Error(error);
597	    }
598	    move = await db.vmMove.update({ where: { id: move.id }, data: { status: "RUNNING", phase: "SNAPSHOT_LIVE", startedAt: move.startedAt ?? new Date() } });
599	    await appendLog(move.id, "PREFLIGHT", `plan ok: ${plan.sourceNodeName} vmid ${plan.sourceVmid} → ${plan.targetNodeName} vmid ${plan.targetVmid} (${plan.addressing.kind}, ${(plan.sourceUsedBytes / 2 ** 30).toFixed(1)} GB, est. dark window ${plan.estimatedDowntimeSec}s)`);
600	  }
601	
602	  const plan = planOf(move)!;
603	  const [source, target] = await Promise.all([loadMoveNode(plan.sourceNodeId), loadMoveNode(plan.targetNodeId)]);
604	  if (!source || !target) throw new Error("source or target node row vanished");
605	  const ctx: Ctx = {
606	    job,
607	    move,
608	    plan,
609	    source,
610	    target,
611	    srcConn: pveFor(source),
612	    tgtConn: pveFor(target),
613	    srcZfs: zfsHostFor(source),
614	    tgtZfs: zfsHostFor(target),
615	    dedicated: plan.addressing.kind === "DEDICATED",
616	    progress,
617	  };
618	
619	  // Explicit operator rollback request (lib/vm-move/actions.ts requestVmMoveRollback).
620	  if ((cpOf(move) as any).rollbackRequested && rollbackAllowed(cpOf(move))) {
621	    const r = await rollback(ctx, "requested by operator");
622	    await db.vmMove.update({ where: { id: move.id }, data: { status: r.ok ? "ROLLED_BACK" : "FAILED", error: r.ok ? "rolled back on request" : `rollback errors: ${r.errors.join(" | ")}`.slice(0, 1900), finishedAt: new Date() } });
623	    throw new Error(r.ok ? "move rolled back on request" : `rollback incomplete: ${r.errors.join(" | ")}`);
624	  }
625	
626	  for (;;) {
627	    ctx.move = (await db.vmMove.findUnique({ where: { id: move.id } }))!;
628	    const cp = cpOf(ctx.move);
629	    const phase = nextPhase(cp, { dedicated: ctx.dedicated });
630	    if (phase === "DONE") {
631	      if (ctx.move.status !== "DONE") await db.vmMove.update({ where: { id: move.id }, data: { status: "DONE", phase: "DONE", finishedAt: new Date() } });
632	      await progress(job.id, 100, "Move complete");
633	      return;
634	    }
635	    await db.vmMove.update({ where: { id: move.id }, data: { phase } });
636	    try {
637	      await runPhase(ctx, phase);
638	    } catch (e: any) {
639	      const msg = String(e?.message ?? e).slice(0, 1500);
640	      await appendLog(move.id, phase, `FAILED: ${msg}`);
641	      const inDarkWindow = !!cp.sourceStoppedAt && !cp.committedAt;
642	      if (inDarkWindow) {
643	        // Customer is down: undo now rather than wait for a retry.
644	        const r = await rollback(ctx, `${phase} failed: ${msg}`);
645	        await db.vmMove.update({
646	          where: { id: move.id },
647	          data: { status: r.ok ? "ROLLED_BACK" : "FAILED", error: `${phase}: ${msg}${r.ok ? " (rolled back; source running again)" : ` — ROLLBACK INCOMPLETE: ${r.errors.join(" | ")}`}`.slice(0, 1900), finishedAt: new Date() },
648	        });
649	        if (!r.ok) {
650	          await db.notification.create({ data: { userId: move.requestedById ?? (await firstAdminId()), title: `VM move ${move.id} needs attention`, body: `Rollback incomplete after ${phase} failed: ${r.errors.join(" | ")}`.slice(0, 900), href: `/admin/ops` } }).catch(() => {});
651	        }
652	        throw new Error(`${phase} failed: ${msg}${r.ok ? " — rolled back" : " — rollback incomplete"}`);
653	      }
654	      const finalAttempt = job.attempts >= MOVE_MAX_ATTEMPTS;
655	      if (finalAttempt && !cp.committedAt) {
656	        // Source still running (we never reached STOP_SOURCE) but the worker
657	        // will not retry again: tidy up the target side so nothing is left
658	        // half-received, and finalise the row.
659	        const r = await rollback(ctx, `${phase} failed on the last attempt: ${msg}`);
660	        await db.vmMove.update({
661	          where: { id: move.id },
662	          data: { status: r.ok ? "ROLLED_BACK" : "FAILED", error: `${phase}: ${msg}${r.ok ? " (target side cleaned up)" : ` — cleanup errors: ${r.errors.join(" | ")}`}`.slice(0, 1900), finishedAt: new Date() },
663	        });
664	        throw new Error(`${phase} failed: ${msg}`);
665	      }
666	      if (finalAttempt && cp.committedAt) {
667	        // Post-commit remainder (NAT/DNS/notices) could not finish: the DB
668	        // already points at the target, so say exactly what is left to do.
669	        await db.vmMove.update({ where: { id: move.id }, data: { status: "FAILED", error: `post-commit ${phase} failed: ${msg} — the server IS live on the target; finish NAT sync / DNS / notice by hand`.slice(0, 1900), finishedAt: new Date() } });
670	        throw new Error(`post-commit ${phase} failed: ${msg}`);
671	      }
672	      // Before the dark window (or after commit): keep the row RUNNING and let
673	      // the worker's retry resume from the last checkpoint.
674	      await db.vmMove.update({ where: { id: move.id }, data: { error: `${phase}: ${msg}` } });
675	      throw e;
676	    }
677	  }
678	}
