685	/**
686	 * VM_MOVE_CLEANUP — destroy the stopped source VM of a DONE move. Refuses
687	 * unless the DB still says the target is live AND the target hypervisor
688	 * agrees, and unless `keepSourceUntil` has passed (or the payload forces it).
689	 */
690	export async function vmMoveCleanupJob(job: Job, progress: Progress): Promise<void> {
691	  const payload = (job.payload ?? {}) as Partial<VmMoveCleanupJobPayload> & { force?: boolean };
692	  if (!payload.vmMoveId) throw new Error("VM_MOVE_CLEANUP job has no vmMoveId");
693	  const move = await db.vmMove.findUnique({ where: { id: payload.vmMoveId } });
694	  if (!move) throw new Error(`VmMove ${payload.vmMoveId} not found`);
695	  if (move.status === "CLEANED") return;
696	  if (move.status !== "DONE") throw new Error(`cleanup refused: move is ${move.status}, not DONE`);
697	  if (move.keepSourceUntil && move.keepSourceUntil.getTime() > Date.now() && !payload.force) {
698	    throw new Error(`cleanup refused: source is kept until ${move.keepSourceUntil.toISOString()} (pass force to override)`);
699	  }
700	  const plan = planOf(move);
701	  const server = await db.server.findUnique({ where: { id: move.serverId }, select: { vmid: true, nodeId: true, hostname: true } });
702	  if (!server || server.vmid !== move.targetVmid || server.nodeId !== move.targetNodeId) {
703	    throw new Error(`cleanup refused: DB says server is vmid ${server?.vmid ?? "?"} on node ${server?.nodeId ?? "?"}, not the move's target ${move.targetVmid}/${move.targetNodeId}`);
704	  }
705	  const [source, target] = await Promise.all([loadMoveNode(move.sourceNodeId), loadMoveNode(move.targetNodeId)]);
706	  if (!source || !target) throw new Error("source or target node row vanished");
707	  const tgtConn = pveFor(target);
708	  const srcConn = pveFor(source);
709	  const targetState = await vmRunning(tgtConn, move.targetVmid);
710	  if (targetState === null) throw new Error(`cleanup refused: target vm ${move.targetVmid} is ABSENT on ${target.name}`);
711	  const sourceState = await vmRunning(srcConn, move.sourceVmid);
712	  if (sourceState === true) throw new Error(`cleanup refused: source vm ${move.sourceVmid} on ${source.name} is RUNNING — it must be stopped (someone started it after the move?)`);
713	
714	  await progress(job.id, 20, `Destroying source vm ${move.sourceVmid} on ${source.name}…`);
715	  const outcome = await destroyVmIdempotent(destroyHost(srcConn), move.sourceVmid);
716	  await appendLog(move.id, "CLEANUP", `source vm ${move.sourceVmid}: ${outcome.detail}`);
717	  await deleteSnippet(source, source.isPrimary ? (process.env.NXEON_SNIPPET_STORAGE ?? "backup") : source.storageHdd, `nxeon-${move.sourceVmid}.yaml`);
718	  if (plan?.addressing.kind === "DEDICATED" && plan.addressing.sourceService) {
719	    await ovhReleaseVirtualMac(plan.addressing.sourceService, plan.addressing.address, plan.addressing.sourceVirtualMac).catch((e) =>
720	      appendLog(move.id, "CLEANUP", `WARNING: could not release the source Virtual MAC: ${e?.message ?? e}`),
721	    );
722	  }
723	  await db.vmMove.update({ where: { id: move.id }, data: { status: "CLEANED", sourceCleanedAt: new Date() } });
724	  await db.auditLog.create({
725	    data: { userId: move.requestedById ?? null, action: "server.vm_move_cleanup", category: "server", target: server.hostname, detail: `destroyed source vmid ${move.sourceVmid} on ${source.name} (move ${move.id})` },
726	  });
727	  await progress(job.id, 100, "Source cleaned up");
728	}
