1	/**
2	 * VM move — PURE planning logic. No DB, no Proxmox, no network: everything
3	 * here takes plain facts in and returns plain decisions out, so it is covered
4	 * end to end by test/vm-move-plan.test.ts without root, a hypervisor or a
5	 * second node. The side-effecting halves (lib/vm-move/preflight.ts gathers the
6	 * facts, worker/vm-move.ts acts on the decisions) stay as thin as possible.
7	 *
8	 * Covers: fleet-wide-unique target VMID choice (never a recycled id), target
9	 * capacity verdicts from REAL usage (not just committed plan RAM), candidate
10	 * classification + ranking for the primary offload, the phase state machine a
11	 * resumed job walks, the target VM config derivation, the move-safe cloud-init
12	 * vendor snippet, dataset-name validation shared with the node-agent, and the
13	 * OVH IP-move destination check (the campus/region guard).
14	 */
15	import { MOVE_PHASES, type MoveCandidate, type MoveCheckpoints, type MoveClass, type MovePhase, type NodeCapacityFacts, type PreflightCheck } from "./types";
16	
17	// ---------------------------------------------------------------------------
18	// VMIDs
19	// ---------------------------------------------------------------------------
20	
21	/** Templates live here on every node — never allocate into it (CLAUDE.md). */
22	export const TEMPLATE_VMID_MIN = 9000;
23	export const TEMPLATE_VMID_MAX = 9999;
24	/** Lowest id Proxmox accepts. */
25	export const VMID_MIN = 100;
26	/** Company infrastructure VMs sit at 8000+ (nxeon-mail) and 9010 (relay); the
27	 *  customer fleet is allocated below this so a move never lands on an
28	 *  infrastructure-looking id. */
29	export const CUSTOMER_VMID_MAX = 7999;
30	
31	/**
32	 * Choose a BRAND-NEW vmid for the moved VM: strictly greater than every id the
33	 * fleet has ever seen in any of the sets handed in (live VMs on every node, the
34	 * DB's Server.vmid, archived servers, in-flight moves, backup archives on the
35	 * target). "Highest ever + 1" is what makes it impossible to recycle an id —
36	 * `pvesh get /cluster/nextid` returns the lowest FREE id, which on a
37	 * non-clustered fleet is almost always a destroyed VM's old number (the
38	 * 2026-09 "never reuse VMIDs" rule exists because recycled ids were found
39	 * live twice: a node offering an id a destroyed-but-still-in-DB server held,
40	 * and an id whose backup archives belonged to a previous tenant).
41	 *
42	 * The template band 9000–9999 is skipped (jumps to 10000), and ids above
43	 * CUSTOMER_VMID_MAX are ignored when computing the "highest customer id" so a
44	 * fleet whose only high id is nxeon-mail (8000) still allocates in the
45	 * customer band instead of jumping to 8001.
46	 */
47	export function pickMoveTargetVmid(sets: ReadonlyArray<Iterable<number>>): number {
48	  let highest = VMID_MIN - 1;
49	  const taken = new Set<number>();
50	  for (const set of sets) {
51	    for (const raw of set) {
52	      const id = Number(raw);
53	      if (!Number.isInteger(id) || id < VMID_MIN) continue;
54	      taken.add(id);
55	      if (id <= CUSTOMER_VMID_MAX && id > highest) highest = id;
56	    }
57	  }
58	  let candidate = highest + 1;
59	  for (let guard = 0; guard < 100_000; guard++, candidate++) {
60	    if (candidate >= TEMPLATE_VMID_MIN && candidate <= TEMPLATE_VMID_MAX) {
61	      candidate = TEMPLATE_VMID_MAX; // loop's ++ lands on 10000
62	      continue;
63	    }
64	    if (taken.has(candidate)) continue;
65	    return candidate;
66	  }
67	  throw new Error("pickMoveTargetVmid: could not find a free vmid");
68	}
69	
70	// ---------------------------------------------------------------------------
71	// Datasets
72	// ---------------------------------------------------------------------------
73	
74	/** A ZFS pool/dataset path as Proxmox's zfspool storage reports it in
75	 *  `pool` (e.g. `data`, `data/vms`, `rpool/data`). Shell-inert charset. */
76	export const ZFS_POOL_RE = /^[a-z][a-z0-9_-]{0,31}(\/[a-z][a-z0-9_-]{0,31}){0,3}$/;
77	/** The volume name Proxmox gives a VM disk. Only disk-0 is ever moved — a VM
78	 *  with more disks (block-storage volumes) is refused at preflight. */
79	export const VM_DISK_RE = /^vm-(\d{3,9})-disk-(\d{1,2})$/;
80	/** Snapshot names this engine creates: fixed prefix + the VmMove id (cuid). */
81	export const MOVE_SNAPSHOT_RE = /^nxmove[12]-[a-z0-9]{10,40}$/;
82	
83	export function datasetFor(pool: string, vmid: number, disk = 0): string {
84	  if (!ZFS_POOL_RE.test(pool)) throw new Error(`refusing unexpected ZFS pool name ${JSON.stringify(pool)}`);
85	  if (!Number.isInteger(vmid) || vmid < VMID_MIN) throw new Error(`refusing vmid ${vmid}`);
86	  return `${pool}/vm-${vmid}-disk-${disk}`;
87	}
88	
89	/** Validate a full dataset path `pool/vm-N-disk-M` and return its parts, or null. */
90	export function parseVmDataset(dataset: string): { pool: string; vmid: number; disk: number } | null {
91	  const slash = dataset.lastIndexOf("/");
92	  if (slash <= 0) return null;
93	  const pool = dataset.slice(0, slash);
94	  const name = dataset.slice(slash + 1);
95	  if (!ZFS_POOL_RE.test(pool)) return null;
96	  const m = VM_DISK_RE.exec(name);
97	  if (!m) return null;
98	  return { pool, vmid: Number(m[1]), disk: Number(m[2]) };
99	}
