108	// ---------------------------------------------------------------------------
109	// Capacity
110	// ---------------------------------------------------------------------------
111	
112	/** RAM a target host must still have REALLY available after the moved VM's
113	 *  full plan RAM is counted (the hypervisor, ZFS metadata, the agent and page
114	 *  cache all need room; a node with less than this is one burst from swap). */
115	export const TARGET_REAL_RAM_RESERVE_MB = Number(process.env.VM_MOVE_TARGET_RESERVE_MB ?? 4096);
116	/** Pool must keep this fraction free after the moved disk lands (ZFS
117	 *  performance collapses past ~80-85% full). */
118	export const TARGET_POOL_MIN_FREE_RATIO = 0.15;
119	/** Committed-RAM ceiling on the target after the move, as % of
120	 *  Node.capacityRamMB. Default 100: a move may fill a node up to the capacity
121	 *  the platform itself promises, never past it — real usage (above) is the
122	 *  other, independent gate. Lower it (e.g. 90, the scheduler's "critical")
123	 *  to keep provisioning headroom on the target. */
124	export const TARGET_COMMITTED_CRIT_PCT = Number(process.env.VM_MOVE_COMMITTED_MAX_PCT ?? 100);
125	
126	export function capacityChecks(target: NodeCapacityFacts, planRamMB: number, planVcpu: number, usedBytes: number, diskSizeGB: number): PreflightCheck[] {
127	  const out: PreflightCheck[] = [];
128	
129	  const availAfter = target.realAvailRamMB - planRamMB;
130	  out.push({
131	    id: "target-real-ram",
132	    ok: availAfter >= TARGET_REAL_RAM_RESERVE_MB,
133	    blocking: true,
134	    detail:
135	      `${target.name}: ${(target.realAvailRamMB / 1024).toFixed(1)} GB really available now, ` +
136	      `${(planRamMB / 1024).toFixed(1)} GB plan RAM moving in → ${(availAfter / 1024).toFixed(1)} GB left ` +
137	      `(needs ≥ ${(TARGET_REAL_RAM_RESERVE_MB / 1024).toFixed(1)} GB)`,
138	  });
139	
140	  const committedAfterPct = target.capacityRamMB > 0 ? ((target.committedRamMB + planRamMB) / target.capacityRamMB) * 100 : 100;
141	  out.push({
142	    id: "target-committed-ram",
143	    ok: committedAfterPct < TARGET_COMMITTED_CRIT_PCT,
144	    blocking: true,
145	    detail: `${target.name}: committed ${(target.committedRamMB / 1024).toFixed(0)} → ${((target.committedRamMB + planRamMB) / 1024).toFixed(0)} GB of ${(target.capacityRamMB / 1024).toFixed(0)} GB (${committedAfterPct.toFixed(0)}%, limit ${TARGET_COMMITTED_CRIT_PCT}%)`,
146	  });
147	
148	  // The zvol is sparse: what lands is roughly what the source really holds
149	  // (plus snapshot churn); the pool must still stay comfortably non-full.
150	  const freeAfter = target.poolFreeBytes - usedBytes;
151	  const freeAfterRatio = target.poolTotalBytes > 0 ? freeAfter / target.poolTotalBytes : 0;
152	  out.push({
153	    id: "target-pool-space",
154	    ok: freeAfter > 0 && freeAfterRatio >= TARGET_POOL_MIN_FREE_RATIO,
155	    blocking: true,
156	    detail: `${target.name}: pool ${(target.poolFreeBytes / 2 ** 30).toFixed(0)} GB free, disk really holds ${(usedBytes / 2 ** 30).toFixed(1)} GB (provisioned ${diskSizeGB} GB) → ${(freeAfter / 2 ** 30).toFixed(0)} GB free after (${(freeAfterRatio * 100).toFixed(0)}%, needs ≥ ${TARGET_POOL_MIN_FREE_RATIO * 100}%)`,
157	  });
158	
159	  // vCPU is normally oversold; warn (not block) past 4x threads or when the
160	  // target is already busy.
161	  const vcpuAfter = target.committedVcpu + planVcpu;
162	  const ratio = target.cpuThreads > 0 ? vcpuAfter / target.cpuThreads : 99;
163	  out.push({
164	    id: "target-cpu",
165	    ok: ratio <= 4 && target.cpuLoad < 0.7,
166	    blocking: false,
167	    detail: `${target.name}: ${vcpuAfter} vCPU on ${target.cpuThreads} threads after (${ratio.toFixed(1)}x), load ${(target.cpuLoad * 100).toFixed(0)}% now`,
168	  });
169	
170	  return out;
171	}
