176	
177	export type CandidateInput = {
178	  serverId: string;
179	  hostname: string;
180	  vmid: number | null;
181	  nodeId: string | null;
182	  status: string;
183	  planRamMB: number;
184	  planVcpu: number;
185	  diskGB: number;
186	  hasDedicatedIp: boolean;
187	  /** DedicatedIp.purpose === "INTERNAL" (owner-operated site, relay, hosting node). */
188	  internalIp: boolean;
189	  isFree: boolean;
190	  attachedVolumes: number;
191	  subdomain: string | null;
192	  forwardCount: number;
193	  gameFamily: string | null;
194	  realRssMB: number | null;
195	  /** Average kvm CPU% over the sample window when the caller measured it. */
196	  realCpuPct: number | null;
197	  /** Days until the term ends; null = never (free) / unknown. */
198	  daysToExpiry: number | null;
199	  autoRenew: boolean;
200	  /** Hostname/tag marks it as company infrastructure (nxeon-infra tag, no Server row…). */
201	  companyInfra: boolean;
202	};
203	
204	export function classifyCandidate(c: CandidateInput): { klass: MoveClass; reasons: string[]; impact: string } {
205	  const reasons: string[] = [];
206	  if (c.companyInfra) reasons.push("company infrastructure (not a customer server)");
207	  if (c.internalIp) reasons.push("dedicated IP is marked INTERNAL");
208	  if (!c.vmid) reasons.push("no VM yet");
209	  if (c.attachedVolumes > 0) reasons.push(`${c.attachedVolumes} block-storage volume(s) attached — only single-disk VMs move`);
210	  if (!["RUNNING", "STOPPED"].includes(c.status)) reasons.push(`status ${c.status}`);
211	  if (reasons.length) return { klass: "C_MUST_STAY", reasons, impact: "not movable by this engine" };
212	
213	  if (c.hasDedicatedIp) {
214	    return {
215	      klass: "A_DEDICATED_IP",
216	      reasons: ["public IP travels with the VM (OVH failover IP move + new Virtual MAC)"],
217	      impact: "no address change; a few minutes of downtime during cutover",
218	    };
219	  }
220	  const parts = ["public IP changes to the target node's IP; SSH/game ports keep their numbers"];
221	  if (c.subdomain) parts.push("Minecraft subdomain is repointed automatically (A+SRV)");
222	  if (c.forwardCount > 0) parts.push(`${c.forwardCount} port forward(s) recreated on the target`);
223	  return {
224	    klass: "B_NAT",
225	    reasons: parts,
226	    impact: c.subdomain ? "players using the subdomain see nothing; raw-IP users need the new address" : "customer must use the new IP (notice sent)",
227	  };
228	}
229	
230	/**
231	 * Relief = how much real pressure leaves the source when this VM goes. Real RSS
232	 * (what the kvm process actually holds) dominates when known; plan RAM is the
233	 * fallback. CPU% adds to it — the primary is CPU-saturated as well as
234	 * RAM-starved. Risk = what can go wrong / how long it takes: disk size (dark
235	 * window), a dedicated IP (an extra reversible-but-external step), a subdomain
236	 * (DNS propagation), imminent expiry with auto-renew off (why move something
237	 * about to be deleted). Score = relief − risk/2 so a big idle NAT VM outranks a
238	 * small busy dedicated one, with class A ties broken toward dedicated-IP
239	 * servers (zero customer-visible change).
240	 */
241	export function scoreCandidate(c: CandidateInput, klass: MoveClass): { relief: number; risk: number; score: number } {
242	  const ramMB = c.realRssMB ?? c.planRamMB;
243	  const relief = Math.min(100, (ramMB / 8192) * 70 + Math.min(30, (c.realCpuPct ?? 0) / 4));
244	  let risk = Math.min(40, (c.diskGB / 100) * 40);
245	  if (klass === "A_DEDICATED_IP") risk += 10;
246	  if (c.subdomain) risk += 10;
247	  if (c.forwardCount > 2) risk += 5;
248	  if (c.daysToExpiry !== null && c.daysToExpiry <= 7 && !c.autoRenew) risk += 25;
249	  if (klass === "C_MUST_STAY") risk = 100;
250	  const bonus = klass === "A_DEDICATED_IP" ? 5 : 0;
251	  const score = klass === "C_MUST_STAY" ? -1 : Math.round(relief - risk / 2 + bonus);
252	  return { relief: Math.round(relief), risk: Math.round(risk), score };
253	}
254	
255	export function rankMoveCandidates(inputs: readonly CandidateInput[]): MoveCandidate[] {
256	  const out: MoveCandidate[] = inputs.map((c) => {
257	    const { klass, reasons, impact } = classifyCandidate(c);
258	    const { relief, risk, score } = scoreCandidate(c, klass);
259	    return {
260	      serverId: c.serverId,
261	      hostname: c.hostname,
262	      vmid: c.vmid,
263	      nodeId: c.nodeId,
264	      klass,
265	      reasons,
266	      planRamMB: c.planRamMB,
267	      planVcpu: c.planVcpu,
268	      diskGB: c.diskGB,
269	      realRssMB: c.realRssMB,
270	      relief,
271	      risk,
272	      impact,
273	      score,
274	    };
275	  });
276	  // Movable first (by score desc), then must-stay; stable by hostname.
277	  return out.sort((a, b) => {
278	    const am = a.klass === "C_MUST_STAY" ? 1 : 0;
279	    const bm = b.klass === "C_MUST_STAY" ? 1 : 0;
280	    if (am !== bm) return am - bm;
281	    if (b.score !== a.score) return b.score - a.score;
282	    return a.hostname.localeCompare(b.hostname);
283	  });
284	}
