286	// ---------------------------------------------------------------------------
287	// Phase state machine
288	// ---------------------------------------------------------------------------
289	
290	/** Is phase `p` already complete according to the checkpoints? */
291	export function phaseComplete(p: MovePhase, cp: MoveCheckpoints, opts: { dedicated: boolean }): boolean {
292	  switch (p) {
293	    case "PREFLIGHT":
294	      return true; // a VmMove row with a plan exists by the time the worker runs
295	    case "SNAPSHOT_LIVE":
296	      return !!cp.liveSnapshotName;
297	    case "SEND_FULL":
298	      return !!cp.fullSentAt;
299	    case "STOP_SOURCE":
300	      return !!cp.sourceStoppedAt;
301	    case "SEND_INCREMENTAL":
302	      return !!cp.incrementalSentAt;
303	    case "CREATE_TARGET":
304	      return !!cp.targetVmCreated;
305	    case "MOVE_IP":
306	      return opts.dedicated ? !!cp.ipMovedAt : true;
307	    case "START_TARGET":
308	      return !!cp.targetVerified;
309	    case "COMMIT":
310	      return !!cp.committedAt;
311	    case "DONE":
312	      return !!cp.committedAt;
313	  }
314	}
315	
316	/** The first phase a (resumed) run still has to execute. */
317	export function nextPhase(cp: MoveCheckpoints, opts: { dedicated: boolean }): MovePhase {
318	  for (const p of MOVE_PHASES) {
319	    if (p === "PREFLIGHT") continue;
320	    if (!phaseComplete(p, cp, opts)) return p;
321	  }
322	  return "DONE";
323	}
324	
325	/** Phases that may be rolled back automatically (anything before COMMIT). Once
326	 *  COMMIT has run the DB points at the target; from there forward is the only
327	 *  safe direction and a human decides. */
328	export function rollbackAllowed(cp: MoveCheckpoints): boolean {
329	  return !cp.committedAt;
330	}
331	
332	/** What rollback must undo, in order, given what the checkpoints say exists.
333	 *  Pure so the exact inventory is testable; the worker executes each step and
334	 *  records successes/failures on `checkpoints.rollback`. */
335	export type RollbackStep =
336	  | "MOVE_IP_BACK" // OVH: route the IP back to the source service + recreate the source Virtual MAC
337	  | "STOP_TARGET"
338	  | "DESTROY_TARGET_VM" // target VM config + its disks (the received dataset)
339	  | "DESTROY_TARGET_DATASET" // received dataset when no VM config references it yet
340	  | "DELETE_TARGET_SNIPPET"
341	  | "DELETE_SOURCE_INCREMENTAL_SNAPSHOT"
342	  | "START_SOURCE"
343	  | "RESTORE_DB_STATUS";
344	export function rollbackSteps(cp: MoveCheckpoints, opts: { dedicated: boolean }): RollbackStep[] {
345	  const steps: RollbackStep[] = [];
346	  if (opts.dedicated && cp.ipMovedAt) steps.push("MOVE_IP_BACK");
347	  if (cp.targetStartedAt) steps.push("STOP_TARGET");
348	  if (cp.targetVmCreated) steps.push("DESTROY_TARGET_VM");
349	  else if (cp.fullSentAt) steps.push("DESTROY_TARGET_DATASET");
350	  if (cp.targetSnippetWritten) steps.push("DELETE_TARGET_SNIPPET");
351	  if (cp.incrementalSnapshotName) steps.push("DELETE_SOURCE_INCREMENTAL_SNAPSHOT");
352	  if (cp.sourceStoppedAt) steps.push("START_SOURCE");
353	  steps.push("RESTORE_DB_STATUS");
354	  return steps;
355	}
