361	/** Source config keys copied verbatim onto the target. Everything else is
362	 *  either regenerated (net0/ipconfig0/scsi0/ide2/cicustom/smbios1/vmgenid/
363	 *  meta/digest/snapshots) or must not travel (parent/snaptime/pending). */
364	export const CARRIED_CONFIG_KEYS = [
365	  "agent",
366	  "balloon",
367	  "bios",
368	  "boot",
369	  "ciuser",
370	  "cores",
371	  "cpu",
372	  "description",
373	  "hotplug",
374	  "kvm",
375	  "machine",
376	  "memory",
377	  "name",
378	  "nameserver",
379	  "numa",
380	  "onboot",
381	  "ostype",
382	  "protection",
383	  "scsihw",
384	  "searchdomain",
385	  "serial0",
386	  "sockets",
387	  "sshkeys",
388	  "tablet",
389	  "tags",
390	  "vga",
391	] as const;
392	
393	/** Keys whose presence means the VM is NOT a plain single-disk cloud-init
394	 *  guest this engine knows how to move. */
395	export const REFUSED_CONFIG_KEY_RE = /^(scsi[1-9]\d*|virtio\d+|sata\d+|ide[013]|efidisk\d+|tpmstate\d+|unused\d+|hostpci\d+|usb\d+|parent|lock)$/;
396	
397	export type SourceDiskInfo = { storage: string; volume: string; sizeGB: number; options: string };
398	
399	/** Parse `scsi0: vmdata:vm-109-disk-0,discard=on,size=25G`. */
400	export function parseScsi0(value: string): SourceDiskInfo | null {
401	  const [volid, ...rest] = String(value).split(",");
402	  const [storage, volume] = volid.split(":");
403	  if (!storage || !volume || !VM_DISK_RE.test(volume)) return null;
404	  const sizeOpt = rest.find((o) => o.startsWith("size="));
405	  const size = sizeOpt ? sizeOpt.slice(5) : "";
406	  let sizeGB = 0;
407	  if (/^\d+G$/.test(size)) sizeGB = Number(size.slice(0, -1));
408	  else if (/^\d+T$/.test(size)) sizeGB = Number(size.slice(0, -1)) * 1024;
409	  else if (/^\d+M$/.test(size)) sizeGB = Math.ceil(Number(size.slice(0, -1)) / 1024);
410	  const options = rest.filter((o) => !o.startsWith("size=")).join(",");
411	  return { storage, volume, sizeGB, options };
412	}
413	
414	/** Inspect a source config: which keys travel, which forbid the move, which
415	 *  snapshots exist (they are NOT carried — the customer would lose them). */
416	export function inspectSourceConfig(cfg: Record<string, unknown>): {
417	  carried: Record<string, string>;
418	  refusedKeys: string[];
419	  disk: SourceDiskInfo | null;
420	  hasCloudInitDrive: boolean;
421	  snapshotNames: string[];
422	} {
423	  const carried: Record<string, string> = {};
424	  const refusedKeys: string[] = [];
425	  let disk: SourceDiskInfo | null = null;
426	  let hasCloudInitDrive = false;
427	  for (const [k, v] of Object.entries(cfg)) {
428	    if (v === undefined || v === null) continue;
429	    if ((CARRIED_CONFIG_KEYS as readonly string[]).includes(k)) carried[k] = String(v);
430	    else if (k === "scsi0") disk = parseScsi0(String(v));
431	    else if (k === "ide2" && /cloudinit/.test(String(v))) hasCloudInitDrive = true;
432	    else if (REFUSED_CONFIG_KEY_RE.test(k)) refusedKeys.push(k);
433	  }
434	  const snapshotNames = Array.isArray((cfg as any).__snapshots) ? ((cfg as any).__snapshots as string[]) : [];
435	  return { carried, refusedKeys, disk, hasCloudInitDrive, snapshotNames };
436	}
437	
438	export type TargetNetwork =
439	  | { kind: "DEDICATED"; address: string; gateway: string; virtualMac: string; bridge: string }
440	  | { kind: "NAT"; privateIp: string; gateway: string; mac: string | null; bridge: string };
441	
442	/**
443	 * The config POSTed to create the target VM. The received dataset is attached
444	 * by volid (`<storage>:vm-<targetVmid>-disk-0` — Proxmox attaches an existing
445	 * volume when the name already carries the VM's own id); a fresh cloud-init
446	 * drive is created; `cicustom` points at the move-safe vendor snippet written
447	 * in the same phase; `onboot` is forced on (the source gets it forced OFF so a
448	 * source-node reboot can never resurrect a moved VM alongside its copy).
449	 */
450	export function buildTargetConfig(opts: {
451	  targetVmid: number;
452	  carried: Record<string, string>;
453	  disk: SourceDiskInfo;
454	  targetStorage: string;
455	  snippetStorage: string;
456	  network: TargetNetwork;
457	  cipassword: string | null;
458	}): Record<string, string | number> {
459	  const cfg: Record<string, string | number> = { ...opts.carried };
460	  cfg.vmid = opts.targetVmid;
461	  cfg.scsi0 = `${opts.targetStorage}:vm-${opts.targetVmid}-disk-0${opts.disk.options ? `,${opts.disk.options}` : ""}`;
462	  cfg.ide2 = `${opts.targetStorage}:cloudinit`;
463	  cfg.cicustom = `vendor=${opts.snippetStorage}:snippets/nxeon-${opts.targetVmid}.yaml`;
464	  cfg.onboot = 1;
465	  if (!cfg.scsihw) cfg.scsihw = "virtio-scsi-single";
466	  if (!cfg.boot) cfg.boot = "order=scsi0";
467	  if (opts.cipassword) cfg.cipassword = opts.cipassword;
468	  if (opts.network.kind === "DEDICATED") {
469	    cfg.net0 = `virtio=${opts.network.virtualMac},bridge=${opts.network.bridge}`;
470	    cfg.ipconfig0 = `ip=${opts.network.address}/32,gw=${opts.network.gateway}`;
471	  } else {
472	    cfg.net0 = opts.network.mac ? `virtio=${opts.network.mac},bridge=${opts.network.bridge}` : `virtio,bridge=${opts.network.bridge}`;
473	    cfg.ipconfig0 = `ip=${opts.network.privateIp}/24,gw=${opts.network.gateway}`;
474	  }
475	  return cfg;
476	}
477	
478	/** Extract the MAC from `virtio=BC:24:11:..,bridge=vmbr1`. */
479	export function macFromNet0(net0: string | undefined): string | null {
480	  const m = /(?:^|,)virtio=([0-9A-Fa-f]{2}(?::[0-9A-Fa-f]{2}){5})/.exec(String(net0 ?? ""));
481	  return m ? m[1] : null;
482	}
483	
484	/**
485	 * The vendor-data the moved VM boots with on its new node.
486	 *
487	 * WHY NOT the original per-VM snippet: Proxmox's NoCloud instance-id is a hash
488	 * of user-data + network-data, so the re-IP (or, for a dedicated IP, the new
489	 * gateway) makes cloud-init treat first boot on the target as a NEW INSTANCE
490	 * and re-run every per-instance module — including the original snippet's
491	 * `runcmd`, which would re-execute the game/app setup script against a server
492	 * that already has months of data on it, and `cc_ssh`, which by default
493	 * deletes and regenerates the host keys (every customer gets "REMOTE HOST
494	 * IDENTIFICATION HAS CHANGED"). This snippet keeps exactly the two things the
495	 * platform needs on every boot (guest agent, root SSH) and pins the host keys.
496	 */
497	export function moveSafeVendorSnippet(): string {
498	  return [
499	    "#cloud-config",
500	    "# Nxeon: post-move vendor data. Deliberately minimal — see lib/vm-move/plan.ts moveSafeVendorSnippet().",
501	    "ssh_deletekeys: false",
502	    "ssh_pwauth: true",
503	    "disable_root: false",
504	    "packages:",
505	    "  - qemu-guest-agent",
506	    "write_files:",
507	    "  - path: /etc/ssh/sshd_config.d/60-nxeon.conf",
508	    '    permissions: "0644"',
509	    "    content: |",
510	    "      PermitRootLogin yes",
511	    "      PasswordAuthentication yes",
512	    "runcmd:",
513	    "  - systemctl enable --now qemu-guest-agent",
514	    "  - systemctl restart ssh || systemctl restart sshd",
515	    "",
516	  ].join("\n");
517	}
