520	// Dedicated IP move — destination guard
521	// ---------------------------------------------------------------------------
522	
523	/** Shape of OVH `GET /ip/{ip}/move` (ip.Destinations). */
524	export type OvhMoveDestinations = { dedicatedServer?: Array<{ service: string; nexthop?: string[] }> };
525	
526	/**
527	 * May this IP be moved to `targetService`? OVH only lists destinations in the
528	 * same campus (a Singapore failover IP lists the three SGP boxes and NOT
529	 * nxeon-bhs1 — confirmed live 2026-10-01). This is the authoritative
530	 * same-zone check; the Node.region equality check is the cheap pre-filter.
531	 * A wrong-zone move is simply impossible through this path rather than
532	 * "possible but unusable".
533	 */
534	export function ipMoveDestinationAllowed(dest: OvhMoveDestinations | null | undefined, targetService: string): boolean {
535	  const list = dest?.dedicatedServer ?? [];
536	  return list.some((d) => d?.service === targetService);
537	}
538	
539	// ---------------------------------------------------------------------------
540	// Estimates
541	// ---------------------------------------------------------------------------
542	
543	/** Assumed sustained inter-node rate for the stream (bytes/s). OVH SGP boxes
544	 *  share a 1 Gbit/s uplink; zstd + the source's load make ~60 MB/s a sober
545	 *  planning figure. Override via env for a measured value. */
546	export const ASSUMED_LINK_BYTES_PER_SEC = Number(process.env.VM_MOVE_LINK_BPS ?? 60 * 1024 * 1024);
547	
548	export function estimateDurations(usedBytes: number, opts?: { linkBps?: number; incrementalRatio?: number }): { fullSendSec: number; downtimeSec: number } {
549	  const bps = opts?.linkBps ?? ASSUMED_LINK_BYTES_PER_SEC;
550	  const fullSendSec = Math.ceil(usedBytes / bps);
551	  // Dark window: shutdown (≤60s) + incremental (a few % of the disk changed
552	  // during the full send) + boot/agent/SSH verify (~60-90s).
553	  const incremental = usedBytes * (opts?.incrementalRatio ?? 0.03);
554	  const downtimeSec = 60 + Math.ceil(incremental / bps) + 90;
555	  return { fullSendSec, downtimeSec };
556	}
557	
558	/** Relief the primary gets from a batch, for the plan document: Σ real RSS
559	 *  (or plan RAM) and Σ vCPU. */
560	export function batchRelief(cands: readonly MoveCandidate[]): { ramMB: number; vcpu: number } {
561	  return cands.reduce(
562	    (acc, c) => ({ ramMB: acc.ramMB + (c.realRssMB ?? c.planRamMB), vcpu: acc.vcpu + c.planVcpu }),
563	    { ramMB: 0, vcpu: 0 },
564	  );
565	}
