15	 *  phase not yet checkpointed and continue from there. */
16	export const MOVE_PHASES = [
17	  "PREFLIGHT", // build + persist the plan (the only phase a dry run executes)
18	  "SNAPSHOT_LIVE", // consistent (guest-agent fs-freeze) Proxmox snapshot of the running source
19	  "SEND_FULL", // full zfs stream of that snapshot → target dataset vm-<targetVmid>-disk-0 (source still running)
20	  "STOP_SOURCE", // graceful shutdown of the source VM — start of the dark window
21	  "SEND_INCREMENTAL", // zfs snapshot of the now-quiescent source + incremental stream (small)
22	  "CREATE_TARGET", // target VM config (API) + move-safe cloud-init vendor snippet
23	  "MOVE_IP", // dedicated-IP servers only: OVH IP move + new Virtual MAC on the target (last reversible step)
24	  "START_TARGET", // start + verify guest agent / SSH
25	  "COMMIT", // DB cutover (nodeId, vmid, ipAddress), NAT reconcile, DNS resync, notices, audit
