1	/**
2	 * The ZFS seam for VM moves — the same shape lib/nat-rules.ts's NatHost gives
3	 * NAT: every host-level ZFS operation a move needs, as an interface with three
4	 * implementations and one place that picks between them:
5	 *
6	 *   - localZfsHost()  — the primary itself (the worker runs there as root;
7	 *                       `zfs` is a local child process, argv arrays only).
8	 *   - agentZfsHost()  — any non-primary node, over its node-agent's
9	 *                       /v1/zfs/* endpoints (node-agent v2). The architecture's
10	 *                       standing rule: host-level work on another node goes
11	 *                       through its agent, not SSH.
12	 *   - sshZfsHost()    — TRANSITION FALLBACK ONLY (VM_MOVE_TRANSPORT=ssh): root
13	 *                       SSH from the primary to the node, for the window until
14	 *                       every node's agent has been updated to v2. Same argv
15	 *                       discipline, same dataset/snapshot allowlists. Remove
16	 *                       once every node reports agent version ≥ 2.
17	 *
18	 * Streams are zstd-compressed on the wire in every implementation so a
19	 * local→agent, agent→agent or ssh→local pairing all interoperate.
20	 */
21	import { spawn } from "node:child_process";
22	import { PassThrough, type Readable } from "node:stream";
23	import { pipeline } from "node:stream/promises";
24	import {
25	  agentZfsDataset,
26	  agentZfsDeleteSnapshot,
27	  agentZfsDestroyDataset,
28	  agentZfsRecv,
29	  agentZfsSendStream,
30	  agentZfsSnapshot,
31	  type AgentNode,
32	} from "../node-agent";
33	import { MOVE_SNAPSHOT_RE, parseVmDataset } from "./plan";
34	
35	export type ZfsDatasetInfo =
36	  | { exists: false }
37	  | { exists: true; usedBytes: number; referencedBytes: number; volsizeBytes: number; snapshots: string[] };
38	
39	export type ZfsHost = {
40	  label: string;
41	  dataset(dataset: string): Promise<ZfsDatasetInfo>;
42	  snapshot(dataset: string, snap: string): Promise<void>;
43	  deleteSnapshot(dataset: string, snap: string): Promise<void>;
44	  /** Destroys the dataset and its snapshots. Implementations refuse a dataset whose vmid has a VM config on that host. */
45	  destroyDataset(dataset: string): Promise<void>;
46	  /** zstd-compressed `zfs send [-i @from] dataset@snap`. */
47	  sendStream(dataset: string, snap: string, from?: string | null): Promise<Readable>;
48	  /** `zstd -d | zfs receive -F -u dataset` fed from `body`. Resolves on exit 0. */
49	  recv(dataset: string, body: Readable): Promise<void>;
50	};
51	
52	function assertDataset(dataset: string): void {
53	  if (!parseVmDataset(dataset)) throw new Error(`refusing unexpected dataset name ${JSON.stringify(dataset)}`);
54	}
55	function assertSnap(snap: string): void {
56	  if (!MOVE_SNAPSHOT_RE.test(snap)) throw new Error(`refusing unexpected snapshot name ${JSON.stringify(snap)}`);
57	}
58	
59	type Runner = (argv: string[]) => Promise<string>;
60	type Spawner = (argv: string[]) => import("node:child_process").ChildProcess;
61	
62	function execArgv(cmd: string, args: string[], timeoutMs = 60_000): Promise<string> {
63	  return new Promise((resolve, reject) => {
64	    const child = spawn(cmd, args, { stdio: ["ignore", "pipe", "pipe"] });
65	    let out = "";
66	    let err = "";
67	    const timer = setTimeout(() => child.kill("SIGKILL"), timeoutMs);
68	    child.stdout.on("data", (d) => (out += d.toString()));
69	    child.stderr.on("data", (d) => (err += d.toString().slice(0, 2000)));
70	    child.on("error", (e) => {
71	      clearTimeout(timer);
72	      reject(e);
73	    });
74	    child.on("close", (code) => {
75	      clearTimeout(timer);
76	      if (code === 0) resolve(out);
77	      else reject(new Error(`${cmd} ${args.slice(0, 3).join(" ")}… exited ${code}: ${err.trim().slice(0, 400)}`));
78	    });
79	  });
80	}
81	
82	/**
83	 * Build a host out of two primitives: `run(argv)` executes `zfs …`/`test …`
84	 * and returns stdout; `spawnCmd(argv)` starts a long-running process whose
85	 * stdin/stdout are streams. Local and SSH differ only in how argv is wrapped.
86	 */
87	function commandZfsHost(label: string, run: Runner, spawnCmd: Spawner): ZfsHost {
88	  const vmConfigExists = async (vmid: number) => {
89	    try {
90	      await run(["test", "-e", `/etc/pve/qemu-server/${vmid}.conf`]);
91	      return true;
92	    } catch {
93	      return false;
94	    }
95	  };
96	  return {
97	    label,
98	    async dataset(dataset) {
99	      assertDataset(dataset);
100	      let line: string;
101	      try {
102	        line = await run(["zfs", "list", "-Hp", "-o", "used,referenced,volsize", dataset]);
103	      } catch (e: any) {
104	        if (/does not exist/.test(String(e?.message))) return { exists: false };
105	        throw e;
106	      }
107	      const [used, referenced, volsize] = line.trim().split(/\s+/).map(Number);
108	      const snapsRaw = await run(["zfs", "list", "-Hp", "-t", "snapshot", "-o", "name", "-d", "1", dataset]).catch(() => "");
109	      const snapshots = snapsRaw
110	        .split("\n")
111	        .map((s) => s.trim())
112	        .filter(Boolean)
113	        .map((s) => s.slice(s.indexOf("@") + 1));
114	      return { exists: true, usedBytes: used, referencedBytes: referenced, volsizeBytes: volsize, snapshots };
115	    },
116	    async snapshot(dataset, snap) {
117	      assertDataset(dataset);
118	      assertSnap(snap);
119	      await run(["zfs", "snapshot", `${dataset}@${snap}`]);
120	    },
121	    async deleteSnapshot(dataset, snap) {
122	      assertDataset(dataset);
123	      assertSnap(snap);
124	      try {
125	        await run(["zfs", "destroy", `${dataset}@${snap}`]);
126	      } catch (e: any) {
127	        if (!/does not exist/.test(String(e?.message))) throw e;
128	      }
129	    },
130	    async destroyDataset(dataset) {
131	      assertDataset(dataset);
132	      const { vmid } = parseVmDataset(dataset)!;
133	      if (await vmConfigExists(vmid)) {
134	        throw new Error(`refusing to destroy ${dataset}: vm ${vmid} has a config on ${label} — destroy it through Proxmox`);
135	      }
136	      try {
137	        await run(["zfs", "destroy", "-r", dataset]);
138	      } catch (e: any) {
139	        if (!/does not exist/.test(String(e?.message))) throw e;
140	      }
141	    },
142	    async sendStream(dataset, snap, from) {
143	      assertDataset(dataset);
144	      assertSnap(snap);
145	      if (from) assertSnap(from);
146	      const zfsArgs = ["zfs", "send", "-L", "-e", ...(from ? ["-i", `${dataset}@${from}`] : []), `${dataset}@${snap}`];
147	      const send = spawnCmd(zfsArgs);
148	      const zstd = spawn("nice", ["-n", "10", "zstd", "-3", "-q", "-T1"], { stdio: ["pipe", "pipe", "pipe"] });
149	      const out = new PassThrough();
150	      let sendErr = "";
151	      send.stderr?.on("data", (d) => (sendErr += d.toString().slice(0, 1000)));
152	      send.on("close", (code) => {
153	        if (code !== 0) out.destroy(new Error(`zfs send ${dataset}@${snap} exited ${code}: ${sendErr.trim()}`));
154	      });
155	      send.stdout!.pipe(zstd.stdin);
156	      zstd.stdout.pipe(out);
157	      zstd.on("close", (code) => {
158	        if (code !== 0) out.destroy(new Error(`zstd exited ${code}`));
159	      });
160	      return out;
161	    },
162	    async recv(dataset, body) {
163	      assertDataset(dataset);
164	      const { vmid } = parseVmDataset(dataset)!;
165	      if (await vmConfigExists(vmid)) throw new Error(`refusing zfs receive into ${dataset}: vm ${vmid} already has a config on ${label}`);
166	      const zstd = spawn("zstd", ["-d", "-q", "-T0"], { stdio: ["pipe", "pipe", "pipe"] });
167	      const recv = spawnCmd(["zfs", "receive", "-F", "-u", dataset]);
168	      let recvErr = "";
169	      recv.stderr?.on("data", (d) => (recvErr += d.toString().slice(0, 1000)));
170	      const done = new Promise<void>((resolve, reject) => {
171	        recv.on("error", reject);
172	        recv.on("close", (code) => (code === 0 ? resolve() : reject(new Error(`zfs receive exited ${code}: ${recvErr.trim()}`))));
173	      });
174	      zstd.stdout.pipe(recv.stdin!);
175	      try {
176	        await pipeline(body, zstd.stdin);
177	        await done;
178	      } catch (e) {
179	        try {
180	          zstd.kill("SIGKILL");
181	        } catch {
182	          /* gone */
183	        }
184	        try {
185	          recv.kill("SIGKILL");
186	        } catch {
187	          /* gone */
188	        }
189	        throw e;
190	      }
191	    },
192	  };
193	}
194	
195	/** The primary itself. */
196	export function localZfsHost(label = "primary"): ZfsHost {
197	  return commandZfsHost(
198	    label,
199	    (argv) => execArgv(argv[0], argv.slice(1)),
200	    (argv) => spawn(argv[0], argv.slice(1), { stdio: ["pipe", "pipe", "pipe"] }),
201	  );
202	}
203	
204	/** Transition fallback: root SSH to a node (argv only, BatchMode, no shell string). */
205	export function sshZfsHost(node: { name: string; publicIp: string }): ZfsHost {
206	  const base = ["-o", "BatchMode=yes", "-o", "ConnectTimeout=15", "-o", "StrictHostKeyChecking=accept-new", `root@${node.publicIp}`, "--"];
207	  return commandZfsHost(
208	    `${node.name} (ssh)`,
209	    (argv) => execArgv("ssh", [...base, ...argv]),
210	    (argv) => spawn("ssh", [...base, ...argv], { stdio: ["pipe", "pipe", "pipe"] }),
211	  );
212	}
213	
214	/** A non-primary node via its node-agent (v2). */
215	export function agentZfsHost(node: AgentNode): ZfsHost {
216	  return {
217	    label: `${node.name} (agent)`,
218	    dataset: (d) => {
219	      assertDataset(d);
220	      return agentZfsDataset(node, d);
221	    },
222	    snapshot: (d, s) => {
223	      assertDataset(d);
224	      assertSnap(s);
225	      return agentZfsSnapshot(node, d, s);
226	    },
227	    deleteSnapshot: (d, s) => {
228	      assertDataset(d);
229	      assertSnap(s);
230	      return agentZfsDeleteSnapshot(node, d, s);
231	    },
232	    destroyDataset: (d) => {
233	      assertDataset(d);
234	      return agentZfsDestroyDataset(node, d);
235	    },
236	    sendStream: (d, s, from) => {
237	      assertDataset(d);
238	      assertSnap(s);
239	      if (from) assertSnap(from);
240	      return agentZfsSendStream(node, d, s, from);
241	    },
242	    recv: (d, body) => {
243	      assertDataset(d);
244	      return agentZfsRecv(node, d, body);
245	    },
246	  };
247	}
248	
249	export type ZfsNodeRow = AgentNode & { isPrimary: boolean };
250	
251	/** Pick the implementation for a node. `VM_MOVE_TRANSPORT=ssh` forces the
252	 *  transition fallback for non-primary nodes; the default is the agent. */
253	export function zfsHostFor(node: ZfsNodeRow): ZfsHost {
254	  if (node.isPrimary) return localZfsHost(node.name);
255	  if ((process.env.VM_MOVE_TRANSPORT ?? "agent") === "ssh") return sshZfsHost(node);
256	  return agentZfsHost(node);
257	}
258	
259	/** Count bytes flowing through a stream (for progress reporting). */
260	export function meter(onBytes: (total: number) => void): PassThrough {
261	  let total = 0;
262	  const pt = new PassThrough();
263	  pt.on("data", (chunk: Buffer) => {
264	    total += chunk.length;
265	    onBytes(total);
266	  });
267	  return pt;
268	}
