77	/** `GET /storage/{id}` → the zfspool's dataset path (e.g. data/vms). */
78	export async function storagePool(conn: PveClient, storage: string): Promise<string> {
79	  const s = await conn.get(`/storage/${encodeURIComponent(storage)}`);
80	  if (s?.type !== "zfspool") throw new Error(`storage ${storage} on ${conn.node} is type ${s?.type ?? "?"}, not zfspool — only ZFS-backed disks can move`);
81	  const pool = String(s?.pool ?? "");
82	  if (!ZFS_POOL_RE.test(pool)) throw new Error(`storage ${storage} on ${conn.node} reports an unexpected pool path ${JSON.stringify(pool)}`);
83	  return pool;
84	}
