95	export async function nodeCapacityFacts(node: MoveNode, conn: PveClient, excludeServerId?: string): Promise<NodeCapacityFacts> {
96	  const [status, storage, servers] = await Promise.all([
97	    conn.get(`/nodes/${conn.node}/status`),
98	    conn.get(`/nodes/${conn.node}/storage/${encodeURIComponent(node.storageNvme)}/status`),
99	    db.server.findMany({
100	      where: { nodeId: node.id, status: { notIn: ["DELETING"] }, ...(excludeServerId ? { id: { not: excludeServerId } } : {}) },
101	      select: { plan: { select: { ramMB: true, cpuCores: true } }, gamePlan: { select: { ramMB: true, cpuCores: true } } },
102	    }),
103	  ]);
104	  const committedRamMB = servers.reduce((s, r) => s + (r.gamePlan?.ramMB ?? r.plan.ramMB), 0);
105	  const committedVcpu = servers.reduce((s, r) => s + (r.gamePlan?.cpuCores ?? r.plan.cpuCores), 0);
106	  const total = Number(status?.memory?.total ?? 0);
107	  // Proxmox's `memory.used` already excludes reclaimable cache (it is
108	  // MemTotal − MemAvailable on PVE 8/9), so total − used ≈ MemAvailable.
109	  const used = Number(status?.memory?.used ?? 0);
110	  return {
111	    nodeId: node.id,
112	    name: node.name,
113	    region: node.region,
114	    realAvailRamMB: Math.round((total - used) / (1024 * 1024)),
115	    realTotalRamMB: Math.round(total / (1024 * 1024)),
116	    committedRamMB,
117	    capacityRamMB: node.capacityRamMB,
118	    poolFreeBytes: Number(storage?.avail ?? 0),
119	    poolTotalBytes: Number(storage?.total ?? 0),
120	    cpuThreads: Number(status?.cpuinfo?.cpus ?? 0),
121	    committedVcpu,
122	    cpuLoad: Number(status?.cpu ?? 0),
123	  };
124	}
