126	/** Every vmid the fleet knows about — live on any node, in the DB (live or archived), reserved by a move. */
127	export async function fleetVmidSets(targetConn: PveClient, targetBackupStorage: string): Promise<{ sets: Iterable<number>[]; unreachable: string[] }> {
128	  const nodes = await db.node.findMany({ select: MOVE_NODE_SELECT });
129	  const unreachable: string[] = [];
130	  const live = await Promise.all(
131	    nodes.map(async (n) => {
132	      try {
133	        const res: any[] = await pveFor(n).get("/cluster/resources", { type: "vm" });
134	        return (res ?? []).map((r) => Number(r?.vmid)).filter(Number.isInteger);
135	      } catch {
136	        unreachable.push(n.name);
137	        return [] as number[];
138	      }
139	    }),
140	  );
141	  const [dbVmids, archivedRows, moves] = await Promise.all([
142	    db.server.findMany({ where: { vmid: { not: null } }, select: { vmid: true } }),
143	    db.serverArchive.findMany({ where: { vmid: { not: null } }, select: { vmid: true } }),
144	    db.vmMove.findMany({ select: { sourceVmid: true, targetVmid: true } }),
145	  ]);
146	  let archivedOnTarget = new Set<number>();
147	  try {
148	    archivedOnTarget = await archivedVmids(targetConn, targetBackupStorage);
149	  } catch {
150	    unreachable.push(`${targetConn.node} backup storage ${targetBackupStorage}`);
151	  }
152	  const sets: Iterable<number>[] = [
153	    ...live,
154	    dbVmids.map((r) => r.vmid!),
155	    archivedRows.map((r) => r.vmid!),
156	    moves.flatMap((m) => [m.sourceVmid, m.targetVmid]),
157	    archivedOnTarget,
158	  ];
159	  return { sets, unreachable };
160	}
