162	/** First free private IP in the target's range (not claimed — COMMIT claims via lib/ipam). */
163	export async function planTargetPrivateIp(targetNodeId: string): Promise<{ ip: string; gateway: string }> {
164	  const range = await ipamRange(targetNodeId);
165	  const rows = await db.server.findMany({ where: { ipAddress: { startsWith: range.subnetPrefix } }, select: { ipAddress: true } });
166	  const used = new Set(rows.map((r) => r.ipAddress!));
167	  for (let i = range.ipStart; i <= range.ipEnd; i++) {
168	    const ip = `${range.subnetPrefix}${i}`;
169	    if (!used.has(ip)) return { ip, gateway: gatewayIp(range.subnetPrefix) };
170	  }
171	  throw new Error(`IP pool exhausted on target node ${targetNodeId}`);
172	}
