181	/**
182	 * Build the plan. Never throws for a "no" — every refusal is a failed blocking
183	 * check in `plan.checks` so the operator sees ALL the reasons at once. Only a
184	 * genuinely unusable request (unknown server/node) throws.
185	 */
186	export async function buildMovePlan(input: PreflightInput): Promise<MovePlan> {
187	  const server = await loadMoveServer(input.serverId);
188	  if (!server) throw new Error(`server ${input.serverId} not found`);
189	  const target = await loadMoveNode(input.targetNodeId);
190	  if (!target) throw new Error(`target node ${input.targetNodeId} not found`);
191	  const source = server.node ?? (await db.node.findFirst({ where: { isPrimary: true }, select: MOVE_NODE_SELECT }));
192	  if (!source) throw new Error("server has no node and no primary node exists");
193	
194	  const checks: PreflightCheck[] = [];
195	  const check = (id: string, ok: boolean, detail: string, blocking = true) => checks.push({ id, ok, blocking, detail });
196	
197	  // ---- server-side eligibility ------------------------------------------------
198	  check("different-node", source.id !== target.id, source.id === target.id ? "target is the server's current node" : `${source.name} → ${target.name}`);
199	  check("target-enabled", target.enabled && target.status === "ONLINE", `${target.name}: enabled=${target.enabled} status=${target.status}`);
200	  check("server-has-vm", !!server.vmid, server.vmid ? `vmid ${server.vmid}` : "server has no VM yet");
201	  check("server-status", ["RUNNING", "STOPPED"].includes(server.status), `status ${server.status}`);
202	  const volumes = await db.volume.count({ where: { serverId: server.id } });
203	  check("no-volumes", volumes === 0, volumes ? `${volumes} block-storage volume(s) pinned — only single-disk VMs move` : "no block-storage volumes");
204	  const inflight = await db.job.count({ where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] }, type: { notIn: ["VM_MOVE"] } } });
205	  check("no-other-jobs", inflight === 0, inflight ? `${inflight} other job(s) queued/running for this server` : "no other jobs in flight");
206	  const activeMoves = await db.vmMove.count({ where: { serverId: server.id, status: { in: ["RUNNING"] } } });
207	  check("no-active-move", activeMoves === 0, activeMoves ? "a move is already running for this server" : "no other move running");
208	  const internal = server.dedicatedIp?.purpose === "INTERNAL";
209	  check("not-internal", !internal, internal ? "dedicated IP is marked INTERNAL (company infrastructure)" : "customer server");
210	
211	  const planRamMB = server.gamePlan?.ramMB ?? server.plan.ramMB;
212	  const planVcpu = server.gamePlan?.cpuCores ?? server.plan.cpuCores;
213	
214	  // ---- source VM facts ----------------------------------------------------------
215	  const srcConn = pveFor(source);
216	  const tgtConn = pveFor(target);
217	  let carried: Record<string, string> = {};
218	  let diskSizeGB = server.gamePlan?.diskGB ?? server.plan.diskGB;
219	  let sourceStorage = source.storageNvme;
220	  let sourcePool = "";
221	  let targetPool = "";
222	  let sourceUsedBytes = 0;
223	  let sourceDataset = "";
224	  let targetDataset = "";
225	  let snapshotNames: string[] = [];
226	  if (server.vmid) {
227	    try {
228	      const cfg = await srcConn.get(`/nodes/${srcConn.node}/qemu/${server.vmid}/config`);
229	      const snaps: any[] = await srcConn.get(`/nodes/${srcConn.node}/qemu/${server.vmid}/snapshot`).catch(() => []);
230	      snapshotNames = (snaps ?? []).map((s) => String(s?.name)).filter((n) => n && n !== "current");
231	      const insp = inspectSourceConfig(cfg ?? {});
232	      carried = insp.carried;
233	      check("single-disk-config", insp.refusedKeys.length === 0, insp.refusedKeys.length ? `config has ${insp.refusedKeys.join(", ")} — only a plain scsi0 + cloud-init VM moves` : "plain scsi0 + cloud-init drive");
234	      check("has-scsi0", !!insp.disk, insp.disk ? `scsi0 = ${insp.disk.storage}:${insp.disk.volume} (${insp.disk.sizeGB} GB)` : "no scsi0 disk found");
235	      check("has-cloudinit-drive", insp.hasCloudInitDrive, insp.hasCloudInitDrive ? "cloud-init drive present (re-IP is possible)" : "no cloud-init drive — the guest's network could not be re-pointed");
236	      check(
237	        "no-snapshots",
238	        snapshotNames.length === 0 || !!input.allowDropSnapshots,
239	        snapshotNames.length ? `${snapshotNames.length} Proxmox snapshot(s) (${snapshotNames.join(", ")}) would NOT be carried over${input.allowDropSnapshots ? " — accepted by the operator" : ""}` : "no snapshots to lose",
240	      );
241	      if (insp.disk) {
242	        sourceStorage = insp.disk.storage;
243	        if (insp.disk.sizeGB) diskSizeGB = insp.disk.sizeGB;
244	        sourcePool = await storagePool(srcConn, sourceStorage);
245	        sourceDataset = `${sourcePool}/${insp.disk.volume}`;
246	        const zfs = zfsHostFor(source);
247	        const info = await zfs.dataset(sourceDataset);
248	        check("source-dataset", info.exists, info.exists ? `${sourceDataset}: ${(info.usedBytes / 2 ** 30).toFixed(1)} GB used of ${(info.volsizeBytes / 2 ** 30).toFixed(0)} GB` : `${sourceDataset} not found via ${zfs.label}`);
249	        if (info.exists) sourceUsedBytes = info.usedBytes;
250	      }
251	    } catch (e: any) {
252	      check("source-readable", false, `could not read the source VM: ${e?.message ?? e}`);
253	    }
254	  }
255	
256	  // ---- target facts -------------------------------------------------------------
257	  let targetFacts: NodeCapacityFacts | null = null;
258	  try {
259	    targetPool = await storagePool(tgtConn, target.storageNvme);
260	    targetFacts = await nodeCapacityFacts(target, tgtConn);
261	    checks.push(...capacityChecks(targetFacts, planRamMB, planVcpu, sourceUsedBytes, diskSizeGB));
262	  } catch (e: any) {
263	    check("target-readable", false, `could not read the target node: ${e?.message ?? e}`);
264	  }
265	  if (!target.isPrimary) {
266	    try {
267	      const h = await agentHealth(target);
268	      const transport = process.env.VM_MOVE_TRANSPORT ?? "agent";
269	      check("target-agent", !!h?.ok && ((h.version ?? 1) >= 2 || transport === "ssh"), `node-agent on ${target.name}: ok=${!!h?.ok} version=${h?.version ?? 1}${(h?.version ?? 1) < 2 ? " (v2 required for the zfs transport; VM_MOVE_TRANSPORT=ssh is the fallback)" : ""}`);
270	    } catch (e: any) {
271	      check("target-agent", (process.env.VM_MOVE_TRANSPORT ?? "agent") === "ssh", `node-agent on ${target.name} unreachable: ${e?.message ?? e}`);
272	    }
273	  }
274	  if (!source.isPrimary) {
275	    try {
276	      const h = await agentHealth(source);
277	      const transport = process.env.VM_MOVE_TRANSPORT ?? "agent";
278	      check("source-agent", !!h?.ok && ((h.version ?? 1) >= 2 || transport === "ssh"), `node-agent on ${source.name}: ok=${!!h?.ok} version=${h?.version ?? 1}`);
279	    } catch (e: any) {
280	      check("source-agent", (process.env.VM_MOVE_TRANSPORT ?? "agent") === "ssh", `node-agent on ${source.name} unreachable: ${e?.message ?? e}`);
281	    }
282	  }
283	
284	  // ---- target vmid: brand-new, fleet-wide ----------------------------------------
285	  let targetVmid = 0;
286	  try {
287	    const { sets, unreachable } = await fleetVmidSets(tgtConn, backupStorageFor(target));
288	    targetVmid = pickMoveTargetVmid(sets);
289	    check("fleet-vmid-visibility", unreachable.length === 0, unreachable.length ? `could not list VMs on: ${unreachable.join(", ")} — a brand-new id cannot be guaranteed` : `every node answered; new vmid ${targetVmid}`);
290	    if (targetPool) targetDataset = datasetFor(targetPool, targetVmid);
291	    const existing = targetDataset ? await zfsHostFor(target).dataset(targetDataset).catch(() => null) : null;
292	    check("target-dataset-free", !existing || !existing.exists, existing?.exists ? `${targetDataset} already exists on ${target.name}` : `${targetDataset || "(target dataset)"} is free`);
293	  } catch (e: any) {
294	    check("fleet-vmid", false, `could not allocate a target vmid: ${e?.message ?? e}`);
295	  }
296	
297	  // ---- addressing ---------------------------------------------------------------
298	  let addressing: MoveAddressing;
299	  let targetBridge = "vmbr0";
300	  if (server.dedicatedIp && !internal) {
301	    const addr = server.dedicatedIp.address;
302	    const ovhBoth = source.provider === "OVH" && target.provider === "OVH";
303	    check("ip-provider", ovhBoth, ovhBoth ? "OVH → OVH (failover IP move supported)" : `dedicated-IP moves are OVH→OVH only (source ${source.provider}, target ${target.provider})`);
304	    check("same-region", source.region === target.region, `${source.region} → ${target.region}`);
305	    check("provider-service-ids", !!source.providerServerId && !!target.providerServerId, `source service ${source.providerServerId ?? "?"}, target service ${target.providerServerId ?? "?"}`);
306	    if (ovhBoth && source.providerServerId && target.providerServerId) {
307	      try {
308	        const r = await ovhIpMovePreflight(addr, source.providerServerId, target.providerServerId);
309	        check("ovh-ip-move-allowed", r.ok, r.detail);
310	      } catch (e: any) {
311	        check("ovh-ip-move-allowed", false, `OVH API: ${e?.message ?? e}`);
312	      }
313	    }
314	    addressing = {
315	      kind: "DEDICATED",
316	      address: addr,
317	      sourceGateway: ovhGatewayOf(source.publicIp),
318	      targetGateway: ovhGatewayOf(target.publicIp),
319	      sourceService: source.providerServerId ?? "",
320	      targetService: target.providerServerId ?? "",
321	      sourceVirtualMac: server.dedicatedIp.virtualMac,
322	    };
323	  } else {
324	    targetBridge = target.bridge;
325	    let planned = { ip: "", gateway: gatewayIp(target.subnetPrefix) };
326	    try {
327	      planned = await planTargetPrivateIp(target.id);
328	      check("target-private-ip", true, `planned ${planned.ip} (gw ${planned.gateway}); claimed atomically at COMMIT`);
329	    } catch (e: any) {
330	      check("target-private-ip", false, `${e?.message ?? e}`);
331	    }
332	    check("public-address-change", true, `public IP changes ${source.publicIp} → ${target.publicIp}; SSH port ${server.sshPort ?? "—"} and ${server.portForwards.length} forward(s) keep their numbers${server.subdomain ? `; subdomain ${server.subdomain} is repointed` : ""}`, false);
333	    addressing = {
334	      kind: "NAT",
335	      sourcePrivateIp: server.ipAddress ?? "",
336	      targetPrivateIpPlanned: planned.ip,
337	      targetGateway: planned.gateway,
338	      sshPort: server.sshPort,
339	      forwardPorts: server.portForwards.map((f) => f.publicPort),
340	      sourcePublicIp: source.publicIp,
341	      targetPublicIp: target.publicIp,
342	    };
343	  }
344	
345	  const est = estimateDurations(sourceUsedBytes);
346	  const ok = checks.every((c) => c.ok || !c.blocking);
347	  return {
348	    version: 1,
349	    serverId: server.id,
350	    hostname: server.hostname,
351	    sourceNodeId: source.id,
352	    sourceNodeName: source.name,
353	    targetNodeId: target.id,
354	    targetNodeName: target.name,
355	    sourceVmid: server.vmid ?? 0,
356	    targetVmid,
357	    planRamMB,
358	    planVcpu,
359	    diskSizeGB,
360	    sourceUsedBytes,
361	    sourceDataset,
362	    targetDataset,
363	    sourceStorage,
364	    targetStorage: target.storageNvme,
365	    targetSnippetStorage: snippetStorageFor(target),
366	    targetBridge,
367	    addressing,
368	    carriedConfig: carried,
369	    target: targetFacts ?? {
370	      nodeId: target.id,
371	      name: target.name,
372	      region: target.region,
373	      realAvailRamMB: 0,
374	      realTotalRamMB: 0,
375	      committedRamMB: 0,
376	      capacityRamMB: target.capacityRamMB,
377	      poolFreeBytes: 0,
378	      poolTotalBytes: 0,
379	      cpuThreads: 0,
380	      committedVcpu: 0,
381	      cpuLoad: 0,
382	    },
383	    checks,
384	    ok,
385	    estimatedDowntimeSec: est.downtimeSec,
386	    estimatedFullSendSec: est.fullSendSec,
387	    createdAt: new Date().toISOString(),
388	  };
389	}
