391	/** OVH's failover gateway convention for the node that hosts the VM: <node /24>.254. */
392	function ovhGatewayOf(nodePublicIp: string): string {
393	  const p = nodePublicIp.split(".");
394	  return p.length === 4 ? `${p[0]}.${p[1]}.${p[2]}.254` : ovhGateway();
395	}
