3	/**
4	 * VM move — admin server actions. This is the interface the admin ops UI
5	 * (agent A2's app/admin/ops) calls; the contract is documented in
6	 * docs/VM-MOVE.md. Every mutation is gated by requireArea("fleet"), audited,
7	 * idempotent where it can be, and enqueues a Job — the web app never touches
8	 * Proxmox, ZFS or OVH directly (that is worker/vm-move.ts's job).
9	 */
10	import { z } from "zod";
11	import type { Prisma } from "@prisma/client";
12	import { db } from "@/lib/db";
13	import { requireArea } from "@/lib/rbac";
14	import { recordAudit } from "@/lib/audit";
15	import { withServerJobLock } from "@/lib/job-guard";
16	import { buildMovePlan } from "./preflight";
17	import { moveCandidatesForNode, type RealUsageByVmid } from "./candidates";
18	import type { MoveCandidate, MovePlan } from "./types";
19	
20	const idSchema = z.string().min(5).max(64).regex(/^[a-z0-9]+$/i);
21	
22	export type RequestVmMoveInput = {
23	  serverId: string;
24	  targetNodeId: string;
25	  /** Preflight only: builds + stores the plan, touches nothing. */
26	  dryRun?: boolean;
27	  /** Free-text operator reason, stored on the VmMove row and in the audit log. */
28	  reason?: string;
29	  /** Accept that the VM's Proxmox snapshots are not carried over. */
30	  allowDropSnapshots?: boolean;
31	};
32	
33	export type RequestVmMoveResult = { ok: true; vmMoveId: string; jobId: string } | { ok: false; error: string };
34	
35	/**
36	 * Plan (dryRun) or execute a move. Returns the VmMove id to poll with
37	 * getVmMove(); the job runs on the worker and the row's `phase`/`log`/`plan`
38	 * fill in as it goes. Refused when another job or move is in flight for the
39	 * server (same per-server lock every other server action uses).
40	 */
41	export async function requestVmMove(input: RequestVmMoveInput): Promise<RequestVmMoveResult> {
42	  const admin = await requireArea("fleet");
43	  const parsed = z
44	    .object({
45	      serverId: idSchema,
46	      targetNodeId: idSchema,
47	      dryRun: z.boolean().optional(),
48	      reason: z.string().max(500).optional(),
49	      allowDropSnapshots: z.boolean().optional(),
50	    })
51	    .safeParse(input);
52	  if (!parsed.success) return { ok: false, error: "Invalid request." };
53	  const { serverId, targetNodeId, dryRun = false, reason, allowDropSnapshots = false } = parsed.data;
54	
55	  const server = await db.server.findUnique({ where: { id: serverId }, select: { id: true, hostname: true, vmid: true, nodeId: true, status: true } });
56	  if (!server) return { ok: false, error: "Server not found." };
57	  const target = await db.node.findUnique({ where: { id: targetNodeId }, select: { id: true, name: true, enabled: true } });
58	  if (!target) return { ok: false, error: "Target node not found." };
59	  if (server.nodeId === target.id) return { ok: false, error: "That is already the server's node." };
60	  if (!server.vmid) return { ok: false, error: "The server has no VM yet." };
61	
62	  const sourceNodeId = server.nodeId ?? (await db.node.findFirst({ where: { isPrimary: true }, select: { id: true } }))?.id;
63	  if (!sourceNodeId) return { ok: false, error: "The server has no node." };
64	
65	  const result = await withServerJobLock(serverId, async (tx) => {
66	    const pending = await tx.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
67	    if (pending > 0) return { ok: false as const, error: "Another job is already in flight for this server." };
68	    const running = await tx.vmMove.count({ where: { serverId, status: "RUNNING" } });
69	    if (running > 0) return { ok: false as const, error: "A move is already running for this server." };
70	    const move = await tx.vmMove.create({
71	      data: {
72	        serverId,
73	        sourceNodeId,
74	        targetNodeId: target.id,
75	        sourceVmid: server.vmid!,
76	        targetVmid: 0, // allocated at preflight
77	        dryRun,
78	        reason: reason?.trim() || null,
79	        requestedById: admin.id,
80	        checkpoints: (allowDropSnapshots ? { allowDropSnapshots: true } : {}) as Prisma.InputJsonValue,
81	      },
82	      select: { id: true },
83	    });
84	    const job = await tx.job.create({ data: { type: "VM_MOVE", serverId, payload: { vmMoveId: move.id } }, select: { id: true } });
85	    return { ok: true as const, vmMoveId: move.id, jobId: job.id };
86	  });
87	  if (result.ok) {
88	    await recordAudit(admin.id, dryRun ? "server.vm_move.plan" : "server.vm_move.request", `${server.hostname} → ${target.name} move=${result.vmMoveId}${reason ? ` reason=${reason.trim().slice(0, 120)}` : ""}`);
89	  }
90	  return result;
91	}
