93	/** Preflight WITHOUT creating a VmMove row or a job — for a live "what would happen" panel. Read-only. */
94	export async function previewVmMove(serverId: string, targetNodeId: string, allowDropSnapshots = false): Promise<{ ok: true; plan: MovePlan } | { ok: false; error: string }> {
95	  await requireArea("fleet");
96	  if (!idSchema.safeParse(serverId).success || !idSchema.safeParse(targetNodeId).success) return { ok: false, error: "Invalid request." };
97	  try {
98	    const plan = await buildMovePlan({ serverId, targetNodeId, allowDropSnapshots });
99	    return { ok: true, plan };
100	  } catch (e: any) {
101	    return { ok: false, error: String(e?.message ?? e).slice(0, 300) };
102	  }
103	}
