105	/** Destroy the stopped source VM of a DONE move (after keepSourceUntil unless `force`). */
106	export async function requestVmMoveCleanup(vmMoveId: string, opts?: { force?: boolean }): Promise<{ ok: true; jobId: string } | { ok: false; error: string }> {
107	  const admin = await requireArea("fleet");
108	  if (!idSchema.safeParse(vmMoveId).success) return { ok: false, error: "Invalid request." };
109	  const move = await db.vmMove.findUnique({ where: { id: vmMoveId }, select: { id: true, serverId: true, status: true, keepSourceUntil: true, server: { select: { hostname: true } } } });
110	  if (!move) return { ok: false, error: "Move not found." };
111	  if (move.status !== "DONE") return { ok: false, error: `Only a DONE move can be cleaned up (this one is ${move.status}).` };
112	  if (move.keepSourceUntil && move.keepSourceUntil.getTime() > Date.now() && !opts?.force) {
113	    return { ok: false, error: `The source VM is kept until ${move.keepSourceUntil.toISOString().slice(0, 10)}; pass force to override.` };
114	  }
115	  const existing = await db.job.findFirst({ where: { type: "VM_MOVE_CLEANUP", status: { in: ["QUEUED", "RUNNING"] }, payload: { path: ["vmMoveId"], equals: vmMoveId } }, select: { id: true } });
116	  if (existing) return { ok: true, jobId: existing.id };
117	  const job = await db.job.create({ data: { type: "VM_MOVE_CLEANUP", serverId: move.serverId, payload: { vmMoveId, force: !!opts?.force } }, select: { id: true } });
118	  await recordAudit(admin.id, "server.vm_move.cleanup", `${move.server.hostname} move=${vmMoveId}${opts?.force ? " force" : ""}`);
119	  return { ok: true, jobId: job.id };
120	}
121	
122	/** Ask a RUNNING move (not yet committed) to roll back at its next step. */
123	export async function requestVmMoveRollback(vmMoveId: string): Promise<{ ok: true; jobId: string } | { ok: false; error: string }> {
124	  const admin = await requireArea("fleet");
125	  if (!idSchema.safeParse(vmMoveId).success) return { ok: false, error: "Invalid request." };
126	  const move = await db.vmMove.findUnique({ where: { id: vmMoveId }, select: { id: true, serverId: true, status: true, checkpoints: true, server: { select: { hostname: true } } } });
127	  if (!move) return { ok: false, error: "Move not found." };
128	  if (move.status !== "RUNNING") return { ok: false, error: `Only a RUNNING move can be rolled back (this one is ${move.status}).` };
129	  const cp = (move.checkpoints as Record<string, unknown> | null) ?? {};
130	  if (cp.committedAt) return { ok: false, error: "This move is already committed — the database points at the new node; roll forward instead." };
131	  await db.vmMove.update({ where: { id: vmMoveId }, data: { checkpoints: { ...cp, rollbackRequested: true } as Prisma.InputJsonValue } });
132	  // The running job notices the flag at its next phase boundary; if the job
133	  // is between attempts (QUEUED), the re-queued job picks it up immediately.
134	  const job = await db.job.findFirst({ where: { type: "VM_MOVE", payload: { path: ["vmMoveId"], equals: vmMoveId } }, orderBy: { createdAt: "desc" }, select: { id: true, status: true } });
135	  let jobId = job?.id ?? "";
136	  if (!job || job.status === "DONE" || job.status === "FAILED") {
137	    jobId = (await db.job.create({ data: { type: "VM_MOVE", serverId: move.serverId, payload: { vmMoveId } }, select: { id: true } })).id;
138	  }
139	  await recordAudit(admin.id, "server.vm_move.rollback", `${move.server.hostname} move=${vmMoveId}`);
140	  return { ok: true, jobId };
141	}
142	
143	export async function getVmMove(vmMoveId: string) {
144	  await requireArea("fleet");
145	  if (!idSchema.safeParse(vmMoveId).success) return null;
146	  return db.vmMove.findUnique({
147	    where: { id: vmMoveId },
148	    include: { server: { select: { id: true, hostname: true, status: true, vmid: true, nodeId: true } } },
149	  });
150	}
151	
152	export async function listVmMoves(opts?: { serverId?: string; limit?: number }) {
153	  await requireArea("fleet");
154	  return db.vmMove.findMany({
155	    where: opts?.serverId ? { serverId: opts.serverId } : undefined,
156	    orderBy: { createdAt: "desc" },
157	    take: Math.min(200, Math.max(1, opts?.limit ?? 50)),
158	    include: { server: { select: { id: true, hostname: true, status: true } } },
159	  });
160	}
