162	/** Ranked offload candidates for a node (lib/vm-move/plan.ts rankMoveCandidates). */
163	export async function listMoveCandidates(nodeId: string, real?: RealUsageByVmid): Promise<MoveCandidate[]> {
164	  await requireArea("fleet");
