1	/**
2	 * Dedicated-IP carry-over for VM moves — the OVH half.
3	 *
4	 * An OVH failover IP is routed to exactly one dedicated server at a time and
5	 * reaches a VM through a per-server Virtual MAC. Moving a VM between two OVH
6	 * boxes therefore needs three provider-side steps, in this order and only as
7	 * the LAST step before the target starts (so everything before it is a plain
8	 * local rollback):
9	 *
10	 *   1. `GET /ip/{ip}/move` — the list of services the IP MAY move to. OVH only
11	 *      lists same-campus destinations (verified live 2026-10-01: a Singapore
12	 *      IP lists ns5002569/ns5013314/ns564103 and not the Beauharnois box), so
13	 *      this is the authoritative "same zone" guard. We also compare the two
14	 *      servers' `datacenter` fields as a belt-and-braces check.
15	 *   2. `POST /ip/{ip}/move {to}` — asynchronous; returns a task we poll via
16	 *      `GET /ip/{ip}/task/{id}` until `done` (or `error`/`cancelled`).
17	 *   3. `POST /dedicated/server/{target}/virtualMac {ipAddress,type:"ovh",…}`
18	 *      — a NEW Virtual MAC on the target server (the old one stays bound to
19	 *      the source server's object and is deleted at cleanup). The MAC string
20	 *      is what the target VM's net0 must carry.
21	 *
22	 * Rollback = the same three steps back toward the source. Hetzner nodes are
23	 * not supported for a dedicated-IP move yet (the engine refuses at preflight):
24	 * Hetzner's Robot has no "move IP" call — the IP must be re-ordered against
25	 * the other server — and the fleet currently has one Hetzner node, so a
26	 * dedicated-IP move involving it would be a different, manual runbook.
27	 */
28	import { ovh, ovhApi } from "../ovh";
29	import { ipMoveDestinationAllowed, type OvhMoveDestinations } from "./plan";
30	
31	const IPV4 = /^(?:(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)$/;
32	const SERVICE_RE = /^[a-z0-9][a-z0-9.-]{2,80}$/;
33	
34	function assertIp(ip: string): void {
35	  if (!IPV4.test(ip)) throw new Error(`refusing non-IPv4 address ${JSON.stringify(ip)}`);
36	}
37	function assertService(s: string): void {
38	  if (!SERVICE_RE.test(s)) throw new Error(`refusing unexpected OVH service name ${JSON.stringify(s)}`);
39	}
40	
41	export type OvhIpFacts = {
42	  routedTo: string | null;
43	  campus: string | null;
44	  type: string | null;
45	  destinations: OvhMoveDestinations;
46	};
47	
48	export async function ovhIpFacts(ip: string): Promise<OvhIpFacts> {
49	  assertIp(ip);
50	  const block = `${ip}/32`;
51	  const info = await ovhApi.ipInfo(block);
52	  const destinations: OvhMoveDestinations = await ovh("GET", `/ip/${encodeURIComponent(block)}/move`).catch(() => ({}));
53	  return {
54	    routedTo: info?.routedTo?.serviceName ?? null,
55	    campus: info?.campus ?? null,
56	    type: info?.type ?? null,
57	    destinations,
58	  };
59	}
60	
61	export async function ovhServerDatacenter(service: string): Promise<string | null> {
62	  assertService(service);
63	  const d = await ovhApi.server(service).catch(() => null);
64	  return d?.datacenter ?? null;
65	}
66	
67	/** Everything preflight needs to know before promising an IP can travel. */
68	export async function ovhIpMovePreflight(ip: string, sourceService: string, targetService: string): Promise<{ ok: boolean; detail: string }> {
69	  assertService(sourceService);
70	  assertService(targetService);
71	  const facts = await ovhIpFacts(ip);
72	  if (facts.routedTo !== sourceService) {
73	    return { ok: false, detail: `${ip} is routed to ${facts.routedTo ?? "nobody"}, not the source node's service ${sourceService}` };
74	  }
75	  if (facts.type !== "failover" && facts.type !== "additional") {
76	    return { ok: false, detail: `${ip} is an OVH "${facts.type}" IP — only failover/additional IPs can move` };
77	  }
78	  if (!ipMoveDestinationAllowed(facts.destinations, targetService)) {
79	    const listed = (facts.destinations.dedicatedServer ?? []).map((d) => d.service).join(", ") || "none";
80	    return { ok: false, detail: `OVH will not move ${ip} to ${targetService} (campus ${facts.campus ?? "?"}); allowed destinations: ${listed}` };
81	  }
82	  const [srcDc, dstDc] = await Promise.all([ovhServerDatacenter(sourceService), ovhServerDatacenter(targetService)]);
83	  if (srcDc && dstDc && srcDc.replace(/\d+$/, "") !== dstDc.replace(/\d+$/, "")) {
84	    return { ok: false, detail: `source datacenter ${srcDc} and target ${dstDc} are different campuses` };
85	  }
86	  return { ok: true, detail: `${ip} (${facts.campus ?? "?"}) may move ${sourceService} → ${targetService}; datacenters ${srcDc ?? "?"}/${dstDc ?? "?"}` };
87	}
88	
89	/** Where a failover IP is routed right now — used to make the move idempotent. */
90	export async function ovhIpRoutedTo(ip: string): Promise<string | null> {
91	  return (await ovhIpFacts(ip)).routedTo;
92	}
93	
94	/**
95	 * Route `ip` to `targetService` and wait for OVH's task to finish. Idempotent:
96	 * if the IP is already routed there, returns immediately. Returns the task id
97	 * (or null when nothing had to be done).
98	 */
99	export async function ovhMoveIp(ip: string, targetService: string, opts?: { timeoutMs?: number; pollMs?: number }): Promise<number | null> {
100	  assertIp(ip);
101	  assertService(targetService);
102	  const block = `${ip}/32`;
103	  if ((await ovhIpRoutedTo(ip)) === targetService) return null;
104	  const task = await ovh("POST", `/ip/${encodeURIComponent(block)}/move`, { to: targetService });
105	  const taskId: number | undefined = task?.taskId;
106	  const timeoutMs = opts?.timeoutMs ?? 10 * 60_000;
107	  const pollMs = opts?.pollMs ?? 5_000;
108	  const start = Date.now();
109	  while (Date.now() - start < timeoutMs) {
110	    await new Promise((r) => setTimeout(r, pollMs));
111	    if (taskId !== undefined) {
112	      const t = await ovh("GET", `/ip/${encodeURIComponent(block)}/task/${taskId}`).catch(() => null);
113	      const status = t?.status;
114	      if (status === "done") break;
115	      if (status === "error" || status === "cancelled") throw new Error(`OVH IP move task ${taskId} ended with status ${status}`);
116	    }
117	    if ((await ovhIpRoutedTo(ip)) === targetService) break;
118	  }
119	  if ((await ovhIpRoutedTo(ip)) !== targetService) throw new Error(`OVH did not finish routing ${ip} to ${targetService} within ${Math.round(timeoutMs / 1000)}s`);
120	  return taskId ?? null;
121	}
122	
123	/** Find the Virtual MAC bound to `ip` on `service`, if any. */
124	export async function ovhFindVirtualMac(service: string, ip: string): Promise<string | null> {
125	  assertService(service);
126	  assertIp(ip);
127	  const macs: string[] = await ovhApi.virtualMacs(service).catch(() => []);
128	  for (const m of macs) {
129	    const ips: string[] = await ovh("GET", `/dedicated/server/${service}/virtualMac/${m}/virtualAddress`).catch(() => []);
130	    if (ips.includes(ip)) return m;
131	  }
132	  return null;
133	}
134	
135	/** Ensure a Virtual MAC for `ip` exists on `service` and return it (creation is async on OVH's side; polled). */
136	export async function ovhEnsureVirtualMac(service: string, ip: string, vmName: string, opts?: { attempts?: number; pollMs?: number }): Promise<string> {
137	  assertService(service);
138	  assertIp(ip);
139	  let mac = await ovhFindVirtualMac(service, ip);
140	  if (mac) return mac;
141	  await ovhApi.createVirtualMac(service, ip, vmName.replace(/[^a-zA-Z0-9-]/g, "").slice(0, 40) || "nxeon-move");
142	  const attempts = opts?.attempts ?? 40;
143	  const pollMs = opts?.pollMs ?? 3_000;
144	  for (let i = 0; i < attempts && !mac; i++) {
145	    await new Promise((r) => setTimeout(r, pollMs));
146	    mac = await ovhFindVirtualMac(service, ip);
147	  }
148	  if (!mac) throw new Error(`Virtual MAC for ${ip} on ${service} not bound after creation (OVH task still pending)`);
149	  return mac;
150	}
151	
152	/** Best-effort removal of the Virtual MAC that carried `ip` on `service` (cleanup / rollback). */
153	export async function ovhReleaseVirtualMac(service: string, ip: string, mac: string | null): Promise<void> {
154	  assertService(service);
155	  assertIp(ip);
156	  const target = mac ?? (await ovhFindVirtualMac(service, ip));
157	  if (!target) return;
158	  await ovh("DELETE", `/dedicated/server/${service}/virtualMac/${target}/virtualAddress/${ip}`).catch(() => {});
159	  await ovh("DELETE", `/dedicated/server/${service}/virtualMac/${target}`).catch(() => {});
160	}
