211	async function handleZfsDestroyDataset(_req, res, rawBody) {
212	  const p = parseJson(rawBody);
213	  const parsed = p && parseVmDataset(p.dataset);
214	  if (!parsed) return sendJson(res, 400, { error: "invalid dataset" });
215	  if (vmConfigExists(parsed.vmid)) return sendJson(res, 409, { error: `vm ${parsed.vmid} has a config on this node — destroy it through Proxmox, not here` });
216	  try {
217	    await zfs(["destroy", "-r", p.dataset]);
