224	/**
225	 * POST /v1/zfs/recv?dataset=… — body is a zstd-compressed `zfs send` stream.
226	 * Decompressed and received with `-F` (so an incremental lands on the full
227	 * pass's snapshot) and `-u` (never try to mount anything). Refuses a dataset
228	 * whose vmid already has a VM config here (that would be someone's live
229	 * disk), and refuses to create a dataset whose pool path doesn't exist.
230	 */
231	async function handleZfsRecv(req, res, dataset) {
232	  const parsed = parseVmDataset(dataset);
233	  if (!parsed) return sendJson(res, 400, { error: "invalid dataset" });
234	  if (vmConfigExists(parsed.vmid)) return sendJson(res, 409, { error: `vm ${parsed.vmid} already has a config on this node` });
235	  try {
236	    await zfs(["list", "-H", "-o", "name", parsed.pool]);
237	  } catch {
238	    return sendJson(res, 400, { error: `pool ${parsed.pool} does not exist on this node` });
239	  }
240	  const zstd = spawn("zstd", ["-d", "-q", "-T0"], { stdio: ["pipe", "pipe", "pipe"] });
241	  const recv = spawn("zfs", ["receive", "-F", "-u", dataset], { stdio: ["pipe", "pipe", "pipe"] });
242	  let recvErr = "";
243	  recv.stderr.on("data", (d) => (recvErr += d.toString().slice(0, 1000)));
244	  let zstdErr = "";
245	  zstd.stderr.on("data", (d) => (zstdErr += d.toString().slice(0, 1000)));
246	  const recvDone = new Promise((resolve, reject) => {
247	    recv.on("error", reject);
248	    recv.on("close", (code) => (code === 0 ? resolve() : reject(new Error(`zfs receive exited ${code}: ${recvErr.trim()}`))));
249	  });
250	  try {
251	    zstd.stdout.pipe(recv.stdin);
252	    await pipeline(req, zstd.stdin);
253	    await recvDone;
254	  } catch (e) {
255	    try { zstd.kill("SIGKILL"); } catch { /* already gone */ }
256	    try { recv.kill("SIGKILL"); } catch { /* already gone */ }
257	    throw new Error(`${e.message}${zstdErr ? ` (zstd: ${zstdErr.trim()})` : ""}`);
258	  }
259	  sendJson(res, 200, { ok: true });
260	}
