262	/**
263	 * GET /v1/zfs/send?dataset=…&snap=…[&from=…] — streams a zstd-compressed
264	 * `zfs send` of `dataset@snap` (incremental from `@from` when given). Used
265	 * when THIS node is the source of a move; the primary pipes it straight into
266	 * the target's recv endpoint.
267	 */
268	async function handleZfsSend(_req, res, dataset, snap, from) {
269	  if (!parseVmDataset(dataset)) return sendJson(res, 400, { error: "invalid dataset" });
270	  if (!isStr(snap, MOVE_SNAPSHOT_RE) || (from !== null && !isStr(from, MOVE_SNAPSHOT_RE))) return sendJson(res, 400, { error: "invalid snapshot" });
271	  const args = ["send", "-L", "-e"];
272	  if (from) args.push("-i", `${dataset}@${from}`);
273	  args.push(`${dataset}@${snap}`);
274	  const send = spawn("zfs", args, { stdio: ["ignore", "pipe", "pipe"] });
275	  const zstd = spawn("zstd", ["-3", "-q", "-T1"], { stdio: ["pipe", "pipe", "pipe"] });
276	  let sendErr = "";
277	  send.stderr.on("data", (d) => (sendErr += d.toString().slice(0, 1000)));
278	  send.on("close", (code) => {
279	    if (code !== 0) {
280	      console.error(`[node-agent] zfs send ${dataset}@${snap} exited ${code}: ${sendErr.trim()}`);
281	      // Truncate the response so the receiver's zstd/zfs receive fails loudly
282	      // instead of accepting a short stream as complete.
283	      try { zstd.kill("SIGKILL"); } catch { /* gone */ }
284	      res.destroy();
285	    }
286	  });
287	  res.writeHead(200, { "Content-Type": "application/octet-stream" });
288	  send.stdout.pipe(zstd.stdin);
289	  zstd.stdout.pipe(res);
290	  res.on("close", () => {
291	    try { send.kill("SIGKILL"); } catch { /* gone */ }
292	    try { zstd.kill("SIGKILL"); } catch { /* gone */ }
293	  });
294	}
