296	// ---- iptables exec — argv arrays only, NEVER a shell string ----------------
297	function iptables(args) {
298	  return new Promise((resolve, reject) => {
299	    execFile("iptables", args, { timeout: CMD_TIMEOUT_MS }, (err, stdout, stderr) => {
300	      if (err) return reject(new Error(String(stderr || err.message).trim().slice(0, 400)));
301	      resolve(stdout);
302	    });
303	  });
304	}
305	
306	async function ensureChain(chain) {
307	  try {
308	    await iptables(["-t", "nat", "-N", chain]);
309	  } catch {
310	    /* chain already exists */
311	  }
312	  try {
313	    await iptables(["-t", "nat", "-C", "PREROUTING", "-j", chain]);
314	  } catch {
315	    await iptables(["-t", "nat", "-A", "PREROUTING", "-j", chain]);
316	  }
317	}
318	
319	function pvesmPath(storageRef) {
320	  return new Promise((resolve, reject) => {
321	    execFile("pvesm", ["path", storageRef], { timeout: 10_000 }, (err, stdout) => {
322	      if (err) return reject(new Error(`pvesm path ${storageRef}: ${err.message}`));
323	      resolve(stdout.trim());
324	    });
325	  });
326	}
