328	// ---- request body helpers ---------------------------------------------------
329	function readBody(req) {
330	  return new Promise((resolve, reject) => {
331	    let size = 0;
332	    const chunks = [];
333	    req.on("data", (c) => {
334	      size += c.length;
335	      if (size > MAX_BODY_BYTES) {
336	        reject(new Error("request body too large"));
337	        req.destroy();
338	        return;
339	      }
340	      chunks.push(c);
341	    });
342	    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
343	    req.on("error", reject);
344	  });
345	}
