347	/** Parse a JSON body, or return undefined (never throws) so handlers can 400 cleanly. */
348	function parseJson(text) {
349	  try {
350	    return JSON.parse(text || "{}");
351	  } catch {
352	    return undefined;
353	  }
354	}
355	
356	function sendJson(res, status, obj) {
357	  const body = JSON.stringify(obj);
358	  res.writeHead(status, { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) });
359	  res.end(body);
360	}
