403	/** Resolve `<storage>:snippets/<filename>` via pvesm and refuse anything that
404	 *  didn't land in a real snippets directory — defense in depth beyond the
405	 *  filename/storage allowlists above. */
406	async function resolveSnippetPath(storage, filename) {
407	  const target = await pvesmPath(`${storage}:snippets/${filename}`);
408	  if (!target.includes(`${path.sep}snippets${path.sep}`) && !target.endsWith(`${path.sep}snippets`)) {
409	    throw new Error("storage did not resolve to a snippets path");
410	  }
