414	async function handleWriteSnippet(_req, res, rawBody) {
415	  const parsed = parseJson(rawBody);
416	  if (!parsed || !STORAGE_RE.test(parsed.storage || "")) return sendJson(res, 400, { error: "invalid storage id" });
417	  if (!FILENAME_RE.test(parsed.filename || "")) return sendJson(res, 400, { error: "invalid filename" });
418	  if (typeof parsed.content !== "string" || parsed.content.length > MAX_BODY_BYTES) {
419	    return sendJson(res, 400, { error: "invalid content" });
420	  }
421	  const target = await resolveSnippetPath(parsed.storage, parsed.filename);
422	  fs.mkdirSync(path.dirname(target), { recursive: true });
423	  fs.writeFileSync(target, parsed.content, { mode: 0o600 });
424	  sendJson(res, 200, { ok: true });
425	}
