427	async function handleDeleteSnippet(_req, res, rawBody) {
428	  const parsed = parseJson(rawBody);
429	  if (!parsed || !STORAGE_RE.test(parsed.storage || "")) return sendJson(res, 400, { error: "invalid storage id" });
430	  if (!FILENAME_RE.test(parsed.filename || "")) return sendJson(res, 400, { error: "invalid filename" });
431	  const target = await resolveSnippetPath(parsed.storage, parsed.filename);
