443	/** Recursively-flat listing of the two backup subdirs this agent exposes —
444	 *  each entry's `path` is exactly what handleBackupFile expects back. Missing
445	 *  subdirs (e.g. a node with no vzdump guests yet) are not an error — an
446	 *  empty/partial manifest is itself the honest signal the primary's collector
447	 *  needs to raise, not something this endpoint should paper over. */
448	async function handleBackupManifest(_req, res) {
449	  const entries = [];
450	  for (const sub of ["platform", "status"]) {
451	    const dir = path.join(BACKUP_ROOT, sub);
452	    let names;
453	    try {
454	      names = fs.readdirSync(dir);
455	    } catch {
456	      continue; // subdir doesn't exist on this node yet — not an error
457	    }
458	    for (const name of names) {
459	      const rel = `${sub}/${name}`;
460	      if (!BACKUP_REL_RE.test(rel)) continue; // silently skip anything not on the allowlist
461	      let st;
462	      try {
463	        st = fs.statSync(path.join(dir, name));
464	      } catch {
465	        continue;
466	      }
467	      if (!st.isFile()) continue;
468	      entries.push({ path: rel, size: st.size, mtimeMs: st.mtimeMs });
469	    }
470	  }
471	  sendJson(res, 200, { entries });
472	}
473	
474	/** Stream one backup file's raw bytes. `relPath` must match BACKUP_REL_RE
475	 *  (rules out traversal by construction — no `..`, no absolute path, no
476	 *  extension this platform doesn't itself produce) AND the resolved real
477	 *  path must land inside BACKUP_ROOT — same defense-in-depth shape as
478	 *  resolveSnippetPath() above, kept even though the regex alone should
479	 *  already be sufficient. */
480	async function handleBackupFile(_req, res, relPath) {
481	  if (!isStr(relPath, BACKUP_REL_RE)) return sendJson(res, 400, { error: "invalid path" });
482	  const full = path.join(BACKUP_ROOT, relPath);
483	  let real;
484	  try {
485	    real = fs.realpathSync(full);
486	  } catch {
487	    return sendJson(res, 404, { error: "not found" });
488	  }
489	  const rootReal = fs.realpathSync(BACKUP_ROOT);
490	  if (real !== rootReal && !real.startsWith(rootReal + path.sep)) {
491	    return sendJson(res, 400, { error: "path escapes backup root" });
492	  }
493	  let st;
494	  try {
495	    st = fs.statSync(real);
496	  } catch {
497	    return sendJson(res, 404, { error: "not found" });
498	  }
499	  if (!st.isFile()) return sendJson(res, 404, { error: "not found" });
500	  res.writeHead(200, {
501	    "Content-Type": "application/octet-stream",
502	    "Content-Length": st.size,
503	    "Content-Disposition": `attachment; filename="${path.basename(real)}"`,
504	  });
505	  fs.createReadStream(real).pipe(res);
506	}
