508	// ---- router ------------------------------------------------------------------
509	
510	async function route(req, res) {
511	  const url = new URL(req.url, `https://${req.headers.host || "localhost"}`);
512	  const { pathname, searchParams } = url;
513	
514	  if (req.method === "GET" && pathname === "/v1/health") return handleHealth(req, res);
515	
516	  if (req.method === "POST" && pathname === "/v1/nat/ensure-chain") return handleEnsureChain(req, res, await readBody(req));
517	
518	  const chainMatch = /^\/v1\/nat\/chain\/([^/]+)$/.exec(pathname);
519	  if (req.method === "GET" && chainMatch) return handleListChain(req, res, decodeURIComponent(chainMatch[1]));
520	
521	  if (req.method === "POST" && pathname === "/v1/nat/rule") return handleAddRule(req, res, await readBody(req));
522	  if (req.method === "DELETE" && pathname === "/v1/nat/rule") return handleDeleteRule(req, res, await readBody(req));
523	
524	  if (req.method === "POST" && pathname === "/v1/snippet") return handleWriteSnippet(req, res, await readBody(req));
525	  if (req.method === "DELETE" && pathname === "/v1/snippet") return handleDeleteSnippet(req, res, await readBody(req));
526	
527	  if (req.method === "GET" && pathname === "/v1/iptables/dnat-check") return handleDnatCheck(req, res, searchParams.get("address"));
528	
529	  if (req.method === "GET" && pathname === "/v1/backup/manifest") return handleBackupManifest(req, res);
530	  if (req.method === "GET" && pathname === "/v1/backup/file") return handleBackupFile(req, res, searchParams.get("path"));
531	
532	  // VM move transport (see the ZFS section above).
533	  if (req.method === "GET" && pathname === "/v1/zfs/dataset") return handleZfsDataset(req, res, searchParams.get("dataset"));
534	  if (req.method === "POST" && pathname === "/v1/zfs/snapshot") return handleZfsSnapshot(req, res, await readBody(req));
535	  if (req.method === "DELETE" && pathname === "/v1/zfs/snapshot") return handleZfsDeleteSnapshot(req, res, await readBody(req));
536	  if (req.method === "DELETE" && pathname === "/v1/zfs/dataset") return handleZfsDestroyDataset(req, res, await readBody(req));
537	  if (req.method === "POST" && pathname === "/v1/zfs/recv") return handleZfsRecv(req, res, searchParams.get("dataset"));
538	  if (req.method === "GET" && pathname === "/v1/zfs/send") return handleZfsSend(req, res, searchParams.get("dataset"), searchParams.get("snap"), searchParams.get("from"));
539	
540	  sendJson(res, 404, { error: "not found" });
541	}
542	
543	// `requestTimeout: 0` — Node's default (300 s) would cut a multi-GB
544	// /v1/zfs/recv upload mid-stream. Nothing else here runs long; the control
545	// endpoints are still bounded by their own exec timeouts.
546	const server = https.createServer({ key: fs.readFileSync(TLS_KEY), cert: fs.readFileSync(TLS_CERT), requestTimeout: 0 }, (req, res) => {
547	  if (!checkAuth(req)) {
548	    sendJson(res, 401, { error: "unauthorized" });
549	    return;
550	  }
551	  route(req, res).catch((e) => {
552	    console.error("[node-agent] request error:", e && e.message ? e.message : e);
553	    try {
554	      sendJson(res, 500, { error: String((e && e.message) || e).slice(0, 300) });
555	    } catch {
556	      /* response already sent/closed */
557	    }
558	  });
559	});
560	
561	server.listen(PORT, () => {
562	  console.log(`[node-agent] listening on :${PORT}`);
563	});
