153	// ---- VM move transport (node-agent v2, 2026-10-01) ------------------------
154	// Thin wrappers over the agent's /v1/zfs/* endpoints; the dataset/snapshot
155	// validation lives in lib/vm-move/plan.ts (and is re-checked by the agent).
156	// The two streaming calls bypass agentRequest() exactly like
157	// agentDownloadBackupFile below: multi-GB bodies, no JSON, no 15 s timeout.
158	
159	export type AgentZfsDataset =
160	  | { exists: false }
161	  | { exists: true; usedBytes: number; referencedBytes: number; volsizeBytes: number; snapshots: string[] };
162	
163	export async function agentZfsDataset(node: AgentNode, dataset: string): Promise<AgentZfsDataset> {
164	  return agentRequest(node, "GET", `/v1/zfs/dataset?dataset=${encodeURIComponent(dataset)}`);
165	}
166	export async function agentZfsSnapshot(node: AgentNode, dataset: string, snap: string): Promise<void> {
167	  await agentRequest(node, "POST", "/v1/zfs/snapshot", { dataset, snap });
168	}
169	export async function agentZfsDeleteSnapshot(node: AgentNode, dataset: string, snap: string): Promise<void> {
170	  await agentRequest(node, "DELETE", "/v1/zfs/snapshot", { dataset, snap });
171	}
172	export async function agentZfsDestroyDataset(node: AgentNode, dataset: string): Promise<void> {
173	  await agentRequest(node, "DELETE", "/v1/zfs/dataset", { dataset });
174	}
175	
176	function agentAuthOrThrow(node: AgentNode): string {
177	  const token = nodeAgentToken(node);
178	  if (!token) throw new NodeAgentError(`node "${node.name}" has no agent token configured — see /admin/nodes/${node.id}`, node.name);
179	  return token;
180	}
181	
182	/** Pipe a (zstd-compressed) zfs send stream INTO this node's `zfs receive`. Resolves when the agent confirms the receive exited 0. */
183	export async function agentZfsRecv(node: AgentNode, dataset: string, body: import("node:stream").Readable): Promise<void> {
184	  const token = agentAuthOrThrow(node);
