590	export async function relocateForwardBlockInTx(
591	  tx: Tx,
592	  range: IpamRange,
593	  serverId: string,
594	  specs: readonly ForwardSpec[]
595	): Promise<{ guestPort: number; protocol: string; oldPublic: number | null; newPublic: number }[]> {
596	  const offsets = blockOffsets(specs);
597	  const own = await tx.portForward.findMany({
598	    where: { serverId },
599	    select: { id: true, publicPort: true, guestPort: true, protocol: true },
600	  });
601	  const ownBlock = specs.map((sp) => own.find((r) => r.guestPort === sp.guestPort && r.protocol === sp.protocol) ?? null);
602	  const skip = new Set(ownBlock.filter((r): r is ForwardRow => !!r).map((r) => r.publicPort));
603	  // Park the existing block rows so nothing (including ourselves) can collide.
604	  let t = -1;
605	  for (const r of ownBlock) if (r) await tx.portForward.update({ where: { id: r.id }, data: { publicPort: t-- } });
606	  const probe = await tx.portForward.findMany({ where: { publicPort: { gte: range.sshPortStart, lte: range.sshPortEnd } }, select: { publicPort: true } });
607	  const servers = await tx.server.findMany({ where: { sshPort: { gte: range.sshPortStart, lte: range.sshPortEnd } }, select: { sshPort: true } });
608	  const used = new Set<number>([...probe.map((f) => f.publicPort), ...servers.map((x) => x.sshPort!).filter((x) => x != null)]);
609	  const base = findContiguousBase(used, range.sshPortStart, range.sshPortEnd, offsets, (p) => isReserved(`port:${p}`) && !skip.has(p));
610	  if (base === null) throw new Error(`No free consecutive block of ${Math.max(...offsets) + 1} ports in ${range.sshPortStart}-${range.sshPortEnd}`);
611	  const out: { guestPort: number; protocol: string; oldPublic: number | null; newPublic: number }[] = [];
612	  for (let i = 0; i < specs.length; i++) {
613	    const row = ownBlock[i];
614	    const newPublic = base + offsets[i];
615	    if (row) await tx.portForward.update({ where: { id: row.id }, data: { publicPort: newPublic } });
616	    else await tx.portForward.create({ data: { serverId, publicPort: newPublic, guestPort: specs[i].guestPort, protocol: specs[i].protocol } });
617	    out.push({ guestPort: specs[i].guestPort, protocol: specs[i].protocol, oldPublic: row?.publicPort ?? null, newPublic });
618	  }
619	  return out;
620	}
