622	/** Locked, retried wrapper around {@link relocateForwardBlockInTx}. */
623	export async function relocateForwardBlock(
624	  client: PrismaClient,
625	  range: IpamRange,
626	  serverId: string,
627	  specs: readonly ForwardSpec[]
628	) {
629	  await probeAdvisoryLocks();
630	  const res = await client.$transaction(async (tx) => {
631	    await lockIpam(tx);
632	    return relocateForwardBlockInTx(tx, range, serverId, specs);
633	  });
634	  for (const r of res) reserve(`port:${r.newPublic}`);
