638	/**
639	 * Make sure every join port of `family` has a PortForward row for this server,
640	 * idempotently. Contiguous families (Valheim, ARK, PZ) get their whole block
641	 * from one atomic allocation when none of it exists yet; everything else (and
642	 * any leftover gap) is allocated one port at a time as before. Returns the
643	 * rows it created. Never throws for a single port: callers log and continue.
644	 */
645	export async function ensureGameForwards(
646	  nodeId: string | null | undefined,
647	  serverId: string,
648	  family: GameFamily
649	): Promise<{ guestPort: number; protocol: string; publicPort: number }[]> {
650	  const created: { guestPort: number; protocol: string; publicPort: number }[] = [];
651	  const have = async () =>
652	    new Set(
653	      (await db.portForward.findMany({ where: { serverId }, select: { guestPort: true, protocol: true } })).map(
654	        (f) => `${f.protocol}/${f.guestPort}`
655	      )
656	    );
657	  let existing = await have();
658	  const block = contiguousForwardPorts(family);
659	  if (block && block.every((p) => !existing.has(`${p.protocol}/${p.port}`))) {
660	    const pub = await allocateGameForwardBlock(
661	      nodeId,
662	      serverId,
663	      block.map((p) => p.port),
664	      block.map((p) => p.protocol)
665	    );
666	    block.forEach((p, i) => created.push({ guestPort: p.port, protocol: p.protocol, publicPort: pub[i] }));
667	    existing = await have();
668	  }
669	  for (const p of joinPortsFor(family)) {
670	    if (existing.has(`${p.protocol}/${p.port}`)) continue;
671	    const pub = await allocateGameForward(nodeId, serverId, p.port, p.protocol);
672	    created.push({ guestPort: p.port, protocol: p.protocol, publicPort: pub });
673	  }
674	  return created;
675	}
