6	/**
7	 * VM power-state reconciliation — the layer that was missing on 2026-09-10.
8	 *
9	 * The primary node suffered a hard, ungraceful crash-and-reboot. Proxmox's
10	 * own `onboot=1` + `startall` correctly auto-started every VM except one
11	 * (`studionexis-soul`, the live Soul Pilates production site): its cloud-init
12	 * ZFS dataset hit a transient "already exists" collision from the crash, the
13	 * start attempt failed, and NOTHING retried it or even noticed — the VM sat
14	 * stopped, silently, until a human found it by hand. Every other reliability
15	 * sweep in this file assumes the VM is already running (`sshHealthSweep`
16	 * checks whether SSH still authenticates on a RUNNING server; it never checks
17	 * whether the VM is actually powered on at all). This sweep closes that gap:
18	 * whenever `Server.status` says RUNNING but Proxmox disagrees, retry the
19	 * start and tell an admin either way.
20	 *
21	 * Deliberately simple, matching `sshHealthSweep`'s own shape: no backoff
22	 * bookkeeping, just "check every sweep, retry every sweep, notifyAdmins is
23	 * already dedup'd on its own (DEDUPE_HOURS) so a stuck VM doesn't spam" — a
24	 * genuinely stuck VM (like the ZFS collision) needs a human regardless, and
25	 * repeated retries are harmless (Proxmox's start is a no-op on an
26	 * already-running VM, and a fresh cloud-init generation on retry is exactly
27	 * what fixed the real 2026-09-10 case).
28	 */
29	const BATCH_SIZE = 40;
30	let cursor = 0;
31	
32	export async function vmRecoverySweep(): Promise<void> {
33	  if (SANDBOX) return; // no real Proxmox in staging
34	
35	  const where = { status: "RUNNING" as const, vmid: { not: null } };
36	  const total = await db.server.count({ where });
37	  if (total === 0) return;
38	  if (cursor >= total) cursor = 0;
39	
40	  const servers = await db.server.findMany({
41	    where,
42	    include: {
43	      node: true,
44	      user: { select: { email: true } },
45	    },
46	    orderBy: { id: "asc" },
47	    skip: cursor,
48	    take: BATCH_SIZE,
49	  });
50	  cursor += servers.length;
51	  if (servers.length < BATCH_SIZE) cursor = 0; // wrapped past the end of the table
52	
53	  for (const s of servers) {
54	    if (!s.vmid) continue;
55	    try {
56	      const conn = s.node
57	        ? pveForNode({ apiUrl: s.node.apiUrl, pveNode: s.node.pveNode, tokenId: s.node.tokenId, tokenSecret: s.node.tokenSecret })
58	        : null;
59	      if (!conn) continue; // no Node row yet on a legacy server — nothing safe to check against
60	
61	      const current = await conn.vmStatus(s.vmid);
62	      const realStatus = (current as any)?.status;
63	      if (realStatus === "running") continue; // the common case — nothing to do
64	
65	      // Proxmox disagrees with our own record: the VM is down when it should
66	      // be up. Attempt the same recovery a human would do by hand.
67	      console.error(`[vm-recovery] ${s.hostname} (vmid ${s.vmid}) is "${realStatus}" but Server.status is RUNNING — attempting start`);
68	      try {
69	        await conn.post(`/nodes/${conn.node}/qemu/${s.vmid}/status/start`, {});
70	        await notifyAdmins(
71	          `Auto-recovered: ${s.hostname} was down`,
72	          `"${s.hostname}" (customer ${s.user.email}, vmid ${s.vmid}) was found powered off (Proxmox status: "${realStatus}") while marked RUNNING — likely fallout from a host restart. It has been started back up automatically. Worth a quick look to confirm the guest's own services (database, app, game process) came back cleanly too, not just the VM shell.`,
73	          `/admin/servers/${s.id}`
74	        );
75	      } catch (startErr: any) {
76	        await notifyAdmins(
77	          `VM down and won't restart: ${s.hostname}`,
78	          `"${s.hostname}" (customer ${s.user.email}, vmid ${s.vmid}) is powered off (Proxmox status: "${realStatus}") and the automatic restart attempt failed: ${startErr?.message ?? startErr}. This needs a human — check /admin/servers/${s.id} or SSH to the node directly.`,
79	          `/admin/servers/${s.id}`
80	        );
81	      }
82	    } catch (e: any) {
83	      // A probe failure (node unreachable, etc.) — don't let one bad server
84	      // stop the rest of the batch, and don't spam if the whole node is down
85	      // (nodeAlert/capacity sweeps already own that signal).
86	      console.error(`[vm-recovery] probe failed for ${s.hostname} (${s.id}):`, e?.message ?? e);
87	    }
88	  }
89	}
