1	/**
2	 * VM memory policy: how much of a customer VM's RAM Proxmox may take back
3	 * (ballooning), plus the pure math for the node RAM guard that keeps pinned
4	 * memory from over-committing a node. Pure on purpose (no db, no network):
5	 * the worker, the scheduler (lib/node-ram-guard.ts), the remediation script
6	 * (scripts/pin-vm-memory.ts) and the tests all share it.
7	 *
8	 * WHY (2026-10-01). Since 2026-09-14 every VM was created with
9	 * `balloon = max(1024, 50% of plan RAM)`. pvestatd auto-ballooning shrinks a
10	 * guest toward that floor whenever its node sits above ~80% RAM. On node-4
11	 * (89% used) a customer's 4 GB Valheim VM sat at ~1.8 GB for days while
12	 * running 23 mods ("1.82 GiB is not enough memory" in the game log). A live
13	 * `balloon 4096` monitor command was undone by pvestatd within seconds,
14	 * because the config floor still allowed the shrink. A customer must get the
15	 * RAM they pay for, so customer VMs now get a floor EQUAL to their plan RAM.
16	 *
17	 * POLICIES (env NXEON_BALLOON_POLICY):
18	 *   pin   (default) balloon = memory. Proxmox's documented "fixed memory"
19	 *         mode: the virtio-balloon device stays (guest memory stats, and on
20	 *         recent qemu-server free-page reporting, which hands pages a guest
21	 *         frees back to the host), but pvestatd can never shrink the guest,
22	 *         because its minimum equals its maximum. Changing an existing VM to
23	 *         this is LIVE: the device stays enabled, so Proxmox applies the new
24	 *         minimum at once and pvestatd's next pass raises the target to the
25	 *         full size. No reboot.
26	 *   off   balloon = 0. Removes the balloon device. Same guarantee, but no
27	 *         memory stats from the device, no free-page reporting, and turning
28	 *         the device off on an existing VM is NOT hotpluggable: the change
29	 *         sits in the pending config until a COLD stop + start.
30	 *   floor the old 50%/min-1024 floor. Escape hatch only: it is the behaviour
31	 *         that caused the incident. Use it if a node is in a RAM emergency
32	 *         and the owner accepts squeezing customers to avoid an OOM kill.
33	 *
34	 * WHY pin, not off, by default: both guarantee the RAM. pin is applied live
35	 * to existing VMs (no customer downtime), keeps the device so a future
36	 * emergency can still be handled live, and free-page reporting keeps host RSS
37	 * closer to what guests really use. That last point matters: pinning removes
38	 * the host's ability to reclaim from guests, so the node RAM guard below is
39	 * what keeps a node from being over-committed instead.
40	 *
41	 * The free-Minecraft shared host (freemc-host, node-2 vmid 100) is not a
42	 * `Server` row and is not created by the worker; it was pinned the same way
43	 * (balloon = memory) by scripts/freemc/rollout/01-pin-guest-memory.sh. This
44	 * module does not change it.
45	 */
46	
47	export type BalloonPolicy = "pin" | "off" | "floor";
48	
49	export const BALLOON_POLICIES: readonly BalloonPolicy[] = ["pin", "off", "floor"];
50	
51	/** Resolve the policy from env. Unknown/empty values fall back to `pin`. */
52	export function balloonPolicy(env: Record<string, string | undefined> = process.env): BalloonPolicy {
53	  const v = (env.NXEON_BALLOON_POLICY ?? "").trim().toLowerCase();
54	  return (BALLOON_POLICIES as readonly string[]).includes(v) ? (v as BalloonPolicy) : "pin";
55	}
