57	/** The legacy floor (pre-2026-10-01): 50% of RAM, min 1024, never above RAM. */
58	export function legacyBalloonFloorMB(memoryMB: number): number {
59	  return Math.min(memoryMB, Math.max(1024, Math.round(memoryMB * 0.5)));
60	}
61	
62	/**
63	 * The `balloon` value (MB) to write into a VM config for `memoryMB` of RAM.
64	 * pin -> memoryMB, off -> 0, floor -> legacy floor.
65	 */
66	export function balloonFor(memoryMB: number, policy: BalloonPolicy = balloonPolicy()): number {
67	  const mem = Math.trunc(Number(memoryMB));
68	  if (!Number.isFinite(mem) || mem < 1) throw new Error(`balloonFor: invalid memory ${memoryMB}`);
69	  if (policy === "off") return 0;
70	  if (policy === "floor") return legacyBalloonFloorMB(mem);
71	  return mem;
72	}
