74	/** `{ memory, balloon }` pair for a Proxmox config POST. */
75	export function memoryConfig(memoryMB: number, policy: BalloonPolicy = balloonPolicy()): { memory: number; balloon: number } {
76	  return { memory: Math.trunc(memoryMB), balloon: balloonFor(memoryMB, policy) };
77	}
