85	/**
86	 * The RAM (MB) Proxmox guarantees a VM: the lowest it may balloon it to.
87	 *   balloon unset -> device on, minimum defaults to memory -> memory
88	 *   balloon 0     -> no device -> memory
89	 *   otherwise     -> min(balloon, memory)
90	 */
91	export function guaranteedMB(memoryMB: unknown, balloonMB: unknown): number {
92	  const mem = num(memoryMB) ?? 0;
93	  const b = num(balloonMB);
94	  if (b === null || b === 0) return mem;
95	  return Math.min(b, mem);
96	}
