98	export type VmMemoryState = {
99	  /** `memory` from the VM config (MB). */
100	  memoryMB: number;
101	  /** `balloon` from the CURRENT (running) config, null if unset. */
102	  balloonMB: number | null;
103	  /** `balloon` from the pending config, when a change is waiting for a cold restart. */
104	  pendingBalloonMB?: number | null;
105	  /** What the customer paid for (gamePlan.ramMB ?? plan.ramMB). */
106	  planRamMB: number;
107	};
