115	/**
116	 * What the remediation script should do with one VM.
117	 *   ok                 floor already >= plan RAM.
118	 *   pending-restart    a balloon:0 is already pending; only a cold restart is missing.
119	 *   pin                floor < plan RAM: set balloon.
120	 *   memory-below-plan  `memory` itself is below the plan: a sizing problem
121	 *                      (resize territory), reported, never touched here.
122	 */
123	export function pinVerdict(s: VmMemoryState): PinVerdict {
124	  if (s.memoryMB < s.planRamMB) {
125	    return { action: "memory-below-plan", note: `memory ${s.memoryMB} MB < plan ${s.planRamMB} MB (sizing issue, not ballooning)` };
126	  }
127	  const floor = guaranteedMB(s.memoryMB, s.balloonMB);
128	  if (floor >= s.planRamMB) return { action: "ok", note: `floor ${floor} MB >= plan ${s.planRamMB} MB` };
129	  const pend = s.pendingBalloonMB;
130	  if (pend !== undefined && pend !== null && guaranteedMB(s.memoryMB, pend) >= s.planRamMB) {
131	    return { action: "pending-restart", note: `balloon ${pend} already pending; needs a cold stop+start` };
132	  }
133	  return { action: "pin", note: `floor ${floor} MB < plan ${s.planRamMB} MB` };
