161	export type RamGuardConfig = {
162	  /** RAM kept for the host itself: ZFS ARC (capped at 8 GB on the primary) + host OS/pve daemons. */
163	  hostReserveMB: number;
164	  /** Max share of (total - reserve) that guaranteed (pinned + floors) VM RAM may reach. */
165	  maxGuaranteedRatio: number;
166	  /** Max share of physical RAM that real used + the new VM may reach. */
167	  maxRealRatio: number;
168	};
169	
170	export function ramGuardConfig(env: Record<string, string | undefined> = process.env): RamGuardConfig {
171	  const n = (k: string, d: number, lo: number, hi: number) => {
172	    const v = Number(env[k]);
173	    return Number.isFinite(v) && v >= lo && v <= hi ? v : d;
174	  };
175	  return {
176	    hostReserveMB: n("NXEON_HOST_RESERVE_MB", 10240, 0, 1_048_576),
177	    maxGuaranteedRatio: n("NXEON_PINNED_RAM_MAX_RATIO", 0.95, 0.1, 1),
178	    maxRealRatio: n("NXEON_REAL_RAM_MAX_RATIO", 0.9, 0.1, 1),
179	  };
180	}
