182	export type ListedVm = {
183	  vmid: number;
184	  status: string;
185	  template?: boolean;
186	  /** Config `memory` (MB). */
187	  memoryMB: number;
188	  /** Config `balloon` (MB, current), null when unset. */
189	  balloonMB: number | null;
190	};
191	
192	export type NodeRamSnapshot = {
193	  /** Physical RAM (MB), from /nodes/<n>/status memory.total. */
194	  totalMB: number;
195	  /** Real used (MB), memory.used (MemTotal - MemAvailable; includes ZFS ARC). */
196	  usedMB: number;
197	  /** Sum of guaranteed RAM of every RUNNING non-template VM on the node (all VMs, not only Nxeon customers). */
198	  guaranteedMB: number;
199	  /** Sum of `memory` of every running VM (the ceiling they may grow to). */
200	  ceilingMB: number;
201	  runningVms: number;
202	};
203	
204	/** Reduce a node's VM list to the guard's guaranteed/ceiling totals. */
205	export function summarizeVms(vms: ListedVm[]): { guaranteedMB: number; ceilingMB: number; runningVms: number } {
206	  let g = 0;
207	  let c = 0;
208	  let r = 0;
209	  for (const v of vms) {
210	    if (v.template || v.status !== "running") continue;
211	    g += guaranteedMB(v.memoryMB, v.balloonMB);
212	    c += v.memoryMB;
213	    r += 1;
214	  }
215	  return { guaranteedMB: g, ceilingMB: c, runningVms: r };
216	}
217	
218	export type RamGuardVerdict = {
219	  ok: boolean;
220	  reason: string;
221	  /** Guaranteed RAM after the new VM, as % of (total - reserve). */
222	  projectedGuaranteedPct: number;
223	  /** Real used + new VM, as % of total. */
224	  projectedRealPct: number;
225	};
226	
227	/**
228	 * Can a node take one more VM that pins `newVmMB`? Two independent checks,
229	 * both must pass:
230	 *  1. guaranteed + new <= (total - hostReserve) * maxGuaranteedRatio.
231	 *     Every pinned VM can always claim its full RAM; this keeps the sum of
232	 *     those claims below what the host can physically hand out after its own
233	 *     reserve (ZFS ARC cap + host). This is what makes pinning safe.
234	 *  2. used + new <= total * maxRealRatio. What is really in use right now
235	 *     (ARC included) must leave room; node-4 at 89% fails this for any VM.
236	 * The DB-committed check in scheduleNode (sum of plan RAM of every
237	 * non-deleting server vs Node.capacityRamMB, < CRITICAL) still runs too: it
238	 * covers STOPPED customer VMs, which this live view cannot see as claims.
239	 */
240	export function ramGuardVerdict(snap: NodeRamSnapshot, newVmMB: number, cfg: RamGuardConfig): RamGuardVerdict {
241	  const budget = Math.max(0, snap.totalMB - cfg.hostReserveMB);
242	  const projG = snap.guaranteedMB + newVmMB;
243	  const projR = snap.usedMB + newVmMB;
244	  const gPct = budget > 0 ? (projG / budget) * 100 : Infinity;
245	  const rPct = snap.totalMB > 0 ? (projR / snap.totalMB) * 100 : Infinity;
246	  const gLimit = budget * cfg.maxGuaranteedRatio;
247	  const rLimit = snap.totalMB * cfg.maxRealRatio;
248	  const problems: string[] = [];
249	  if (!(snap.totalMB > 0)) problems.push("node reported no RAM total");
250	  else {
251	    if (projG > gLimit) {
252	      problems.push(
253	        `guaranteed VM RAM would be ${Math.round(projG)} MB > ${Math.round(gLimit)} MB ` +
254	          `(${Math.round(cfg.maxGuaranteedRatio * 100)}% of ${snap.totalMB} MB minus ${cfg.hostReserveMB} MB host reserve)`,
255	      );
256	    }
257	    if (projR > rLimit) {
258	      problems.push(
259	        `real used would be ${Math.round(projR)} MB > ${Math.round(rLimit)} MB (${Math.round(cfg.maxRealRatio * 100)}% of ${snap.totalMB} MB)`,
260	      );
261	    }
262	  }
263	  return {
264	    ok: problems.length === 0,
265	    reason: problems.length ? problems.join("; ") : "ok",
266	    projectedGuaranteedPct: gPct,
267	    projectedRealPct: rPct,
268	  };
269	}
270	
271	/** Headroom (MB) a node has for more pinned RAM under both checks (may be negative). */
272	export function pinnedHeadroomMB(snap: NodeRamSnapshot, cfg: RamGuardConfig): number {
273	  const budget = Math.max(0, snap.totalMB - cfg.hostReserveMB);
274	  const g = budget * cfg.maxGuaranteedRatio - snap.guaranteedMB;
275	  const r = snap.totalMB * cfg.maxRealRatio - snap.usedMB;
276	  return Math.floor(Math.min(g, r));
277	}
