44	/**
45	 * Single idempotent choke point for keeping a paid Minecraft server's DNS
46	 * (`<subdomain>.play.nxeon.cloud`, see lib/game-subdomain-dns.ts) in sync with
47	 * its actual reachable ip:port. Called from every place that can change that
48	 * ip:port: provision() (dedicated-IP servers only — see below), addPortForward/
49	 * deletePortForward (NAT servers), and suspend()/unsuspend().
50	 *
51	 * Never throws — a DNS hiccup must not fail provisioning, a port-forward save,
52	 * or a suspend/unsuspend cycle. Callers fire-and-forget via the SYNC_GAME_DNS
53	 * job (see worker/index.ts) rather than awaiting this inline.
54	 */
55	/**
56	 * Pure: which families get a managed subdomain, and whether it includes an
57	 * SRV record. Java gets the full A+SRV pair (no port to remember); Bedrock
58	 * and everything in `HOSTNAME_CONNECT_FAMILIES` (lib/games.ts — the single
59	 * source of truth shared with checkout/dashboard, so the family list can't
60	 * drift between call sites) get an A record only — a friendly hostname is
61	 * the most a subdomain can offer there (see game-subdomain-dns.ts). Every
62	 * other family either rejects hostnames outright (rust, palworld,
63	 * spaceengineers, sandstorm, arkasa — confirmed, not assumed) or has no
64	 * meaningful direct-connect flow at all (server browser/matchmaking only),
65	 * or is simply unverified. Extracted for the same reason
66	 * `resolveGameServerDnsTarget` was: fully unit-testable without touching
67	 * `syncGameServerDns`'s DB/HTTP I/O.
68	 */
69	export function dnsSupportForFamily(family: string | null): { managed: false } | { managed: true; includeSrv: boolean } {
70	  if (family === "minecraft") return { managed: true, includeSrv: true };
71	  if (family === "bedrock" || (family && HOSTNAME_CONNECT_FAMILIES.has(family as GameFamily))) return { managed: true, includeSrv: false };
