75	export async function syncGameServerDns(serverId: string): Promise<void> {
76	  if (SANDBOX) return;
77	  try {
78	    const server = await db.server.findUnique({
79	      where: { id: serverId },
80	      include: {
81	        osTemplate: { select: { family: true } },
82	        gamePlan: { select: { gameFamily: true } },
83	        node: { select: { publicIp: true } },
84	        dedicatedIp: { select: { address: true } },
85	        portForwards: true,
86	      },
87	    });
88	    if (!server || !server.subdomain) return;
89	
90	    const familyLike = server as unknown as { gamePlan?: { gameFamily?: string | null } | null; osTemplate?: { family?: string | null } | null };
91	    const family = gameFamilyForServer(familyLike);
92	    const support = dnsSupportForFamily(family);
93	    if (!support.managed) return;
94	    const includeSrv = support.includeSrv;
95	    // The JOIN port, not the RCON/health-check GAME_PORT — see this file's own
96	    // resolveGameServerDnsTarget doc comment for why that distinction matters.
97	    const join = joinPortFor(family as GameFamily);
98	
99	    const target = resolveGameServerDnsTarget({
100	      status: server.status,
101	      dedicatedIp: server.dedicatedIp,
102	      portForwards: server.portForwards,
103	      nodePublicIp: server.node?.publicIp,
104	      publicIpEnv: process.env.PUBLIC_IP,
105	      gamePort: join.port,
106	      gameProtocol: join.protocol,
107	    });
108	
109	    if (target) {
110	      await upsertMinecraftSubdomainDns({ subdomain: server.subdomain, ip: target.ip, port: target.port, includeSrv });
111	    } else {
112	      await deleteMinecraftSubdomainDns(server.subdomain);
113	    }
114	  } catch (e) {
115	    logError("game-subdomain-sync", e, { serverId });
116	  }
117	}
