1702	async function reinstall(job: Job) {
1703	  const server = await loadServer(job);
1704	  if (SANDBOX) {
1705	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
1706	    await notify(
1707	      server.userId,
1708	      `Server ${server.hostname} reinstalled (sandbox)`,
1709	      "The sandbox server was reinstalled (no real VM was touched).",
1710	      `/dashboard/servers/${server.id}`
1711	    );
1712	    return;
1713	  }
1714	  // DATA SAFETY (critical): a reinstall destroys the VM, and `destroyVm` runs
1715	  // `qm destroy` with { "destroy-unreferenced-disks": 1, purge: 1 } — which wipes
1716	  // EVERY disk the vmid owns, including attached block-storage Volume disks
1717	  // (scsi1+, `vmdata:vm-<vmid>-disk-N`). A disk named `vm-<vmid>-disk-N` is owned
1718	  // by that vmid, and both purge and the default destroy (which removes disks
1719	  // referenced in config, incl. detached `unusedN` entries) delete it; there is no
1720	  // Proxmox API to selectively spare it, and the reinstall re-clones onto the SAME
1721	  // vmid, so we cannot GUARANTEE such a disk survives the destroy. Rather than risk
1722	  // wiping a customer's data, BLOCK the reinstall until the volume(s) are detached.
1723	  // Detaching moves the disk to an "unused" entry (data preserved on storage) and it
1724	  // can be re-attached after the reinstall. This runs BEFORE any status change or
1725	  // destructive call, so a blocked reinstall touches nothing.
1726	  //
1727	  // Match on `serverId` ALONE — NOT `status: "ATTACHED"`. Detaching keeps
1728	  // `serverId` set (see worker/volumes.ts) so the volume can be re-attached, and
1729	  // the disk remains owned by this vmid as an `unusedN` entry. PVE's destroy_vm
1730	  // passes `include_unused => 1`, so it frees those too. Filtering on ATTACHED
1731	  // let the worst path through: fill a volume, Detach (the UI says "Data is
1732	  // preserved."), Reinstall — guard sees nothing attached, purge takes the data.
1733	  // Detaching is therefore NOT sufficient protection, and telling the customer to
1734	  // detach was wrong advice; they must delete the volume (which destroys just
1735	  // that disk, deliberately) or move it to another server first.
1736	  const pinnedVolumes = await db.volume.findMany({
1737	    where: { serverId: server.id },
1738	  });
1739	  // Sandbox volumes have no real disk, so they cannot be purged and must not block.
1740	  const realPinned = pinnedVolumes.filter(
1741	    (v) => !(typeof v.diskName === "string" && v.diskName.startsWith("sandbox:"))
1742	  );
1743	  if (realPinned.length > 0) {
1744	    const names = realPinned.map((v) => `"${v.name}"`).join(", ");
1745	    throw new Error(
1746	      `Remove your data volume(s) before reinstalling to protect their data: ${names}. ` +
1747	        `Reinstalling purges every disk this server owns — including detached volumes ` +
1748	        `that are still assigned to it — and that cannot be undone.`
1749	    );
1750	  }
1751	
1752	  const { conn } = await nodeFor(server);
1753	  // Clear the stored root password BEFORE destroying the VM. `provision()`
1754	  // below reuses `serverRootPassword(server)` instead of minting a fresh one
1755	  // whenever `server.vmid` is already set — that reuse exists for a RETRY
1756	  // (cloud-init's password module is once-per-instance, so a retry must not
1757	  // overwrite Server.rootPasswordEnc with a value the already-booted guest
1758	  // never saw; see provision()'s own comment on this line). A REINSTALL is not
1759	  // a retry: `destroyVm` just above genuinely deletes the VM, so the guest
1760	  // that "already saw" the old password no longer exists — the next one is a
1761	  // brand-new instance that has never seen ANY password yet. Without this,
1762	  // reinstall silently kept the customer's old root password forever (found
1763	  // in the 2026-09-24 audit) — the one operation a customer expects to rotate
1764	  // credentials (e.g. after a suspected compromise) quietly didn't. Nulling
1765	  // both columns here makes `serverRootPassword(server)` return null once
1766	  // provision() reloads the row, so its existing `?? generatePassword()`
1767	  // fallback mints a real fresh one — same code path a first-ever provision
1768	  // takes, no new logic needed there.
1769	  await db.server.update({
1770	    where: { id: server.id },
1771	    data: { status: "REINSTALLING", rootPassword: null, rootPasswordEnc: null },
1772	  });
1773	  if (server.vmid) await destroyVm(conn, server.vmid);
1774	  await provision(job);
1775	}
