869	    }, 20_000);
870	  }
871	  await step(job, "Comparing with the database…", 80);
872	  const [servers, ips, archives, templates, inflightRows] = await Promise.all([
873	    db.server.findMany({ select: { id: true, hostname: true, vmid: true, nodeId: true, status: true, ipAddress: true, updatedAt: true } }),
874	    db.dedicatedIp.findMany({ select: { id: true, address: true, status: true, serverId: true, nodeId: true, purpose: true } }),
875	    db.serverArchive.findMany({ where: { vmid: { not: null } }, select: { vmid: true, hostname: true, deletedAt: true }, orderBy: { deletedAt: "desc" }, take: 2000 }),
876	    db.osTemplate.findMany({ where: { active: true }, select: { vmid: true, baseVmid: true } }),
877	    db.job.findMany({ where: { status: { in: ["QUEUED", "RUNNING"] }, serverId: { not: null } }, select: { serverId: true } }),
878	  ]);
879	  const busy = new Set(inflightRows.map((r) => r.serverId!));
880	  const archivedByVmid: Record<number, { hostname: string; deletedAt: Date }> = {};
881	  for (const a of archives) if (a.vmid != null && !archivedByVmid[a.vmid]) archivedByVmid[a.vmid] = { hostname: a.hostname, deletedAt: a.deletedAt };
882	  const templateVmids = [...new Set(templates.flatMap((t) => [t.vmid, t.baseVmid].filter((v): v is number => typeof v === "number" && v >= 9000 && v <= 9999)))].sort((a, b) => a - b);
