885	    vmsByNode,
886	    servers: servers.map((s) => ({ ...s, hasInflightJob: busy.has(s.id) })),
887	    dedicatedIps: ips,
888	    archivedByVmid,
889	    templateVmids,
890	    prodTag: process.env.NXEON_TAG ?? "nxeon",
891	  });
892	  await finish(job, {
893	    ok: true,
894	    findings,
895	    scannedNodes: nodes.map((n) => ({ id: n.id, name: n.name, vms: vmsByNode[n.id]?.length ?? null })),
