1	/**
2	 * DB-vs-Proxmox drift / orphan detector — PURE. worker/admin-ops.ts collects
3	 * every node's VM list + the relevant DB rows and hands them here; this
4	 * decides what is wrong and which findings are SAFE to clean up in one click.
5	 *
6	 * Safety rules baked in (each from a real near-miss in this fleet):
7	 *  - A VM is only an "orphan" if it carries the PRODUCTION platform tag
8	 *    (provision() tags every VM `${NXEON_TAG};user-xxxx`) AND no Server row
9	 *    owns that vmid. Staging shares the primary node with its own tag and
10	 *    must never be flagged; untagged VMs (mail, Kodely, hosting node, cold-
11	 *    email relay…) are internal infrastructure — reported, never offered for
12	 *    destruction.
13	 *  - Templates (vmid 9000-9999 or `template: 1`) are never orphans.
14	 *  - One-click destroy is offered only for a STOPPED orphan. A running orphan
15	 *    may be something real that lost its row; stop it deliberately first.
16	 *  - A dedicated IP is only "orphaned" when its row claims a server that no
17	 *    longer exists (or claims none while ASSIGNED). It is never released
18	 *    while a live Server row still holds that address.
19	 */
20	
21	export type DriftSeverity = "high" | "medium" | "low" | "info";
22	
23	export type DriftFixKey = "reconcile_status" | "orphan_vm_destroy" | "orphan_ip_release" | "sync_forwards" | "diagnose";
24	
25	export type DriftFinding = {
26	  kind:
27	    | "orphan_vm"
28	    | "unmanaged_vm"
29	    | "missing_vm"
30	    | "wrong_node"
31	    | "status_mismatch"
32	    | "stranded_transitional"
33	    | "duplicate_vmid"
34	    | "ip_orphan"
35	    | "ip_mismatch"
36	    | "ip_conflict"
37	    | "template_missing"
38	    | "node_unreachable";
39	  severity: DriftSeverity;
40	  title: string;
41	  detail: string;
42	  nodeId?: string;
43	  nodeName?: string;
44	  vmid?: number;
45	  serverId?: string;
46	  hostname?: string;
47	  ipId?: string;
48	  fix?: DriftFixKey;
49	};
50	
51	export type PveVm = { vmid: number; name?: string; status?: string; tags?: string; template?: number | boolean };
52	
53	export type DriftInput = {
54	  nodes: { id: string; name: string; isPrimary: boolean; enabled: boolean; acceptsProvisions: boolean }[];
55	  /** nodeId -> its VM list, or null when that node's API could not be read. */
56	  vmsByNode: Record<string, PveVm[] | null>;
57	  servers: {
58	    id: string;
59	    hostname: string;
60	    vmid: number | null;
61	    nodeId: string | null;
62	    status: string;
63	    ipAddress: string | null;
64	    updatedAt: Date;
65	    hasInflightJob: boolean;
66	  }[];
67	  dedicatedIps: { id: string; address: string; status: string; serverId: string | null; nodeId: string; purpose: string }[];
68	  /** Archived (deleted) servers by vmid, for labelling leftovers. */
69	  archivedByVmid: Record<number, { hostname: string; deletedAt: Date }>;
70	  /** Template vmids every provision-accepting node must carry. */
71	  templateVmids: number[];
72	  prodTag: string;
73	  now?: Date;
74	};
75	
76	export function isTemplateVm(v: PveVm): boolean {
77	  return v.template === 1 || v.template === true || (v.vmid >= 9000 && v.vmid <= 9999);
78	}
79	
80	export function vmTags(v: PveVm): string[] {
81	  return String(v.tags ?? "")
82	    .split(/[;,\s]+/)
83	    .map((t) => t.trim().toLowerCase())
84	    .filter(Boolean);
