87	const TRANSITIONAL = new Set(["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"]);
88	const STRANDED_MIN = 60;
89	
90	export function detectDrift(input: DriftInput): DriftFinding[] {
91	  const now = input.now ?? new Date();
92	  const out: DriftFinding[] = [];
93	  const prodTag = input.prodTag.toLowerCase();
94	  const primary = input.nodes.find((n) => n.isPrimary);
95	  const nodeName = (id: string | null | undefined) => input.nodes.find((n) => n.id === id)?.name ?? "?";
96	  const nodeOf = (s: { nodeId: string | null }) => s.nodeId ?? primary?.id ?? null;
97	
98	  const serverByVmid = new Map<number, DriftInput["servers"][number]>();
99	  for (const s of input.servers) if (s.vmid != null) serverByVmid.set(s.vmid, s);
100	
101	  // vmid -> nodes it appears on (real VMs only)
102	  const seenOn = new Map<number, string[]>();
103	  for (const n of input.nodes) {
104	    const vms = input.vmsByNode[n.id];
105	    if (vms == null) {
106	      out.push({
107	        kind: "node_unreachable",
108	        severity: "high",
109	        title: `Could not read VMs on ${n.name}`,
110	        detail: "The node's Proxmox API did not answer — drift on this node is unknown, nothing below covers it.",
111	        nodeId: n.id,
112	        nodeName: n.name,
113	      });
114	      continue;
115	    }
116	    for (const v of vms) {
117	      if (isTemplateVm(v)) continue;
118	      seenOn.set(v.vmid, [...(seenOn.get(v.vmid) ?? []), n.id]);
119	      const owner = serverByVmid.get(v.vmid);
120	      if (owner) {
121	        const ownerNode = nodeOf(owner);
122	        if (ownerNode !== n.id) continue; // handled by wrong_node below
123	        // status mismatch (only for settled DB states)
124	        const pve = String(v.status ?? "");
125	        if (!owner.hasInflightJob && !TRANSITIONAL.has(owner.status)) {
126	          if ((owner.status === "RUNNING" && pve === "stopped") || ((owner.status === "STOPPED" || owner.status === "ERROR") && pve === "running")) {
127	            out.push({
128	              kind: "status_mismatch",
129	              severity: owner.status === "RUNNING" ? "high" : "medium",
130	              title: `${owner.hostname}: DB says ${owner.status}, Proxmox says ${pve}`,
131	              detail: "The dashboard and power controls follow the DB row; reconcile reads the hypervisor and corrects it.",
132	              nodeId: n.id,
133	              nodeName: n.name,
134	              vmid: v.vmid,
135	              serverId: owner.id,
136	              hostname: owner.hostname,
137	              fix: "reconcile_status",
138	            });
139	          }
140	        }
141	        continue;
142	      }
143	      const tags = vmTags(v);
144	      const archived = input.archivedByVmid[v.vmid];
145	      if (tags.includes(prodTag)) {
146	        const stopped = v.status === "stopped";
147	        out.push({
148	          kind: "orphan_vm",
149	          severity: stopped ? "medium" : "high",
150	          title: `Orphan VM ${v.vmid}${v.name ? ` (${v.name})` : ""} on ${n.name}`,
151	          detail:
152	            (archived
153	              ? `Leftover of deleted server ${archived.hostname} (deleted ${archived.deletedAt.toISOString().slice(0, 10)}). `
154	              : "Platform-tagged VM with no Server row. ") +
155	            (stopped
156	              ? "It is stopped and safe to destroy (its vmid is never reused)."
157	              : `It is ${v.status ?? "in an unknown state"} — stop it deliberately before destroying; it may be something real that lost its row.`),
158	          nodeId: n.id,
159	          nodeName: n.name,
160	          vmid: v.vmid,
161	          fix: stopped ? "orphan_vm_destroy" : undefined,
162	        });
163	      } else if (!tags.some((t) => t.startsWith("nxeon"))) {
164	        out.push({
165	          kind: "unmanaged_vm",
166	          severity: "info",
167	          title: `Unmanaged VM ${v.vmid}${v.name ? ` (${v.name})` : ""} on ${n.name}`,
168	          detail: "No platform tag and no Server row — internal infrastructure or a hand-made VM. Never cleaned up automatically.",
169	          nodeId: n.id,
170	          nodeName: n.name,
171	          vmid: v.vmid,
172	        });
173	      }
174	    }
175	  }
176	
177	  for (const [vmid, nodes] of seenOn) {
178	    if (nodes.length > 1) {
179	      out.push({
180	        kind: "duplicate_vmid",
181	        severity: "medium",
182	        title: `vmid ${vmid} exists on ${nodes.length} nodes`,
183	        detail: `Present on ${nodes.map(nodeName).join(", ")}. The nodes aren't clustered so Proxmox allows it, but every vmid-keyed lookup becomes ambiguous.`,
184	        vmid,
185	      });
186	    }
187	  }
188	
189	  // Servers whose VM is not where the DB says.
190	  for (const s of input.servers) {
191	    if (s.vmid == null) {
192	      if (TRANSITIONAL.has(s.status) && !s.hasInflightJob && (now.getTime() - s.updatedAt.getTime()) / 60_000 >= STRANDED_MIN) {
193	        out.push({
194	          kind: "stranded_transitional",
195	          severity: "high",
196	          title: `${s.hostname} stuck in ${s.status} with no job`,
197	          detail: `No VM, no in-flight job, untouched for ${Math.round((now.getTime() - s.updatedAt.getTime()) / 60_000)} min.`,
198	          serverId: s.id,
199	          hostname: s.hostname,
200	          fix: "diagnose",
201	        });
202	      }
203	      continue;
204	    }
205	    const nid = nodeOf(s);
206	    if (!nid) continue;
207	    const vms = input.vmsByNode[nid];
208	    if (vms == null) continue; // node unreachable, already reported
209	    const here = vms.some((v) => v.vmid === s.vmid && !isTemplateVm(v));
210	    if (!here && s.status !== "DELETING") {
211	      const elsewhere = (seenOn.get(s.vmid) ?? []).filter((x) => x !== nid);
212	      out.push(
213	        elsewhere.length
214	          ? {
215	              kind: "wrong_node",
216	              severity: "high",
217	              title: `${s.hostname}: VM ${s.vmid} is on ${elsewhere.map(nodeName).join(", ")}, DB says ${nodeName(nid)}`,
218	              detail: "Every action for this server is sent to the wrong node. Fix the Server.nodeId record (or finish the move) before anything else.",
219	              serverId: s.id,
220	              hostname: s.hostname,
221	              vmid: s.vmid,
222	              nodeId: nid,
223	              nodeName: nodeName(nid),
224	            }
225	          : {
226	              kind: "missing_vm",
