add = '''// ---------------------------------------------------------------------------
// Ownership tags — how the engine proves a VM is ITS OWN before touching it
// ---------------------------------------------------------------------------

/** Tag carried by the in-flight target VM from CREATE_TARGET until FINALIZE
 *  removes it: `nxmove-<moveId>`. Rollback destroys a target VM ONLY when this
 *  tag is present; drift detection never offers a tagged VM for destruction. */
export function moveTargetTag(moveId: string): string {
  if (!/^[a-z0-9]{10,40}$/.test(moveId)) throw new Error(`refusing unexpected move id ${JSON.stringify(moveId)}`);
  return `nxmove-${moveId}`;
}
/** Tag the kept (stopped) source carries from FINALIZE until VM_MOVE_CLEANUP. */
export const MOVED_SOURCE_TAG = "nxeon-moved";
/** Any tag that marks a VM as part of a move — never an "orphan". */
export function isMoveTag(tag: string): boolean {
  return tag === MOVED_SOURCE_TAG || /^nxmove-[a-z0-9]{10,40}$/.test(tag);
}

export function splitTags(tags: unknown): string[] {
  return String(tags ?? "")
    .split(/[;,\\s]+/)
    .map((t) => t.trim())
    .filter(Boolean);
}
export function joinTags(tags: readonly string[]): string {
  return [...new Set(tags)].join(";");
}

/**
 * Is the VM whose config is `cfg` the target THIS move created? Requires the
 * move's own tag; the carried `name` must match too when the plan knows it.
 * A VM at the target vmid WITHOUT the tag is a foreign VM (a vmid collision
 * — see docs/VM-MOVE-DEEP-ANALYSIS.md FMEA) and must never be reused or destroyed.
 */
export function isOurTargetVm(cfg: Record<string, unknown> | null | undefined, moveId: string, expectedName?: string | null): boolean {
  if (!cfg) return false;
  const tags = splitTags(cfg.tags);
  if (!tags.includes(moveTargetTag(moveId))) return false;
  if (expectedName && cfg.name !== undefined && String(cfg.name) !== expectedName) return false;
  return true;
}

/**
 * Is the VM at the source vmid still the source this move left behind? Used
 * by cleanup before the one destructive call the engine ever makes against a
 * source: the name must match the plan, and once FINALIZE recorded the tag it
 * must still be there. A mismatch means vmid confusion — refuse.
 */
export function isKeptSourceVm(
  cfg: Record<string, unknown> | null | undefined,
  opts: { expectedName: string | null | undefined; tagRecorded: boolean },
): { ok: boolean; reason: string } {
  if (!cfg) return { ok: false, reason: "no config" };
  if (opts.expectedName && cfg.name !== undefined && String(cfg.name) !== opts.expectedName) {
    return { ok: false, reason: `name ${String(cfg.name)} != expected ${opts.expectedName}` };
  }
  if (opts.tagRecorded && !splitTags(cfg.tags).includes(MOVED_SOURCE_TAG)) {
    return { ok: false, reason: `tag ${MOVED_SOURCE_TAG} missing` };
  }
  if (cfg.template) return { ok: false, reason: "is a template" };
  return { ok: true, reason: "name/tag match" };
}

