// Dataset destroy guard (shared by zfs-host.ts and node-agent/index.js)
// ---------------------------------------------------------------------------

/**
 * May `zfs destroy -r` run on this dataset? Only a dataset this engine
 * received: a VM disk name, NO VM config for its vmid on that host, and every
 * snapshot it carries is one of ours (a received move dataset holds only
 * nxmove1/nxmove2 snapshots, or none while partial). A dataset carrying any
 * other snapshot (Proxmox snapshots, backup snapshots) belongs to somebody.
 */
export function datasetDestroyAllowed(info: { exists: boolean; snapshots?: string[]; vmConfigExists: boolean }): { ok: boolean; reason: string } {
  if (!info.exists) return { ok: true, reason: "already absent" };
  if (info.vmConfigExists) return { ok: false, reason: "a VM config for this vmid exists on the host — destroy it through Proxmox" };
