/**
 * VM move — the ENGINE. Pure orchestration: every side effect goes through the
 * `MoveWorld` interface below, so the exact same code that moves a customer VM
 * is driven in test/vm-move-engine.test.ts by an in-memory fake fleet with a
 * failure injected at every step boundary (throw, hang→timeout, and "worker
 * crashed here, resume later"), and the safety invariants are ASSERTED rather
 * than read off the code.
 *
 * THE INVARIANTS (docs/VM-MOVE-DEEP-ANALYSIS.md §3), and where each is enforced:
 *
 *   I1  The source VM and its disk are never modified destructively before
 *       COMMIT, and never destroyed by this engine at all. → `SourceHypervisor`
 *       and `SourceZfs` have NO destroy/create/receive members (type-level);
 *       the only writes to the source are: a Proxmox snapshot, a zfs snapshot
 *       named nxmove*, a graceful shutdown/stop, a start (rollback), and —
 *       after COMMIT only — onboot=0 + tag + link_down. Cleanup (worker) is a
 *       separate job with its own verified world.
 *   I2  A destructive call on the TARGET side only ever touches what THIS move
 *       created: a VM is destroyed only if its config carries `nxmove-<moveId>`
 *       (`isOurTargetVm`), a dataset only if `datasetDestroyAllowed`.
 *   I3  Automatic rollback happens only inside the dark window
 *       (`inDarkWindow`) or on the final attempt before it; after COMMIT the
 *       move is forward-only and a human decides.
 *   I4  Never both VMs running at once: the target is started only after the
 *       source is verified stopped; rollback stops the target before starting
 *       the source.
 *   I5  A worker crash at any point resumes correctly: forward from the last
 *       checkpoint, or — if a rollback was in progress — the rollback.
 *   I6  Every rollback step is attempted even if an earlier one failed, and
 *       the source is started back (if it was running) regardless.
 */
import {
  DEFAULT_SHUTDOWN_TIMEOUT_S,
  MOVED_SOURCE_TAG,
  buildTargetConfig,
  inDarkWindow,
  incrementalSnapshotName,
  isOurTargetVm,
  joinTags,
  liveSnapshotName,
  macFromNet0,
  moveSafeVendorSnippet,
  moveTargetTag,
  nextPhase,
  parseScsi0,
  preStopGate,
  remainingRollbackSteps,
  rollbackAllowed,
  rollbackInterrupted,
  shutdownTimeoutDecision,
  splitTags,
  statusAfterMove,
  type RollbackStep,
} from "./plan";
import type { MoveCheckpoints, MovePhase, MovePlan } from "./types";
import type { ZfsDatasetInfo } from "./zfs-host";

// ---------------------------------------------------------------------------
// The world
// ---------------------------------------------------------------------------

export type HvState = "running" | "stopped" | "absent";

/** Everything the engine may do to the TARGET node's hypervisor. */
export interface Hypervisor {
  readonly nodeName: string;
  vmState(vmid: number): Promise<HvState>;
  /** null when the VM does not exist. */
  vmConfig(vmid: number): Promise<Record<string, unknown> | null>;
  setConfig(vmid: number, patch: Record<string, string | number>): Promise<void>;
  listSnapshots(vmid: number): Promise<string[]>;
  createSnapshot(vmid: number, name: string, description: string): Promise<void>;
  deleteSnapshot(vmid: number, name: string): Promise<void>;
  /** Graceful ACPI shutdown; must reject when the guest is still running after `timeoutS`. */
  shutdown(vmid: number, timeoutS: number): Promise<void>;
  /** Hard stop. */
  stop(vmid: number): Promise<void>;
  start(vmid: number): Promise<void>;
  createVm(cfg: Record<string, string | number>): Promise<void>;
  /** `qm destroy` with purge + unreferenced disks. Only ever called on a target VM that passed `isOurTargetVm`. */
  destroyVm(vmid: number): Promise<void>;
  waitGuestAgent(vmid: number, timeoutMs: number): Promise<boolean>;
  /** Best-effort guest file read via the agent; null when unavailable. */
  readGuestFile(vmid: number, path: string): Promise<string | null>;
}

/** The SOURCE hypervisor handle: by construction there is no destroy and no
 *  create here — invariant I1 is a compile error to break. */
export type SourceHypervisor = Omit<Hypervisor, "destroyVm" | "createVm">;

export interface TargetZfs {
  dataset(dataset: string): Promise<ZfsDatasetInfo>;
  deleteSnapshot(dataset: string, snap: string): Promise<void>;
  /** Refuses unless `datasetDestroyAllowed` (implementation-enforced; the engine also checks). */
  destroyDataset(dataset: string): Promise<void>;
  /** Pipe `stream` into `zfs receive -s -F -u dataset`. */
  recv(dataset: string, stream: NodeJS.ReadableStream): Promise<void>;
  vmConfigExists(vmid: number): Promise<boolean>;
}
/** The SOURCE zfs handle: can snapshot, list and send — never destroy a dataset, never receive. */
export interface SourceZfs {
  dataset(dataset: string): Promise<ZfsDatasetInfo>;
  snapshot(dataset: string, snap: string): Promise<void>;
  /** Only this engine's own nxmove* snapshots (asserted by every implementation). */
  deleteSnapshot(dataset: string, snap: string): Promise<void>;
  sendStream(dataset: string, snap: string, from: string | null, opts?: { resumeToken?: string | null }): Promise<NodeJS.ReadableStream>;
}

export type MoveNodeFacts = {
  id: string;
  name: string;
  publicIp: string;
  isPrimary: boolean;
};

export type MoveServerFacts = {
  id: string;
  hostname: string;
  status: string;
  vmid: number | null;
  nodeId: string | null;
  ipAddress: string | null;
  sshPort: number | null;
  subdomain: string | null;
  userId: string;
  userEmail: string | null;
  dedicatedIpAssigned: boolean;
  otherJobsInFlight: number;
};

export type MoveRowFacts = {
  id: string;
  serverId: string;
  status: string;
  phase: string;
  dryRun: boolean;
  plan: MovePlan | null;
  checkpoints: MoveCheckpoints;
  requestedById: string | null;
  startedAt: Date | null;
};

export interface MoveWorld {
  now(): Date;
  /** Env-ish knobs. */
  keepSourceDays: number;
  stallTimeoutMs: number;

  // ---- durable state -----------------------------------------------------------
  loadMove(): Promise<MoveRowFacts>;
  updateMove(data: Partial<{ status: string; phase: string; error: string | null; startedAt: Date; finishedAt: Date; plan: MovePlan; addressChanged: boolean; keepSourceUntil: Date; targetVmid: number; sourceVmid: number; sourceNodeId: string }>): Promise<void>;
  saveCheckpoints(patch: Partial<MoveCheckpoints>, phase?: MovePhase): Promise<MoveCheckpoints>;
  appendLog(phase: string, msg: string): Promise<void>;
  progress(pct: number, step: string): Promise<void>;
  loadServer(): Promise<MoveServerFacts | null>;
  setServerStatus(status: "RUNNING" | "STOPPED"): Promise<void>;
  /** The ONE irreversible write: Server.nodeId/vmid/(ipAddress)/status + DedicatedIp.nodeId/virtualMac + VmMove.addressChanged/keepSourceUntil, in one transaction. */
  commitCutover(args: { targetNodeId: string; targetVmid: number; ipAddress?: string; status: "RUNNING" | "STOPPED"; dedicated: { address: string; virtualMac: string | null } | null; addressChanged: boolean; keepSourceUntil: Date }): Promise<void>;
  /** Fleet-wide, atomic, monotonic vmid claim (lib/vmid-high-water.ts). */
  claimTargetVmid(floor: number): Promise<number>;
  /** Preflight (lib/vm-move/preflight.ts buildMovePlan). */
  preflight(): Promise<MovePlan>;
  /** Reserve a private IP in the target node's pool (in-process + VmMove-aware pickFreeIp). */
  allocateTargetPrivateIp(targetNodeId: string): Promise<string>;
  rootPassword(): Promise<string | null>;

  // ---- fleet -------------------------------------------------------------------
  source: { node: MoveNodeFacts; hv: SourceHypervisor; zfs: SourceZfs };
  target: { node: MoveNodeFacts; hv: Hypervisor; zfs: TargetZfs };
  snippets: { write(node: MoveNodeFacts, storage: string, filename: string, content: string): Promise<void>; delete(node: MoveNodeFacts, storage: string, filename: string): Promise<void> };
  ovh: {
    moveIp(ip: string, toService: string): Promise<number | null>;
    ensureVirtualMac(service: string, ip: string, vmName: string): Promise<string>;
    releaseVirtualMac(service: string, ip: string, mac: string | null): Promise<void>;
    routedTo(ip: string): Promise<string | null>;
  };
  net: {
    syncPortForwards(context: string): Promise<Error | null>;
    checkSsh(host: string, port: number, timeoutMs: number): Promise<{ ok: boolean; error?: string }>;
    checkGamePort(host: string, port: number, protocol: "tcp" | "udp", timeoutMs: number): Promise<{ ok: boolean; error?: string }>;
    targetReachable(): Promise<boolean>;
  };
  dns: { queueGameDnsSync(serverId: string): Promise<void> };
  notify: {
    customer(userId: string, title: string, body: string, href: string): Promise<void>;
    email(to: string, subject: string, text: string, userId: string): Promise<void>;
    admins(title: string, body: string, href: string): Promise<void>;
  };
  audit(action: string, target: string, detail: string): Promise<void>;
  /** What the worker loop considers the last permitted attempt for this job. */
  isFinalAttempt(): boolean;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

export class MoveAbort extends Error {
  constructor(message: string) {
    super(message);
    this.name = "MoveAbort";
  }
}

async function readRow(w: MoveWorld): Promise<{ row: MoveRowFacts; plan: MovePlan; cp: MoveCheckpoints; dedicated: boolean }> {
  const row = await w.loadMove();
  if (!row.plan) throw new Error("move row has no plan");
  return { row, plan: row.plan, cp: row.checkpoints ?? {}, dedicated: row.plan.addressing.kind === "DEDICATED" };
}

/** Pipe a send stream into the target's receive with a stall watchdog and progress. */
async function transfer(w: MoveWorld, plan: MovePlan, snap: string, from: string | null, label: string, resumeToken: string | null): Promise<void> {
  const { PassThrough } = await import("node:stream");
  const total = plan.sourceUsedBytes || 1;
  const stream = await w.source.zfs.sendStream(plan.sourceDataset, snap, from, { resumeToken });
  const meter = new PassThrough();
  let bytes = 0;
  let lastReport = 0;
  let lastByteAt = Date.now();
  meter.on("data", (chunk: Buffer) => {
    bytes += chunk.length;
    lastByteAt = Date.now();
    if (Date.now() - lastReport > 5000) {
      lastReport = Date.now();
      void w.progress(Math.min(99, Math.round((bytes / total) * 100)), `${label}: ${(bytes / 2 ** 30).toFixed(2)} GB sent`);
    }
  });
  // Stall watchdog: a hung agent/ssh/zfs must not hold the job (and the
  // customer's dark window) forever. Resumable receive means a stall costs
  // only the retry, not the bytes already landed.
  const watchdog = setInterval(() => {
    if (Date.now() - lastByteAt > w.stallTimeoutMs) {
      meter.destroy(new Error(`transfer stalled: no bytes for ${Math.round(w.stallTimeoutMs / 1000)}s`));
    }
  }, 5000);
  stream.on("error", (e: Error) => meter.destroy(e));
  stream.pipe(meter);
  try {
    await w.target.zfs.recv(plan.targetDataset, meter);
  } catch (e) {
    (stream as any).destroy?.();
    throw e;
  } finally {
    clearInterval(watchdog);
  }
}

/** Receive-or-resume policy for a dataset that may hold a partial receive. */
export function partialReceiveDecision(info: ZfsDatasetInfo, wantSnap: string): "skip" | "resume" | "restart" | "fresh" {
  if (!info.exists) return "fresh";
  if (info.snapshots.includes(wantSnap)) return "skip";
  if (info.resumeToken) return "resume";
  return "restart";
}

// ---------------------------------------------------------------------------
// Phases
// ---------------------------------------------------------------------------

async function runPhase(w: MoveWorld, phase: MovePhase): Promise<void> {
  const { row, plan, cp, dedicated } = await readRow(w);
  const log = (msg: string) => w.appendLog(phase, msg);
  await w.progress(0, phase);
  const srcHv = w.source.hv;
  const tgtHv = w.target.hv;

  switch (phase) {
    case "SNAPSHOT_LIVE": {
      const name = liveSnapshotName(row.id);
      const existing = await srcHv.listSnapshots(plan.sourceVmid);
      if (!existing.includes(name)) {
        // Disk-only Proxmox snapshot. With the guest agent running Proxmox
        // fs-freezes the guest for the instant of the snapshot (filesystem-
        // consistent); without it the live pass is crash-consistent, which is
        // fine: the FINAL state comes from the incremental pass taken with the
        // VM cleanly shut down.
        await srcHv.createSnapshot(plan.sourceVmid, name, `Nxeon VM move ${row.id} → ${w.target.node.name} (live pass)`);
      }
      await w.saveCheckpoints({ liveSnapshotName: name });
      await log(`consistent snapshot ${name} on ${w.source.node.name}`);
      return;
    }
    case "SEND_FULL": {
      const snap = cp.liveSnapshotName!;
      const info = await w.target.zfs.dataset(plan.targetDataset);
      const decision = partialReceiveDecision(info, snap);
      if (decision === "skip") {
        await log(`target already holds ${plan.targetDataset}@${snap} — skipping the full send`);
      } else {
        let token: string | null = null;
        if (decision === "resume") {
          token = info.exists ? info.resumeToken ?? null : null;
          await log(`resuming the interrupted full send from the receive token`);
        } else if (decision === "restart") {
          // A partial receive with no resume token — nothing usable; start over.
          // destroyDataset refuses anything that is not a move-owned dataset.
          await w.target.zfs.destroyDataset(plan.targetDataset);
          await log(`removed partial ${plan.targetDataset} from an earlier attempt`);
        }
        const t0 = w.now().getTime();
        await transfer(w, plan, snap, null, "Full copy", token);
        await log(`full stream done in ${Math.round((w.now().getTime() - t0) / 1000)}s (${(plan.sourceUsedBytes / 2 ** 30).toFixed(1)} GB used on source)`);
      }
      await w.saveCheckpoints({ fullSentAt: w.now().toISOString() });
      return;
    }
    case "STOP_SOURCE": {
      // Last gate before the customer goes dark: the plan may be hours old.
      const server = await w.loadServer();
      const gate = preStopGate({
        serverStatus: server?.status ?? null,
        dedicated,
        dedicatedIpStillAssigned: !!server?.dedicatedIpAssigned,
        ipRoutedToSource: dedicated && plan.addressing.kind === "DEDICATED" ? (await w.ovh.routedTo(plan.addressing.address).catch(() => null)) === plan.addressing.sourceService || null : null,
        otherJobsInFlight: server?.otherJobsInFlight ?? 0,
        targetAgentOk: await w.net.targetReachable(),
      });
      if (!gate.ok) throw new MoveAbort(`pre-stop gate refused: ${gate.reasons.join("; ")}`);

      const state = await srcHv.vmState(plan.sourceVmid);
      if (state === "absent") throw new MoveAbort(`source vm ${plan.sourceVmid} is ABSENT on ${w.source.node.name}`);
      // Recorded ONCE: a retry after a slow shutdown finds the VM stopped and
      // must not conclude "it was already off" (which would skip START_SOURCE on rollback).
      const sourceWasRunning = cp.sourceWasRunning ?? (state === "running" || server?.status === "RUNNING");
      await w.saveCheckpoints({ sourceWasRunning });
      if (state === "running") {
        const timeoutS = plan.shutdownTimeoutS ?? DEFAULT_SHUTDOWN_TIMEOUT_S;
        try {
          await srcHv.shutdown(plan.sourceVmid, timeoutS);
        } catch (e: any) {
          if (shutdownTimeoutDecision(cp) === "force-stop") {
            await log(`graceful shutdown did not finish in ${timeoutS}s — HARD STOP permitted by the operator (final sync will be crash-consistent)`);
            await srcHv.stop(plan.sourceVmid);
          } else {
            throw new Error(`guest did not shut down within ${timeoutS}s (${e?.message ?? e}); refusing a hard stop — retry later or request the move with allowForceStop`);
          }
        }
        if ((await srcHv.vmState(plan.sourceVmid)) === "running") throw new Error(`vm ${plan.sourceVmid} on ${w.source.node.name} is still running after shutdown`);
      }
      // STOPPED here keeps vmRecoverySweep from restarting the source (it only
      // looks at RUNNING rows) and is also the truth for the customer.
      await w.setServerStatus("STOPPED");
      await w.saveCheckpoints({ sourceStoppedAt: w.now().toISOString(), previousIpAddress: server?.ipAddress ?? null, previousSshPort: server?.sshPort ?? null });
      await log(`source vm ${plan.sourceVmid} stopped (was ${sourceWasRunning ? "running" : "already stopped"}) — dark window opened`);
      return;
    }
    case "SEND_INCREMENTAL": {
      if ((await srcHv.vmState(plan.sourceVmid)) === "running") throw new MoveAbort("source vm is running again — refusing the final sync (someone started it mid-move)");
      const name = cp.incrementalSnapshotName ?? incrementalSnapshotName(row.id);
      const src = await w.source.zfs.dataset(plan.sourceDataset);
      if (!(src.exists && src.snapshots.includes(name))) await w.source.zfs.snapshot(plan.sourceDataset, name);
      await w.saveCheckpoints({ incrementalSnapshotName: name });
      const tgt = await w.target.zfs.dataset(plan.targetDataset);
      const decision = partialReceiveDecision(tgt, name);
      if (decision === "skip") {
        await log(`target already holds @${name} — skipping incremental`);
      } else {
        if (decision === "fresh" || (tgt.exists && !tgt.snapshots.includes(cp.liveSnapshotName!))) {
          throw new Error(`target dataset lost the full-pass snapshot @${cp.liveSnapshotName} — cannot send an incremental on top`);
        }
        // An interrupted incremental either left a resume token (resume it) or
        // nothing (zfs receive is atomic per stream: the dataset is back at the
        // full-pass snapshot and the incremental simply runs again).
        const token = decision === "resume" && tgt.exists ? tgt.resumeToken ?? null : null;
        const t0 = w.now().getTime();
        await transfer(w, plan, name, cp.liveSnapshotName!, "Final sync", token);
        await log(`incremental stream done in ${Math.round((w.now().getTime() - t0) / 1000)}s`);
      }
      await w.saveCheckpoints({ incrementalSentAt: w.now().toISOString() });
      return;
    }
    case "CREATE_TARGET": {
      const server = await w.loadServer();
      if (!server) throw new MoveAbort("server row vanished mid-move");
      const srcCfg = await srcHv.vmConfig(plan.sourceVmid);
      const disk = parseScsi0(String(srcCfg?.scsi0 ?? ""));
      if (!disk) throw new Error("source scsi0 unreadable at CREATE_TARGET");

      const snippetName = `nxeon-${plan.targetVmid}.yaml`;
      await w.snippets.write(w.target.node, plan.targetSnippetStorage, snippetName, moveSafeVendorSnippet());
      await w.saveCheckpoints({ targetSnippetWritten: true });

      let network: Parameters<typeof buildTargetConfig>[0]["network"];
      let targetPrivateIp: string | undefined;
      if (plan.addressing.kind === "DEDICATED") {
        network = { kind: "DEDICATED", address: plan.addressing.address, gateway: plan.addressing.targetGateway, virtualMac: cp.targetVirtualMac ?? "02:00:00:00:00:00", bridge: "vmbr0" };
      } else {
        targetPrivateIp = cp.targetPrivateIp ?? (await w.allocateTargetPrivateIp(w.target.node.id));
        // Persist the reservation BEFORE the VM exists so lib/ipam.ts can
        // exclude it from every other allocation while this move is RUNNING.
        if (!cp.targetPrivateIp) await w.saveCheckpoints({ targetPrivateIp });
        network = { kind: "NAT", privateIp: targetPrivateIp, gateway: plan.addressing.targetGateway, mac: macFromNet0(srcCfg?.net0 as string | undefined), bridge: plan.targetBridge };
      }
      const cfg = buildTargetConfig({
        targetVmid: plan.targetVmid,
        carried: plan.carriedConfig,
        disk,
        targetStorage: plan.targetStorage,
        snippetStorage: plan.targetSnippetStorage,
        network,
        cipassword: await w.rootPassword(),
        moveId: row.id,
      });
      const existingCfg = await tgtHv.vmConfig(plan.targetVmid);
      if (existingCfg === null) {
        await tgtHv.createVm(cfg);
      } else if (isOurTargetVm(existingCfg, row.id, plan.carriedConfig.name)) {
        await log(`target vm ${plan.targetVmid} already exists and carries ${moveTargetTag(row.id)} — reusing`);
      } else {
        // A VM at our vmid that we did not create: vmid collision. Never reuse,
        // never destroy — abort so the operator looks (I2).
        throw new MoveAbort(`a FOREIGN vm already exists at vmid ${plan.targetVmid} on ${w.target.node.name} (no ${moveTargetTag(row.id)} tag) — refusing to touch it`);
      }
      // The received dataset still carries this engine's two snapshots; the
      // target VM must start clean (Proxmox knows nothing about them).
      for (const s of [cp.liveSnapshotName, cp.incrementalSnapshotName]) if (s) await w.target.zfs.deleteSnapshot(plan.targetDataset, s).catch(() => {});
      await w.saveCheckpoints({ targetVmCreated: true });
      await log(`target vm ${plan.targetVmid} created on ${w.target.node.name} (${network.kind}${targetPrivateIp ? ` ${targetPrivateIp}` : ""})`);
      return;
    }
    case "MOVE_IP": {
      if (plan.addressing.kind !== "DEDICATED") return;
      const a = plan.addressing;
      const taskId = await w.ovh.moveIp(a.address, a.targetService);
      await w.saveCheckpoints({ ipMovedAt: w.now().toISOString(), ...(taskId !== null ? { ipMoveTaskId: taskId } : {}) });
      await log(`OVH routed ${a.address} → ${a.targetService}${taskId !== null ? ` (task ${taskId})` : " (already there)"}`);
      const mac = await w.ovh.ensureVirtualMac(a.targetService, a.address, `nxeon-${plan.targetVmid}`);
      await tgtHv.setConfig(plan.targetVmid, { net0: `virtio=${mac},bridge=vmbr0`, ipconfig0: `ip=${a.address}/32,gw=${a.targetGateway}` });
      await w.saveCheckpoints({ targetVirtualMac: mac });
      await log(`virtual MAC ${mac} bound on ${a.targetService}; target net0 updated`);
      return;
    }
    case "START_TARGET": {
      // I4: never both running.
      if ((await srcHv.vmState(plan.sourceVmid)) === "running") throw new MoveAbort("source vm is running — refusing to start the target alongside it");
      if (dedicated && !cp.targetVirtualMac) throw new Error("target has no virtual MAC yet — MOVE_IP did not complete");
      if ((await tgtHv.vmState(plan.targetVmid)) !== "running") await tgtHv.start(plan.targetVmid);
      await w.saveCheckpoints({ targetStartedAt: w.now().toISOString() });
      await w.progress(90, "Waiting for the guest agent…");
      const agentOk = await tgtHv.waitGuestAgent(plan.targetVmid, 240_000);
      await log(agentOk ? "guest agent answered on the target" : "guest agent did NOT answer within 240s");
      let sshOk = false;
      let detail = "";
      if (plan.addressing.kind === "DEDICATED") {
        const r = await w.net.checkSsh(plan.addressing.address, 22, 180_000);
        sshOk = r.ok;
        detail = `${plan.addressing.address}:22 ${r.ok ? "answered" : `no SSH banner (${r.error ?? "timeout"})`}`;
      } else {
        // NAT rules for the new address are installed at FINALIZE (they key off
        // Server.nodeId/ipAddress); the guest agent is the pre-commit proof.
        sshOk = agentOk;
        detail = `NAT guest ${cp.targetPrivateIp ?? "?"} — external SSH verified after FINALIZE's NAT sync`;
      }
      if (!agentOk && !sshOk) throw new Error(`target vm ${plan.targetVmid} started but neither the guest agent nor SSH answered (${detail})`);
      await w.saveCheckpoints({ targetVerified: true });
      await log(`target verified: ${detail}`);
      return;
    }
    case "COMMIT": {
      const server = await w.loadServer();
      if (!server) throw new MoveAbort("server row vanished mid-move");
      if (!["RUNNING", "STOPPED"].includes(server.status)) throw new MoveAbort(`server status is ${server.status} — refusing to commit`);
      const addressChanged = plan.addressing.kind === "NAT";
      const keepSourceUntil = new Date(w.now().getTime() + w.keepSourceDays * 86_400_000);
      await w.commitCutover({
        targetNodeId: w.target.node.id,
        targetVmid: plan.targetVmid,
        ...(plan.addressing.kind === "NAT" && cp.targetPrivateIp ? { ipAddress: cp.targetPrivateIp } : {}),
        status: statusAfterMove(cp.sourceWasRunning),
        dedicated: plan.addressing.kind === "DEDICATED" ? { address: plan.addressing.address, virtualMac: cp.targetVirtualMac ?? null } : null,
        addressChanged,
        keepSourceUntil,
      });
      await w.saveCheckpoints({ committedAt: w.now().toISOString() });
      await log(`DB cutover: node ${w.source.node.name} → ${w.target.node.name}, vmid ${plan.sourceVmid} → ${plan.targetVmid}${cp.targetPrivateIp ? `, private IP → ${cp.targetPrivateIp}` : ""} — point of no return`);
      return;
    }
    case "FINALIZE": {
      // Every step here is idempotent and individually checkpointed, so a
      // failure anywhere is retried without redoing the rest (the old COMMIT
      // did all of this after its checkpoint and a retry skipped it all).
      const server = await w.loadServer();
      if (!server) throw new Error("server row vanished after commit");

      if (!cp.sourceOnbootDisabled) {
        // The source must never come back on its own (a node reboot runs
        // onboot guests), must be visibly a moved leftover, and must not be
        // able to talk even if someone starts it by hand (link_down).
        try {
          const srcCfg = (await srcHv.vmConfig(plan.sourceVmid)) ?? {};
          const tags = joinTags([...splitTags(srcCfg.tags), MOVED_SOURCE_TAG]);
          const net0 = String(srcCfg.net0 ?? "");
          const patch: Record<string, string | number> = { onboot: 0, tags };
          if (net0 && !/link_down=1/.test(net0)) patch.net0 = `${net0},link_down=1`;
          await srcHv.setConfig(plan.sourceVmid, patch);
          await w.saveCheckpoints({ sourceOnbootDisabled: true });
          await log(`source vm ${plan.sourceVmid}: onboot=0, tag ${MOVED_SOURCE_TAG}, link down`);
        } catch (e: any) {
          await log(`WARNING: could not neutralise the source vm: ${e?.message ?? e} — set onboot=0 by hand before the next ${w.source.node.name} reboot`);
          await w.notify.admins(`VM move ${row.id}: source not neutralised`, `Set onboot=0 on vmid ${plan.sourceVmid} (${w.source.node.name}) by hand: ${String(e?.message ?? e).slice(0, 300)}`, "/admin/ops");
        }
      }

      if (!cp.natSyncedAt) {
        const natErr = await w.net.syncPortForwards(`vm move ${server.hostname}`);
        if (natErr) throw new Error(`NAT sync failed: ${natErr.message}`);
        await w.saveCheckpoints({ natSyncedAt: w.now().toISOString() });
        await log("NAT chains reconciled on every node");
      }

      // Post-move verification from OUTSIDE the target node: what the customer dials.
      const verification: NonNullable<MoveCheckpoints["verification"]> = { ...(cp.verification ?? {}) };
      const shouldBeUp = statusAfterMove(cp.sourceWasRunning) === "RUNNING";
      if (shouldBeUp && verification.sshOk === undefined) {
        if (plan.addressing.kind === "NAT" && server.sshPort) {
          const r = await w.net.checkSsh(w.target.node.publicIp, server.sshPort, 120_000);
          verification.sshOk = r.ok;
          await log(`external SSH ${w.target.node.publicIp}:${server.sshPort} ${r.ok ? "answered" : `did not answer (${r.error ?? "timeout"})`}`);
        } else if (plan.addressing.kind === "DEDICATED") {
          verification.sshOk = cp.targetVerified ?? null;
        }
        if (plan.gameProbe) {
          const host = plan.addressing.kind === "DEDICATED" ? plan.addressing.address : w.target.node.publicIp;
          const port = plan.addressing.kind === "DEDICATED" ? plan.gameProbe.port : (plan.addressing.forwardPorts.length ? null : null);
          // For NAT the public game port is a PortForward row; the worker adapter
          // resolves it into plan.gameProbe.port at preflight when one exists.
          const probePort = port ?? plan.gameProbe.port;
          const r = await w.net.checkGamePort(host, probePort, plan.gameProbe.protocol, 300_000);
          verification.gamePortOk = r.ok;
          await log(`game port ${host}:${probePort}/${plan.gameProbe.protocol} ${r.ok ? "answered" : `did not answer (${r.error ?? "timeout"})`}`);
        }
        await w.saveCheckpoints({ verification });
        if (verification.sshOk === false || verification.gamePortOk === false) {
          await w.notify.admins(
            `VM move ${row.id}: ${server.hostname} moved but a probe failed`,
            `ssh=${verification.sshOk} game=${verification.gamePortOk ?? "n/a"} on ${w.target.node.name}. The DB points at the target; check the guest's network (cloud-init re-IP) before telling the customer.`,
            `/admin/servers/${server.id}`,
          );
        }
      }
      if (!shouldBeUp && (await tgtHv.vmState(plan.targetVmid)) === "running") {
        // The customer had it stopped: it was booted once so cloud-init could re-IP it; put it back the way it was.
        await tgtHv.shutdown(plan.targetVmid, 120).catch(() => tgtHv.stop(plan.targetVmid));
        await log("server was STOPPED before the move — target booted once for the re-IP and stopped again");
      }

      if (server.subdomain && !cp.dnsQueuedAt) {
        await w.dns.queueGameDnsSync(server.id);
        await w.saveCheckpoints({ dnsQueuedAt: w.now().toISOString() });
        await log(`queued SYNC_GAME_DNS for ${server.subdomain}`);
      }

      if (!cp.noticesSentAt) {
        const addressChanged = plan.addressing.kind === "NAT";
        if (addressChanged) {
          const title = `${server.hostname}: new connection address`;
          const body =
            `Your server ${server.hostname} now runs on upgraded hardware and has a new public address: ${w.target.node.publicIp}. ` +
            `Your SSH port${server.sshPort ? ` (${server.sshPort})` : ""} and any game ports are unchanged${server.subdomain ? `, and ${server.subdomain}.play.nxeon.cloud already points at the new address` : ""}. ` +
            `Please update any saved connections that use the old address (${w.source.node.publicIp}), and any DNS records of your own domains that point at it.`;
          await w.notify.customer(server.userId, title, body, `/dashboard/servers/${server.id}`);
          if (server.userEmail) await w.notify.email(server.userEmail, title, `${body}\n\nNothing else about your server changed — same data, same plan, same root password.`, server.userId);
        } else {
          await w.notify.customer(server.userId, `${server.hostname} was moved to upgraded hardware`, "A short restart happened during the move. Your IP address, ports and data are unchanged.", `/dashboard/servers/${server.id}`);
        }
        await w.saveCheckpoints({ noticesSentAt: w.now().toISOString() });
      }

      await w.audit("server.vm_move", server.hostname, `${w.source.node.name}(vmid ${plan.sourceVmid}) → ${w.target.node.name}(vmid ${plan.targetVmid}) ${plan.addressing.kind}${plan.addressing.kind === "NAT" ? " address-changed" : ""} move=${row.id}`);
      await w.saveCheckpoints({ finalizedAt: w.now().toISOString() });
      await log(`move complete; source vm ${plan.sourceVmid} kept STOPPED on ${w.source.node.name} for ${w.keepSourceDays} days`);
      return;
    }
    case "PREFLIGHT":
    case "DONE":
      return;
  }
}

// ---------------------------------------------------------------------------
// Rollback
// ---------------------------------------------------------------------------

export async function rollback(w: MoveWorld, why: string): Promise<{ ok: boolean; errors: string[] }> {
  const { row, plan, cp, dedicated } = await readRow(w);
  const steps = remainingRollbackSteps(cp, { dedicated });
  const done: string[] = [...(cp.rollback?.steps ?? [])];
  const errors: string[] = [...(cp.rollback?.errors ?? [])];
  const startedAt = cp.rollback?.startedAt ?? w.now().toISOString();
  await w.appendLog("ROLLBACK", `${cp.rollback?.startedAt ? "continuing" : "starting"} rollback (${why}); steps: ${steps.join(" → ") || "none"}`);
  await w.saveCheckpoints({ rollback: { startedAt, steps: done, errors } });

  const record = async (step: RollbackStep, err?: string) => {
    if (err) errors.push(`${step}: ${err.slice(0, 300)}`);
    else done.push(step);
    // Checkpoint after EVERY step so a crash mid-rollback resumes the rollback (I5).
    await w.saveCheckpoints({ rollback: { startedAt, steps: done, errors } });
  };

  for (const step of steps) {
    try {
      switch (step) {
        case "MOVE_IP_BACK": {
          if (plan.addressing.kind !== "DEDICATED") break;
          const a = plan.addressing;
          await w.ovh.releaseVirtualMac(a.targetService, a.address, cp.targetVirtualMac ?? null);
          await w.ovh.moveIp(a.address, a.sourceService);
          const mac = await w.ovh.ensureVirtualMac(a.sourceService, a.address, `nxeon-${plan.sourceVmid}`);
          await w.source.hv.setConfig(plan.sourceVmid, { net0: `virtio=${mac},bridge=vmbr0`, ipconfig0: `ip=${a.address}/32,gw=${a.sourceGateway}` });
          await w.commitCutover; // (no-op reference: the DB DedicatedIp row was never changed before COMMIT)
          break;
        }
        case "STOP_TARGET":
          if ((await w.target.hv.vmState(plan.targetVmid)) === "running") await w.target.hv.stop(plan.targetVmid);
          break;
        case "DESTROY_TARGET_VM": {
          const cfg = await w.target.hv.vmConfig(plan.targetVmid);
          if (cfg === null) break; // already gone
          if (!isOurTargetVm(cfg, row.id, plan.carriedConfig.name)) {
            throw new Error(`vm ${plan.targetVmid} on ${w.target.node.name} does not carry ${moveTargetTag(row.id)} — NOT destroyed (foreign VM?)`);
          }
          if ((await w.target.hv.vmState(plan.targetVmid)) === "running") await w.target.hv.stop(plan.targetVmid);
          await w.target.hv.destroyVm(plan.targetVmid);
          if ((await w.target.hv.vmState(plan.targetVmid)) !== "absent") throw new Error(`destroy of vm ${plan.targetVmid} reported success but it is still present`);
          break;
        }
        case "DESTROY_TARGET_DATASET":
          await w.target.zfs.destroyDataset(plan.targetDataset);
          break;
        case "DELETE_TARGET_SNIPPET":
          await w.snippets.delete(w.target.node, plan.targetSnippetStorage, `nxeon-${plan.targetVmid}.yaml`);
          break;
        case "DELETE_SOURCE_INCREMENTAL_SNAPSHOT":
          if (cp.incrementalSnapshotName) await w.source.zfs.deleteSnapshot(plan.sourceDataset, cp.incrementalSnapshotName);
          break;
        case "START_SOURCE": {
          // I4: the target must be down before the source comes back.
          const t = await w.target.hv.vmState(plan.targetVmid).catch(() => "absent" as HvState);
          if (t === "running") throw new Error("target vm still running — not starting the source alongside it");
          if ((await w.source.hv.vmState(plan.sourceVmid)) !== "running") await w.source.hv.start(plan.sourceVmid);
          break;
        }
        case "RESTORE_DB_STATUS":
          await w.setServerStatus(statusAfterMove(cp.sourceWasRunning));
          break;
      }
      await record(step);
    } catch (e: any) {
      await record(step, String(e?.message ?? e));
    }
  }
  // The live-pass Proxmox snapshot is harmless but pointless now (best-effort).
  if (cp.liveSnapshotName) await w.source.hv.deleteSnapshot(plan.sourceVmid, cp.liveSnapshotName).catch(() => {});
  await w.saveCheckpoints({ rollback: { startedAt, finishedAt: w.now().toISOString(), steps: done, errors } });
  await w.appendLog("ROLLBACK", errors.length ? `finished WITH ERRORS: ${errors.join(" | ")}` : `finished cleanly (${done.join(", ")})`);
  return { ok: errors.length === 0, errors };
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

export type RunOutcome = "DONE" | "PLANNED" | "ROLLED_BACK" | "FAILED" | "RETRY";

/**
 * Run (or resume) a move. Throws to signal the worker loop "retry" (RETRY)
 * or a terminal failure; returns normally for DONE/PLANNED. The outcome is
 * also returned for callers that do not use exceptions (tests).
 */
export async function runMove(w: MoveWorld): Promise<RunOutcome> {
  let row = await w.loadMove();
  if (row.status === "DONE" || row.status === "CLEANED") return "DONE";
  if (row.status === "ROLLED_BACK" || row.status === "FAILED") throw new Error(`move is ${row.status}`);

  // ---- PREFLIGHT ------------------------------------------------------------------
  if (!row.plan || row.phase === "PREFLIGHT") {
    await w.progress(2, "Preflight…");
    const plan = await w.preflight();
    const failed = plan.checks.filter((c) => !c.ok && c.blocking);
    if (row.dryRun) {
      await w.updateMove({ plan, targetVmid: plan.targetVmid, sourceVmid: plan.sourceVmid, sourceNodeId: plan.sourceNodeId, status: "PLANNED", phase: "PREFLIGHT", finishedAt: w.now(), error: failed.length ? `preflight: ${failed.map((c) => c.detail).join("; ")}` : null });
      await w.appendLog("PREFLIGHT", `dry run: ${plan.ok ? "all blocking checks passed" : `${failed.length} blocking check(s) failed`}`);
      return "PLANNED";
    }
    if (!plan.ok) {
      const error = `preflight failed: ${failed.map((c) => `[${c.id}] ${c.detail}`).join("; ")}`.slice(0, 1900);
      await w.updateMove({ plan, sourceVmid: plan.sourceVmid, sourceNodeId: plan.sourceNodeId, status: "FAILED", error, finishedAt: w.now() });
      await w.appendLog("PREFLIGHT", error);
      throw new Error(error);
    }
    // CLAIM the target vmid from the fleet-wide high-water mark so no PROVISION
    // (and no concurrent move) can ever be handed the same id. The plan's
    // candidate is only a floor.
    const claimed = await w.claimTargetVmid(plan.targetVmid);
    const slash = plan.targetDataset.lastIndexOf("/");
    const pool = slash > 0 ? plan.targetDataset.slice(0, slash) : "";
    const finalPlan: MovePlan = { ...plan, version: 2, targetVmid: claimed, targetDataset: pool ? `${pool}/vm-${claimed}-disk-0` : plan.targetDataset };
    const existing = await w.target.zfs.dataset(finalPlan.targetDataset).catch(() => null);
    if (existing?.exists) throw new Error(`claimed vmid ${claimed} but ${finalPlan.targetDataset} already exists on ${w.target.node.name}`);
    if ((await w.target.hv.vmConfig(claimed)) !== null) throw new Error(`claimed vmid ${claimed} but a VM with that id exists on ${w.target.node.name}`);
    await w.updateMove({ plan: finalPlan, targetVmid: claimed, sourceVmid: finalPlan.sourceVmid, sourceNodeId: finalPlan.sourceNodeId, status: "RUNNING", phase: "SNAPSHOT_LIVE", startedAt: row.startedAt ?? w.now() });
    await w.appendLog("PREFLIGHT", `plan ok: ${finalPlan.sourceNodeName} vmid ${finalPlan.sourceVmid} → ${finalPlan.targetNodeName} vmid ${claimed} (${finalPlan.addressing.kind}, ${(finalPlan.sourceUsedBytes / 2 ** 30).toFixed(1)} GB, est. dark window ${finalPlan.estimatedDowntimeSec}s)`);
    row = await w.loadMove();
  }

  const dedicated = row.plan!.addressing.kind === "DEDICATED";

  // ---- a rollback that was interrupted must be finished first (I5) ----------------
  if (rollbackInterrupted(row.checkpoints)) {
    const r = await rollback(w, "continuing an interrupted rollback");
    await w.updateMove({ status: r.ok ? "ROLLED_BACK" : "FAILED", error: r.ok ? "rolled back" : `rollback errors: ${r.errors.join(" | ")}`.slice(0, 1900), finishedAt: w.now() });
    if (!r.ok) await w.notify.admins(`VM move ${row.id} needs attention`, `Rollback incomplete: ${r.errors.join(" | ")}`.slice(0, 900), "/admin/ops");
    throw new Error(r.ok ? "move rolled back" : `rollback incomplete: ${r.errors.join(" | ")}`);
  }

  for (;;) {
    row = await w.loadMove();
    const cp = row.checkpoints;

    // Operator rollback request — honoured at EVERY phase boundary, not only at job start.
    if (cp.rollbackRequested && rollbackAllowed(cp)) {
      const r = await rollback(w, "requested by operator");
      await w.updateMove({ status: r.ok ? "ROLLED_BACK" : "FAILED", error: r.ok ? "rolled back on request" : `rollback errors: ${r.errors.join(" | ")}`.slice(0, 1900), finishedAt: w.now() });
      throw new Error(r.ok ? "move rolled back on request" : `rollback incomplete: ${r.errors.join(" | ")}`);
    }

    const phase = nextPhase(cp, { dedicated });
    if (phase === "DONE") {
      if (row.status !== "DONE") await w.updateMove({ status: "DONE", phase: "DONE", finishedAt: w.now() });
      await w.progress(100, "Move complete");
      return "DONE";
    }
    await w.updateMove({ phase });
    try {
      await runPhase(w, phase);
    } catch (e: any) {
      const msg = String(e?.message ?? e).slice(0, 1500);
      await w.appendLog(phase, `FAILED: ${msg}`);
      const abort = e instanceof MoveAbort;
      if (inDarkWindow(cp) || (abort && !cp.committedAt)) {
        // Customer is down (or the world changed under us): undo now.
        const r = await rollback(w, `${phase} failed: ${msg}`);
        await w.updateMove({ status: r.ok ? "ROLLED_BACK" : "FAILED", error: `${phase}: ${msg}${r.ok ? " (rolled back; source as before)" : ` — ROLLBACK INCOMPLETE: ${r.errors.join(" | ")}`}`.slice(0, 1900), finishedAt: w.now() });
        if (!r.ok) await w.notify.admins(`VM move ${row.id} needs attention`, `Rollback incomplete after ${phase} failed: ${r.errors.join(" | ")}`.slice(0, 900), "/admin/ops");
        throw new Error(`${phase} failed: ${msg}${r.ok ? " — rolled back" : " — rollback incomplete"}`);
      }
      const finalAttempt = w.isFinalAttempt();
      if (finalAttempt && !cp.committedAt) {
        const r = await rollback(w, `${phase} failed on the last attempt: ${msg}`);
        await w.updateMove({ status: r.ok ? "ROLLED_BACK" : "FAILED", error: `${phase}: ${msg}${r.ok ? " (target side cleaned up)" : ` — cleanup errors: ${r.errors.join(" | ")}`}`.slice(0, 1900), finishedAt: w.now() });
        throw new Error(`${phase} failed: ${msg}`);
      }
      if (finalAttempt && cp.committedAt) {
        await w.updateMove({ status: "FAILED", error: `post-commit ${phase} failed: ${msg} — the server IS live on the target; finish NAT sync / DNS / notice by hand`.slice(0, 1900), finishedAt: w.now() });
        await w.notify.admins(`VM move ${row.id}: post-commit step failed`, `${phase}: ${msg}`.slice(0, 900), "/admin/ops");
        throw new Error(`post-commit ${phase} failed: ${msg}`);
      }
      // Before the dark window (or after commit): keep the row RUNNING and let the worker retry from the checkpoint.
      await w.updateMove({ error: `${phase}: ${msg}` });
      throw e;
    }
  }
}

