/**
 * The ZFS seam for VM moves — the same shape lib/nat-rules.ts's NatHost gives
 * NAT: every host-level ZFS operation a move needs, as an interface with three
 * implementations and one place that picks between them:
 *
 *   - localZfsHost()  — the primary itself (the worker runs there as root;
 *                       `zfs` is a local child process, argv arrays only).
 *   - agentZfsHost()  — any non-primary node, over its node-agent's
 *                       /v1/zfs/* endpoints (node-agent v2). The architecture's
 *                       standing rule: host-level work on another node goes
 *                       through its agent, not SSH.
 *   - sshZfsHost()    — TRANSITION FALLBACK ONLY (VM_MOVE_TRANSPORT=ssh): root
 *                       SSH from the primary to the node, for the window until
 *                       every node's agent has been updated to v2. Same argv
 *                       discipline, same dataset/snapshot allowlists. Remove
 *                       once every node reports agent version ≥ 2.
 *
 * Streams are zstd-compressed on the wire in every implementation so a
 * local→agent, agent→agent or ssh→local pairing all interoperate.
 *
 * RESUMABLE RECEIVE (2026-10-01 hardening): `zfs receive -s` leaves a
 * `receive_resume_token` on an interrupted dataset; `dataset()` reports it and
 * `sendStream(..., { resumeToken })` continues with `zfs send -t <token>`
 * instead of re-streaming a 50 GB disk after a WAN hiccup.
 *
 * DESTROY GUARD: `destroyDataset` refuses unless lib/vm-move/plan.ts's
 * `datasetDestroyAllowed` says the dataset is move-owned (no VM config for its
 * vmid on this host, and every snapshot it carries is an nxmove* one).
 */
import { spawn } from "node:child_process";
import { PassThrough, type Readable } from "node:stream";
import { pipeline } from "node:stream/promises";
import {
  agentZfsDataset,
  agentZfsDeleteSnapshot,
  agentZfsDestroyDataset,
  agentZfsRecv,
  agentZfsSendStream,
  agentZfsSnapshot,
  agentZfsVmConfigExists,
  type AgentNode,
} from "../node-agent";
import { MOVE_SNAPSHOT_RE, datasetDestroyAllowed, parseVmDataset } from "./plan";

export type ZfsDatasetInfo =
  | { exists: false }
  | { exists: true; usedBytes: number; referencedBytes: number; volsizeBytes: number; snapshots: string[]; resumeToken: string | null };

export type ZfsHost = {
  label: string;
  dataset(dataset: string): Promise<ZfsDatasetInfo>;
  snapshot(dataset: string, snap: string): Promise<void>;
  deleteSnapshot(dataset: string, snap: string): Promise<void>;
  /** Destroys the dataset and its snapshots. Refuses unless `datasetDestroyAllowed`. */
  destroyDataset(dataset: string): Promise<void>;
  /** zstd-compressed `zfs send [-i @from] dataset@snap`, or `zfs send -t <token>` to resume. */
  sendStream(dataset: string, snap: string, from?: string | null, opts?: { resumeToken?: string | null }): Promise<Readable>;
  /** `zstd -d | zfs receive -s -F -u dataset` fed from `body`. Resolves on exit 0. */
  recv(dataset: string, body: Readable): Promise<void>;
  /** Does /etc/pve/qemu-server/<vmid>.conf exist on this host? */
  vmConfigExists(vmid: number): Promise<boolean>;
};

export function assertDataset(dataset: string): void {
  if (!parseVmDataset(dataset)) throw new Error(`refusing unexpected dataset name ${JSON.stringify(dataset)}`);
}
export function assertSnap(snap: string): void {
  if (!MOVE_SNAPSHOT_RE.test(snap)) throw new Error(`refusing unexpected snapshot name ${JSON.stringify(snap)}`);
}
/** Receive-resume tokens are opaque base64-ish blobs; keep them shell-inert. */
export const RESUME_TOKEN_RE = /^[A-Za-z0-9+/=_-]{16,4096}$/;
export function assertResumeToken(token: string): void {
  if (!RESUME_TOKEN_RE.test(token)) throw new Error("refusing malformed zfs receive_resume_token");
}

type Runner = (argv: string[]) => Promise<string>;
type Spawner = (argv: string[]) => import("node:child_process").ChildProcess;

function execArgv(cmd: string, args: string[], timeoutMs = 60_000): Promise<string> {
  return new Promise((resolve, reject) => {
    const child = spawn(cmd, args, { stdio: ["ignore", "pipe", "pipe"] });
    let out = "";
    let err = "";
    const timer = setTimeout(() => child.kill("SIGKILL"), timeoutMs);
    child.stdout.on("data", (d) => (out += d.toString()));
    child.stderr.on("data", (d) => (err += d.toString().slice(0, 2000)));
    child.on("error", (e) => {
      clearTimeout(timer);
      reject(e);
    });
    child.on("close", (code) => {
      clearTimeout(timer);
      if (code === 0) resolve(out);
      else reject(new Error(`${cmd} ${args.slice(0, 3).join(" ")}… exited ${code}: ${err.trim().slice(0, 400)}`));
    });
  });
}

/** Parse the `zfs get -H -o value receive_resume_token` answer ("-" = none). */
export function parseResumeToken(raw: string): string | null {
  const v = raw.trim();
  if (!v || v === "-") return null;
  return RESUME_TOKEN_RE.test(v) ? v : null;
}

/**
 * Build a host out of two primitives: `run(argv)` executes `zfs …`/`test …`
 * and returns stdout; `spawnCmd(argv)` starts a long-running process whose
 * stdin/stdout are streams. Local and SSH differ only in how argv is wrapped.
 */
function commandZfsHost(label: string, run: Runner, spawnCmd: Spawner): ZfsHost {
  const vmConfigExists = async (vmid: number) => {
    try {
      await run(["test", "-e", `/etc/pve/qemu-server/${vmid}.conf`]);
      return true;
    } catch {
      return false;
    }
  };
  const dataset = async (ds: string): Promise<ZfsDatasetInfo> => {
    assertDataset(ds);
    let line: string;
    try {
      line = await run(["zfs", "list", "-Hp", "-o", "used,referenced,volsize", ds]);
    } catch (e: any) {
      if (/does not exist/.test(String(e?.message))) return { exists: false };
      throw e;
    }
    const [used, referenced, volsize] = line.trim().split(/\s+/).map(Number);
    const snapsRaw = await run(["zfs", "list", "-Hp", "-t", "snapshot", "-o", "name", "-d", "1", ds]).catch(() => "");
    const snapshots = snapsRaw
      .split("\n")
      .map((s) => s.trim())
      .filter(Boolean)
      .map((s) => s.slice(s.indexOf("@") + 1));
    const tokenRaw = await run(["zfs", "get", "-H", "-o", "value", "receive_resume_token", ds]).catch(() => "-");
    return { exists: true, usedBytes: used, referencedBytes: referenced, volsizeBytes: volsize, snapshots, resumeToken: parseResumeToken(tokenRaw) };
  };
  return {
    label,
    dataset,
    vmConfigExists,
    async snapshot(ds, snap) {
      assertDataset(ds);
      assertSnap(snap);
      await run(["zfs", "snapshot", `${ds}@${snap}`]);
    },
    async deleteSnapshot(ds, snap) {
      assertDataset(ds);
      assertSnap(snap);
      try {
        await run(["zfs", "destroy", `${ds}@${snap}`]);
      } catch (e: any) {
        if (!/does not exist/.test(String(e?.message))) throw e;
      }
    },
    async destroyDataset(ds) {
      assertDataset(ds);
      const { vmid } = parseVmDataset(ds)!;
      const info = await dataset(ds);
      const verdict = datasetDestroyAllowed({ exists: info.exists, snapshots: info.exists ? info.snapshots : [], vmConfigExists: await vmConfigExists(vmid) });
      if (!verdict.ok) throw new Error(`refusing to destroy ${ds} on ${label}: ${verdict.reason}`);
      if (!info.exists) return;
      try {
        await run(["zfs", "destroy", "-r", ds]);
      } catch (e: any) {
        if (!/does not exist/.test(String(e?.message))) throw e;
      }
    },
    async sendStream(ds, snap, from, opts) {
      assertDataset(ds);
      assertSnap(snap);
      if (from) assertSnap(from);
      let zfsArgs: string[];
      if (opts?.resumeToken) {
        assertResumeToken(opts.resumeToken);
        zfsArgs = ["zfs", "send", "-t", opts.resumeToken];
      } else {
        zfsArgs = ["zfs", "send", "-L", "-e", ...(from ? ["-i", `${ds}@${from}`] : []), `${ds}@${snap}`];
      }
      const send = spawnCmd(zfsArgs);
      const zstd = spawn("nice", ["-n", "10", "zstd", "-3", "-q", "-T1"], { stdio: ["pipe", "pipe", "pipe"] });
      const out = new PassThrough();
      let sendErr = "";
      send.stderr?.on("data", (d) => (sendErr += d.toString().slice(0, 1000)));
      send.on("close", (code) => {
        if (code !== 0) out.destroy(new Error(`zfs send ${ds}@${snap} exited ${code}: ${sendErr.trim()}`));
      });
      send.stdout!.pipe(zstd.stdin);
      zstd.stdout.pipe(out);
      zstd.on("close", (code) => {
        if (code !== 0) out.destroy(new Error(`zstd exited ${code}`));
      });
      out.on("close", () => {
        try {
          send.kill("SIGKILL");
        } catch {
          /* gone */
        }
        try {
          zstd.kill("SIGKILL");
        } catch {
          /* gone */
        }
      });
      return out;
    },
    async recv(ds, body) {
      assertDataset(ds);
      const { vmid } = parseVmDataset(ds)!;
      if (await vmConfigExists(vmid)) throw new Error(`refusing zfs receive into ${ds}: vm ${vmid} already has a config on ${label}`);
      const zstd = spawn("zstd", ["-d", "-q", "-T0"], { stdio: ["pipe", "pipe", "pipe"] });
      // -s: keep a resume token on interruption; -F: an incremental lands on the
      // full pass's snapshot; -u: never mount anything.
      const recv = spawnCmd(["zfs", "receive", "-s", "-F", "-u", ds]);
      let recvErr = "";
      recv.stderr?.on("data", (d) => (recvErr += d.toString().slice(0, 1000)));
      const done = new Promise<void>((resolve, reject) => {
        recv.on("error", reject);
        recv.on("close", (code) => (code === 0 ? resolve() : reject(new Error(`zfs receive exited ${code}: ${recvErr.trim()}`))));
      });
      zstd.stdout.pipe(recv.stdin!);
      try {
        await pipeline(body, zstd.stdin);
        await done;
      } catch (e) {
        try {
          zstd.kill("SIGKILL");
        } catch {
          /* gone */
        }
        try {
          recv.kill("SIGKILL");
        } catch {
          /* gone */
        }
        throw e;
      }
    },
  };
}

/** The primary itself. */
export function localZfsHost(label = "primary"): ZfsHost {
  return commandZfsHost(
    label,
    (argv) => execArgv(argv[0], argv.slice(1)),
    (argv) => spawn(argv[0], argv.slice(1), { stdio: ["pipe", "pipe", "pipe"] }),
  );
}

/** Transition fallback: root SSH to a node (argv only, BatchMode, no shell string). */
export function sshZfsHost(node: { name: string; publicIp: string }): ZfsHost {
  const base = ["-o", "BatchMode=yes", "-o", "ConnectTimeout=15", "-o", "StrictHostKeyChecking=accept-new", `root@${node.publicIp}`, "--"];
  return commandZfsHost(
    `${node.name} (ssh)`,
    (argv) => execArgv("ssh", [...base, ...argv]),
    (argv) => spawn("ssh", [...base, ...argv], { stdio: ["pipe", "pipe", "pipe"] }),
  );
}

/** A non-primary node via its node-agent (v2). The agent re-checks every guard itself. */
export function agentZfsHost(node: AgentNode): ZfsHost {
  const dataset = async (d: string): Promise<ZfsDatasetInfo> => {
    assertDataset(d);
    const r = await agentZfsDataset(node, d);
    if (!r.exists) return { exists: false };
    return { ...r, resumeToken: r.resumeToken ? parseResumeToken(r.resumeToken) : null };
  };
  return {
    label: `${node.name} (agent)`,
    dataset,
    vmConfigExists: (vmid) => agentZfsVmConfigExists(node, vmid),
    snapshot: (d, s) => {
      assertDataset(d);
      assertSnap(s);
      return agentZfsSnapshot(node, d, s);
    },
    deleteSnapshot: (d, s) => {
      assertDataset(d);
      assertSnap(s);
      return agentZfsDeleteSnapshot(node, d, s);
    },
    destroyDataset: async (d) => {
      assertDataset(d);
      // Belt and braces: decide here too, so a downgraded agent cannot be talked into it.
      const info = await dataset(d);
      const { vmid } = parseVmDataset(d)!;
      const verdict = datasetDestroyAllowed({ exists: info.exists, snapshots: info.exists ? info.snapshots : [], vmConfigExists: await agentZfsVmConfigExists(node, vmid) });
      if (!verdict.ok) throw new Error(`refusing to destroy ${d} on ${node.name}: ${verdict.reason}`);
      if (!info.exists) return;
      return agentZfsDestroyDataset(node, d);
    },
    sendStream: (d, s, from, opts) => {
      assertDataset(d);
      assertSnap(s);
      if (from) assertSnap(from);
      if (opts?.resumeToken) assertResumeToken(opts.resumeToken);
      return agentZfsSendStream(node, d, s, from, opts?.resumeToken ?? null);
    },
    recv: (d, body) => {
      assertDataset(d);
      return agentZfsRecv(node, d, body);
    },
  };
}

export type ZfsNodeRow = AgentNode & { isPrimary: boolean };

/** Pick the implementation for a node. `VM_MOVE_TRANSPORT=ssh` forces the
 *  transition fallback for non-primary nodes; the default is the agent. */
export function zfsHostFor(node: ZfsNodeRow): ZfsHost {
  if (node.isPrimary) return localZfsHost(node.name);
  if ((process.env.VM_MOVE_TRANSPORT ?? "agent") === "ssh") return sshZfsHost(node);
  return agentZfsHost(node);
}

/** Count bytes flowing through a stream (for progress reporting). */
export function meter(onBytes: (total: number) => void): PassThrough {
  let total = 0;
  const pt = new PassThrough();
  pt.on("data", (chunk: Buffer) => {
    total += chunk.length;
    onBytes(total);
  });
  return pt;
}

