        assertResumeToken(opts.resumeToken);
        zfsArgs = ["zfs", "send", "-t", opts.resumeToken];
      } else {
        zfsArgs = ["zfs", "send", "-L", "-e", ...(from ? ["-i", `${ds}@${from}`] : []), `${ds}@${snap}`];
      }
      const send = spawnCmd(zfsArgs);
      const zstd = spawn("nice", ["-n", "10", "zstd", "-3", "-q", "-T1"], { stdio: ["pipe", "pipe", "pipe"] });
      const out = new PassThrough();
      let sendErr = "";
      send.stderr?.on("data", (d) => (sendErr += d.toString().slice(0, 1000)));
      send.on("close", (code) => {
        if (code !== 0) out.destroy(new Error(`zfs send ${ds}@${snap} exited ${code}: ${sendErr.trim()}`));
      });
      send.stdout!.pipe(zstd.stdin);
      zstd.stdout.pipe(out);
      zstd.on("close", (code) => {
        if (code !== 0) out.destroy(new Error(`zstd exited ${code}`));
      });
      out.on("close", () => {
        try {
          send.kill("SIGKILL");
        } catch {
          /* gone */
        }
        try {
          zstd.kill("SIGKILL");
        } catch {
          /* gone */
        }
      });
      return out;
    },
    async recv(ds, body) {
      assertDataset(ds);
      const { vmid } = parseVmDataset(ds)!;
      if (await vmConfigExists(vmid)) throw new Error(`refusing zfs receive into ${ds}: vm ${vmid} already has a config on ${label}`);
      const zstd = spawn("zstd", ["-d", "-q", "-T0"], { stdio: ["pipe", "pipe", "pipe"] });
      // -s: keep a resume token on interruption; -F: an incremental lands on the
      // full pass's snapshot; -u: never mount anything.
      const recv = spawnCmd(["zfs", "receive", "-s", "-F", "-u", ds]);
      let recvErr = "";
      recv.stderr?.on("data", (d) => (recvErr += d.toString().slice(0, 1000)));
      const done = new Promise<void>((resolve, reject) => {
        recv.on("error", reject);
        recv.on("close", (code) => (code === 0 ? resolve() : reject(new Error(`zfs receive exited ${code}: ${recvErr.trim()}`))));
      });
      zstd.stdout.pipe(recv.stdin!);
      try {
        await pipeline(body, zstd.stdin);
        await done;
      } catch (e) {
        try {
          zstd.kill("SIGKILL");
        } catch {
          /* gone */
        }
        try {
          recv.kill("SIGKILL");
        } catch {
          /* gone */
        }
        throw e;
      }
    },
  };
}

/** The primary itself. */
export function localZfsHost(label = "primary"): ZfsHost {
  return commandZfsHost(
    label,
    (argv) => execArgv(argv[0], argv.slice(1)),
    (argv) => spawn(argv[0], argv.slice(1), { stdio: ["pipe", "pipe", "pipe"] }),
  );
}

/** Transition fallback: root SSH to a node (argv only, BatchMode, no shell string). */
export function sshZfsHost(node: { name: string; publicIp: string }): ZfsHost {
  const base = ["-o", "BatchMode=yes", "-o", "ConnectTimeout=15", "-o", "StrictHostKeyChecking=accept-new", `root@${node.publicIp}`, "--"];
  return commandZfsHost(
    `${node.name} (ssh)`,
    (argv) => execArgv("ssh", [...base, ...argv]),
    (argv) => spawn("ssh", [...base, ...argv], { stdio: ["pipe", "pipe", "pipe"] }),
  );
}

/** A non-primary node via its node-agent (v2). The agent re-checks every guard itself. */
export function agentZfsHost(node: AgentNode): ZfsHost {
  const dataset = async (d: string): Promise<ZfsDatasetInfo> => {
    assertDataset(d);
    const r = await agentZfsDataset(node, d);
    if (!r.exists) return { exists: false };
    return { ...r, resumeToken: r.resumeToken ? parseResumeToken(r.resumeToken) : null };
  };
  return {
    label: `${node.name} (agent)`,
    dataset,
    vmConfigExists: (vmid) => agentZfsVmConfigExists(node, vmid),
    snapshot: (d, s) => {
      assertDataset(d);
      assertSnap(s);
      return agentZfsSnapshot(node, d, s);
    },
    deleteSnapshot: (d, s) => {
      assertDataset(d);
      assertSnap(s);
      return agentZfsDeleteSnapshot(node, d, s);
    },
    destroyDataset: async (d) => {
      assertDataset(d);
      // Belt and braces: decide here too, so a downgraded agent cannot be talked into it.
      const info = await dataset(d);
      const { vmid } = parseVmDataset(d)!;
      const verdict = datasetDestroyAllowed({ exists: info.exists, snapshots: info.exists ? info.snapshots : [], vmConfigExists: await agentZfsVmConfigExists(node, vmid) });
      if (!verdict.ok) throw new Error(`refusing to destroy ${d} on ${node.name}: ${verdict.reason}`);
      if (!info.exists) return;
      return agentZfsDestroyDataset(node, d);
    },
    sendStream: (d, s, from, opts) => {
      assertDataset(d);
      assertSnap(s);
      if (from) assertSnap(from);
      if (opts?.resumeToken) assertResumeToken(opts.resumeToken);
      return agentZfsSendStream(node, d, s, from, opts?.resumeToken ?? null);
    },
    recv: (d, body) => {
      assertDataset(d);
      return agentZfsRecv(node, d, body);
    },
  };
}

export type ZfsNodeRow = AgentNode & { isPrimary: boolean };

/** Pick the implementation for a node. `VM_MOVE_TRANSPORT=ssh` forces the
 *  transition fallback for non-primary nodes; the default is the agent. */
export function zfsHostFor(node: ZfsNodeRow): ZfsHost {
  if (node.isPrimary) return localZfsHost(node.name);
  if ((process.env.VM_MOVE_TRANSPORT ?? "agent") === "ssh") return sshZfsHost(node);
  return agentZfsHost(node);
}

/** Count bytes flowing through a stream (for progress reporting). */
export function meter(onBytes: (total: number) => void): PassThrough {
  let total = 0;
  const pt = new PassThrough();
  pt.on("data", (chunk: Buffer) => {
    total += chunk.length;
    onBytes(total);
  });
  return pt;
}

