/**
 * Fleet-wide, monotonic vmid allocation — the ONE place a brand-new vmid is
 * claimed, shared by PROVISION (worker/index.ts allocateFreshVmid) and VM_MOVE
 * (lib/vm-move/engine.ts PREFLIGHT).
 *
 * WHY SHARED (audit 2026-10-01): the move engine computed "highest id seen on
 * any node + 1" at preflight but never claimed it, and the provisioner's
 * `vmid_high_water` Setting never learned about moves. Between a move's
 * preflight and its CREATE_TARGET (hours, for a big disk) a PROVISION could be
 * handed the very same number — on the target node that means CREATE_TARGET
 * would have "reused" another customer's brand-new VM and rollback would have
 * destroyed it. One atomic insert-or-bump statement closes that: whoever runs
 * it gets a number nobody has ever been handed, in any order, from any process.
 *
 * `floor` is the caller's own idea of "above everything I can see" (fleet
 * listing, DB rows, archives); the Setting may already be higher. The template
 * band 9000–9999 is skipped (lib/proxmox.ts isReservedVmid/freshVmidFloor).
 */
import { db } from "./db";
import { freshVmidFloor, isReservedVmid } from "./proxmox";

export const VMID_HIGH_WATER_KEY = "vmid_high_water";

export async function claimVmidHighWater(floor: number): Promise<number> {
  const f = Number.isInteger(floor) && floor >= 100 ? floor : 100;
  const rows = await db.$queryRaw<{ value: string }[]>`
    INSERT INTO "Setting" ("key", "value") VALUES (${VMID_HIGH_WATER_KEY}, ${String(f)})
    ON CONFLICT ("key") DO UPDATE
      SET "value" = GREATEST(("Setting"."value")::bigint + 1, ${f}::bigint)::text
    RETURNING "value"`;
  const claimed = Number(rows?.[0]?.value);
  if (!Number.isInteger(claimed) || claimed <= 0) throw new Error(`${VMID_HIGH_WATER_KEY} returned a non-integer (${rows?.[0]?.value})`);
  // Never step into the template range; jump it once and re-claim from there.
  if (isReservedVmid(claimed)) return claimVmidHighWater(freshVmidFloor(claimed, [claimed]));
  return claimed;
}

/** Raise the mark after a vmid was used by a path that did not claim it here. */
export async function bumpVmidHighWater(vmid: number): Promise<void> {
  if (!Number.isInteger(vmid) || vmid < 100) return;
  await db.$executeRaw`
    UPDATE "Setting" SET "value" = GREATEST(("value")::bigint, ${vmid}::bigint)::text
    WHERE "key" = ${VMID_HIGH_WATER_KEY}`;
}

