/**
 * VM_MOVE / VM_MOVE_CLEANUP — worker adapters.
 *
 * The move itself is lib/vm-move/engine.ts (`runMove`), pure orchestration
 * over a `MoveWorld`. This file builds the REAL world out of the database,
 * both nodes' Proxmox APIs, the ZFS hosts (local / node-agent / ssh), OVH, NAT
 * and the mailer, and exposes the three job entry points plus two hooks the
 * rest of the worker calls:
 *
 *   vmMoveJob                    VM_MOVE handler (resume-safe)
 *   vmMoveCleanupJob             VM_MOVE_CLEANUP handler — the ONLY place the
 *                                engine ever destroys a SOURCE VM, after
 *                                re-verifying DB, both hypervisors and the
 *                                VM's identity (name + nxeon-moved tag)
 *   teardownMoveLeftoversForServer  called by the DELETE handler before the
 *                                Server row (and, by cascade, every VmMove row)
 *                                disappears, so a kept source / half-built
 *                                target can never become an untracked orphan
 *   vmMoveWatchdogSweep          a RUNNING move with no live job (worker
 *                                restarts exhausted, job FAILED outside the
 *                                engine) is re-queued or escalated — never
 *                                left dark forever
 *
 * Design notes and the failure-mode analysis: docs/VM-MOVE.md,
 * docs/VM-MOVE-DEEP-ANALYSIS.md.
 */
import { writeFile, unlink } from "node:fs/promises";
import type { Job, Prisma } from "@prisma/client";
import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { pveFor, waitForGuestAgent, destroyVmIdempotent, isVmAbsentError, type PveClient, type VmDestroyHost } from "../lib/proxmox";
import { allocateIp } from "../lib/ipam";
import { serverRootPassword } from "../lib/sftp";
import { sendMail } from "../lib/mailer";
import { agentWriteSnippet, agentDeleteSnippet, agentHealth } from "../lib/node-agent";
import { claimVmidHighWater } from "../lib/vmid-high-water";
import { syncPortForwardsBestEffort } from "./network";
import { checkSshReachable, checkGamePortOpen } from "./provision-health";
import { notifyAdmins } from "./monitor";
import { buildMovePlan, loadMoveNode, loadMoveServer, readGuestFileSoft, snippetStorageFor, type MoveNode } from "../lib/vm-move/preflight";
import { zfsHostFor, type ZfsHost } from "../lib/vm-move/zfs-host";
import { isKeptSourceVm, isOurTargetVm, MOVED_SOURCE_TAG, moveTargetTag, parseVmDataset, splitTags } from "../lib/vm-move/plan";
import { ovhEnsureVirtualMac, ovhIpRoutedTo, ovhMoveIp, ovhReleaseVirtualMac } from "../lib/vm-move/ovh-ip-move";
import { runMove, type Hypervisor, type HvState, type MoveNodeFacts, type MoveRowFacts, type MoveServerFacts, type MoveWorld, type SourceZfs, type TargetZfs } from "../lib/vm-move/engine";
import type { MoveCheckpoints, MovePhase, MovePlan, MoveLogLine, VmMoveCleanupJobPayload, VmMoveJobPayload } from "../lib/vm-move/types";

const SNIPPET_DIR = process.env.NXEON_SNIPPET_DIR ?? "/tank/backup/snippets";
const KEEP_SOURCE_DAYS = Math.max(1, Number(process.env.VM_MOVE_KEEP_SOURCE_DAYS ?? 7));
const STALL_TIMEOUT_MS = Math.max(60_000, Number(process.env.VM_MOVE_STALL_TIMEOUT_MS ?? 10 * 60_000));
/** Must match worker/index.ts's MAX_ATTEMPTS — attempts is incremented at claim time. */
const MOVE_MAX_ATTEMPTS = 3;

type Progress = (jobId: string, progress: number, step: string) => Promise<void>;

// ---------------------------------------------------------------------------
// Hypervisor adapter (Proxmox API)
// ---------------------------------------------------------------------------

function hypervisorFor(conn: PveClient, nodeName: string): Hypervisor {
  const state = async (vmid: number): Promise<HvState> => {
    try {
      const s = await conn.vmStatus(vmid);
      return s?.status === "running" ? "running" : "stopped";
    } catch (e) {
      if (isVmAbsentError(e, vmid)) return "absent";
      throw e;
    }
  };
  return {
    nodeName,
    vmState: state,
    async vmConfig(vmid) {
      try {
        return await conn.get(`/nodes/${conn.node}/qemu/${vmid}/config`);
      } catch (e) {
        if (isVmAbsentError(e, vmid)) return null;
        throw e;
      }
    },
    async setConfig(vmid, patch) {
      await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, patch);
    },
    async listSnapshots(vmid) {
      const snaps: any[] = await conn.get(`/nodes/${conn.node}/qemu/${vmid}/snapshot`).catch(() => []);
      return (snaps ?? []).map((s) => String(s?.name)).filter((n) => n && n !== "current");
    },
    async createSnapshot(vmid, name, description) {
      const upid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/snapshot`, { snapname: name, vmstate: 0, description });
      await conn.waitForTask(upid, 300_000);
    },
    async deleteSnapshot(vmid, name) {
      const upid = await conn.del(`/nodes/${conn.node}/qemu/${vmid}/snapshot/${encodeURIComponent(name)}`);
      await conn.waitForTask(upid, 120_000);
    },
    async shutdown(vmid, timeoutS) {
      const upid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/shutdown`, { timeout: timeoutS });
      await conn.waitForTask(upid, (timeoutS + 30) * 1000);
      if ((await state(vmid)) === "running") throw new Error(`vm ${vmid} still running after a ${timeoutS}s graceful shutdown`);
    },
    async stop(vmid) {
      const upid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/stop`, {});
      await conn.waitForTask(upid, 120_000);
    },
    async start(vmid) {
      const upid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
      await conn.waitForTask(upid, 180_000);
    },
    async createVm(cfg) {
      const upid = await conn.post(`/nodes/${conn.node}/qemu`, cfg);
      await conn.waitForTask(upid, 120_000);
    },
    async destroyVm(vmid) {
      const upid = await conn.del(`/nodes/${conn.node}/qemu/${vmid}`, { "destroy-unreferenced-disks": 1, purge: 1 });
      await conn.waitForTask(upid, 600_000);
    },
    waitGuestAgent: (vmid, timeoutMs) => waitForGuestAgent(conn, conn.node, vmid, timeoutMs),
    readGuestFile: (vmid, path) => readGuestFileSoft(conn, vmid, path),
  };
}

function destroyHost(conn: PveClient): VmDestroyHost {
  return {
    probe: async (id) => {
      try {
        await conn.vmStatus(id);
        return "present";
      } catch (e) {
        return isVmAbsentError(e, id) ? "absent" : "unknown";
      }
    },
    stop: async (id) => {
      const upid = await conn.post(`/nodes/${conn.node}/qemu/${id}/status/stop`, {});
      await conn.waitForTask(upid);
    },
    destroy: async (id) => {
      const upid = await conn.del(`/nodes/${conn.node}/qemu/${id}`, { "destroy-unreferenced-disks": 1, purge: 1 });
      await conn.waitForTask(upid, 600_000);
    },
  };
}

async function writeSnippet(node: MoveNode, storage: string, filename: string, content: string): Promise<void> {
  if (node.isPrimary) await writeFile(`${SNIPPET_DIR}/${filename}`, content, "utf8");
  else await agentWriteSnippet(node, storage, filename, content);
}
async function deleteSnippet(node: MoveNode, storage: string, filename: string): Promise<void> {
  if (node.isPrimary) await unlink(`${SNIPPET_DIR}/${filename}`).catch(() => {});
  else await agentDeleteSnippet(node, storage, filename).catch(() => {});
}

function nodeFacts(n: MoveNode): MoveNodeFacts {
  return { id: n.id, name: n.name, publicIp: n.publicIp, isPrimary: n.isPrimary };
}

// ---------------------------------------------------------------------------
// The real world
// ---------------------------------------------------------------------------

async function appendLogRow(moveId: string, phase: string, msg: string): Promise<void> {
  console.log(`[vm-move] ${moveId} ${phase}: ${msg}`);
  const row = await db.vmMove.findUnique({ where: { id: moveId }, select: { log: true } });
  const log = ((row?.log as MoveLogLine[] | null) ?? []).slice(-400);
  log.push({ at: new Date().toISOString(), phase, msg });
  await db.vmMove.update({ where: { id: moveId }, data: { log: log as unknown as Prisma.InputJsonValue } }).catch(() => {});
}

async function buildWorld(job: Job, moveId: string, progress: Progress): Promise<MoveWorld> {
  const row0 = await db.vmMove.findUnique({ where: { id: moveId } });
  if (!row0) throw new Error(`VmMove ${moveId} not found`);
  const [source, target] = await Promise.all([loadMoveNode(row0.sourceNodeId), loadMoveNode(row0.targetNodeId)]);
  if (!source || !target) throw new Error("source or target node row vanished");
  const srcConn = pveFor(source);
  const tgtConn = pveFor(target);
  const srcZfs: ZfsHost = zfsHostFor(source);
  const tgtZfs: ZfsHost = zfsHostFor(target);

  const sourceZfs: SourceZfs = { dataset: (d) => srcZfs.dataset(d), snapshot: (d, s) => srcZfs.snapshot(d, s), deleteSnapshot: (d, s) => srcZfs.deleteSnapshot(d, s), sendStream: (d, s, f, o) => srcZfs.sendStream(d, s, f, o) };
  const targetZfs: TargetZfs = { dataset: (d) => tgtZfs.dataset(d), deleteSnapshot: (d, s) => tgtZfs.deleteSnapshot(d, s), destroyDataset: (d) => tgtZfs.destroyDataset(d), recv: (d, b) => tgtZfs.recv(d, b as any), vmConfigExists: (v) => tgtZfs.vmConfigExists(v) };

  return {
    now: () => new Date(),
    keepSourceDays: KEEP_SOURCE_DAYS,
    stallTimeoutMs: STALL_TIMEOUT_MS,
    async loadMove(): Promise<MoveRowFacts> {
      const r = await db.vmMove.findUnique({ where: { id: moveId } });
      if (!r) throw new Error(`VmMove ${moveId} vanished`);
      return { id: r.id, serverId: r.serverId, status: r.status, phase: r.phase, dryRun: r.dryRun, plan: (r.plan as MovePlan | null) ?? null, checkpoints: ((r.checkpoints as MoveCheckpoints | null) ?? {}) as MoveCheckpoints, requestedById: r.requestedById, startedAt: r.startedAt };
    },
    async updateMove(data) {
      const { plan, ...rest } = data;
      await db.vmMove.update({ where: { id: moveId }, data: { ...(rest as any), ...(plan ? { plan: plan as unknown as Prisma.InputJsonValue } : {}) } });
    },
    async saveCheckpoints(patch, phase?: MovePhase) {
      const r = await db.vmMove.findUnique({ where: { id: moveId }, select: { checkpoints: true } });
      const next = { ...(((r?.checkpoints as MoveCheckpoints | null) ?? {}) as MoveCheckpoints), ...patch };
      await db.vmMove.update({ where: { id: moveId }, data: { checkpoints: next as unknown as Prisma.InputJsonValue, ...(phase ? { phase } : {}) } });
      return next;
    },
    appendLog: (phase, msg) => appendLogRow(moveId, phase, msg),
    progress: (pct, step) => progress(job.id, pct, step),
    async loadServer(): Promise<MoveServerFacts | null> {
      const s = await loadMoveServer(row0.serverId);
      if (!s) return null;
      const otherJobsInFlight = await db.job.count({ where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] }, type: { notIn: ["VM_MOVE"] } } });
      return { id: s.id, hostname: s.hostname, status: s.status, vmid: s.vmid, nodeId: s.nodeId, ipAddress: s.ipAddress, sshPort: s.sshPort, subdomain: s.subdomain, userId: s.userId, userEmail: s.user?.email ?? null, dedicatedIpAssigned: !!s.dedicatedIp, otherJobsInFlight };
    },
    async setServerStatus(status) {
      await db.server.update({ where: { id: row0.serverId }, data: { status } });
    },
    async commitCutover(a) {
      await db.$transaction(async (tx) => {
        await tx.server.update({ where: { id: row0.serverId }, data: { nodeId: a.targetNodeId, vmid: a.targetVmid, status: a.status, ...(a.ipAddress ? { ipAddress: a.ipAddress } : {}) } });
        if (a.dedicated) await tx.dedicatedIp.updateMany({ where: { address: a.dedicated.address }, data: { nodeId: a.targetNodeId, virtualMac: a.dedicated.virtualMac ?? undefined } });
        await tx.vmMove.update({ where: { id: moveId }, data: { addressChanged: a.addressChanged, keepSourceUntil: a.keepSourceUntil } });
      });
    },
    claimTargetVmid: (floor) => claimVmidHighWater(floor),
    preflight: () => buildMovePlan({ serverId: row0.serverId, targetNodeId: row0.targetNodeId, allowDropSnapshots: !!(row0.checkpoints as any)?.allowDropSnapshots }),
    allocateTargetPrivateIp: (nodeId) => allocateIp(nodeId),
    async rootPassword() {
      const s = await db.server.findUnique({ where: { id: row0.serverId }, select: { rootPassword: true, rootPasswordEnc: true } });
      return s ? serverRootPassword(s) : null;
    },
    source: { node: nodeFacts(source), hv: hypervisorFor(srcConn, source.name), zfs: sourceZfs },
    target: { node: nodeFacts(target), hv: hypervisorFor(tgtConn, target.name), zfs: targetZfs },
    snippets: {
      write: (n, storage, filename, content) => writeSnippet(n.id === source.id ? source : target, storage, filename, content),
      delete: (n, storage, filename) => deleteSnippet(n.id === source.id ? source : target, storage, filename),
    },
    ovh: { moveIp: ovhMoveIp, ensureVirtualMac: ovhEnsureVirtualMac, releaseVirtualMac: ovhReleaseVirtualMac, routedTo: ovhIpRoutedTo },
    net: {
      syncPortForwards: (ctx) => (SANDBOX ? Promise.resolve(null) : syncPortForwardsBestEffort(ctx)),
      checkSsh: async (host, port, timeoutMs) => {
        const r = await checkSshReachable(host, port, { timeoutMs });
        return { ok: r.ok, error: r.error };
      },
      checkGamePort: async (host, port, protocol, timeoutMs) => {
        const r = await checkGamePortOpen(host, port, protocol, { timeoutMs });
        return { ok: r.ok, error: r.error };
      },
      targetReachable: async () => {
        if (target.isPrimary) return true;
        try {
          const h = await agentHealth(target);
          return !!h?.ok;
        } catch {
          return (process.env.VM_MOVE_TRANSPORT ?? "agent") === "ssh";
        }
      },
    },
    dns: {
      queueGameDnsSync: async (serverId) => {
        await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId } });
      },
    },
    notify: {
      customer: async (userId, title, body, href) => {
        await db.notification.create({ data: { userId, title, body, href } }).catch(() => {});
      },
      email: async (to, subject, text, userId) => {
        await sendMail({ to, subject, html: `<p>${text.replace(/\n\n/g, "</p><p>")}</p>`, text, userId }).catch((e) => console.error("[vm-move] customer email failed", e));
      },
      admins: (title, body, href) => notifyAdmins(title, body, href),
    },
    audit: async (action, targetName, detail) => {
      await db.auditLog.create({ data: { userId: row0.requestedById ?? null, action, category: "server", target: targetName, detail } });
    },
    isFinalAttempt: () => job.attempts >= MOVE_MAX_ATTEMPTS,
  };
}

// ---------------------------------------------------------------------------
// Job entry points
// ---------------------------------------------------------------------------

/** VM_MOVE handler. `progress` is worker/index.ts's reportJobProgress. */
export async function vmMoveJob(job: Job, progress: Progress): Promise<void> {
  const payload = (job.payload ?? {}) as Partial<VmMoveJobPayload>;
  if (!payload.vmMoveId) throw new Error("VM_MOVE job has no vmMoveId");
  const move = await db.vmMove.findUnique({ where: { id: payload.vmMoveId } });
  if (!move) throw new Error(`VmMove ${payload.vmMoveId} not found`);
  if (move.status === "DONE" || move.status === "CLEANED") return;
  if (move.status === "ROLLED_BACK" || move.status === "FAILED") throw new Error(move.error ?? `move is ${move.status}`);
  if (SANDBOX) {
    await db.vmMove.update({ where: { id: move.id }, data: { status: "FAILED", error: "VM moves are not simulated in sandbox mode", finishedAt: new Date() } });
    throw new Error("VM moves are not simulated in sandbox mode");
  }
  const world = await buildWorld(job, move.id, progress);
  await runMove(world);
}

/**
 * Verify, on the hypervisor, that the VM at `vmid` really is the move's kept
 * source (name + nxeon-moved tag once FINALIZE recorded it, not a template).
 */
async function verifyKeptSource(conn: PveClient, vmid: number, plan: MovePlan | null, cp: MoveCheckpoints): Promise<{ ok: boolean; reason: string; state: "running" | "stopped" | "absent" }> {
  let cfg: Record<string, unknown> | null = null;
  try {
    cfg = await conn.get(`/nodes/${conn.node}/qemu/${vmid}/config`);
  } catch (e) {
    if (isVmAbsentError(e, vmid)) return { ok: true, reason: "already absent", state: "absent" };
    throw e;
  }
  const st = await conn.vmStatus(vmid).catch(() => null);
  const state = st?.status === "running" ? "running" : "stopped";
  const v = isKeptSourceVm(cfg, { expectedName: plan?.carriedConfig?.name ?? null, tagRecorded: !!cp.sourceOnbootDisabled });
  return { ...v, state };
}

/**
 * VM_MOVE_CLEANUP — destroy the stopped source VM of a DONE move. Refuses
 * unless the DB still says the target is live AND the target hypervisor
 * agrees (present, and running when the server is RUNNING) AND the VM at the
 * source vmid is provably the one this move left behind, and unless
 * `keepSourceUntil` has passed (or the payload forces it).
 */
export async function vmMoveCleanupJob(job: Job, progress: Progress): Promise<void> {
  const payload = (job.payload ?? {}) as Partial<VmMoveCleanupJobPayload>;
  if (!payload.vmMoveId) throw new Error("VM_MOVE_CLEANUP job has no vmMoveId");
  const move = await db.vmMove.findUnique({ where: { id: payload.vmMoveId } });
  if (!move) throw new Error(`VmMove ${payload.vmMoveId} not found`);
  if (move.status === "CLEANED") return;
  if (move.status !== "DONE") throw new Error(`cleanup refused: move is ${move.status}, not DONE`);
  if (move.keepSourceUntil && move.keepSourceUntil.getTime() > Date.now() && !payload.force) {
    throw new Error(`cleanup refused: source is kept until ${move.keepSourceUntil.toISOString()} (pass force to override)`);
  }
  const plan = (move.plan as MovePlan | null) ?? null;
  const cp = ((move.checkpoints as MoveCheckpoints | null) ?? {}) as MoveCheckpoints;
  const server = await db.server.findUnique({ where: { id: move.serverId }, select: { vmid: true, nodeId: true, hostname: true, status: true } });
  if (!server || server.vmid !== move.targetVmid || server.nodeId !== move.targetNodeId) {
    throw new Error(`cleanup refused: DB says server is vmid ${server?.vmid ?? "?"} on node ${server?.nodeId ?? "?"}, not the move's target ${move.targetVmid}/${move.targetNodeId}`);
  }
  const [source, target] = await Promise.all([loadMoveNode(move.sourceNodeId), loadMoveNode(move.targetNodeId)]);
  if (!source || !target) throw new Error("source or target node row vanished");
  const tgtConn = pveFor(target);
  const srcConn = pveFor(source);
  const tgtState = await (async () => {
    try {
      const s = await tgtConn.vmStatus(move.targetVmid);
      return s?.status === "running" ? "running" : "stopped";
    } catch (e) {
      if (isVmAbsentError(e, move.targetVmid)) return "absent";
      throw e;
    }
  })();
  if (tgtState === "absent") throw new Error(`cleanup refused: target vm ${move.targetVmid} is ABSENT on ${target.name}`);
  if (server.status === "RUNNING" && tgtState !== "running" && !payload.force) throw new Error(`cleanup refused: server is RUNNING in the DB but target vm ${move.targetVmid} is ${tgtState} on ${target.name}`);
  const tgtCfg = await tgtConn.get(`/nodes/${tgtConn.node}/qemu/${move.targetVmid}/config`).catch(() => null);
  if (plan?.carriedConfig?.name && tgtCfg?.name && String(tgtCfg.name) !== plan.carriedConfig.name) {
    throw new Error(`cleanup refused: target vm ${move.targetVmid} is named ${tgtCfg.name}, expected ${plan.carriedConfig.name}`);
  }
  const src = await verifyKeptSource(srcConn, move.sourceVmid, plan, cp);
  if (src.state === "running") throw new Error(`cleanup refused: source vm ${move.sourceVmid} on ${source.name} is RUNNING — it must be stopped (someone started it after the move?)`);
  if (!src.ok) throw new Error(`cleanup refused: vm ${move.sourceVmid} on ${source.name} is not provably the kept source (${src.reason})`);

  await progress(job.id, 20, `Destroying source vm ${move.sourceVmid} on ${source.name}…`);
  const outcome = await destroyVmIdempotent(destroyHost(srcConn), move.sourceVmid);
  await appendLogRow(move.id, "CLEANUP", `source vm ${move.sourceVmid}: ${outcome.detail}`);
  await deleteSnippet(source, snippetStorageFor(source), `nxeon-${move.sourceVmid}.yaml`);
  if (plan?.addressing.kind === "DEDICATED" && plan.addressing.sourceService) {
    await ovhReleaseVirtualMac(plan.addressing.sourceService, plan.addressing.address, plan.addressing.sourceVirtualMac).catch((e) =>
      appendLogRow(move.id, "CLEANUP", `WARNING: could not release the source Virtual MAC: ${e?.message ?? e}`),
    );
  }
  await db.vmMove.update({ where: { id: move.id }, data: { status: "CLEANED", sourceCleanedAt: new Date() } });
  await db.auditLog.create({
    data: { userId: move.requestedById ?? null, action: "server.vm_move_cleanup", category: "server", target: server.hostname, detail: `destroyed source vmid ${move.sourceVmid} on ${source.name} (move ${move.id})` },
  });
  await progress(job.id, 100, "Source cleaned up");
}

// ---------------------------------------------------------------------------
// Hooks for the rest of the worker
// ---------------------------------------------------------------------------

/**
 * Called by the DELETE handler BEFORE `db.server.delete` (VmMove rows cascade
 * away with the server). Tears down what a move left behind for this server,
 * with the same identity proofs as cleanup/rollback:
 *   - DONE (not CLEANED): the kept SOURCE (stopped, name/tag verified)
 *   - RUNNING/FAILED/ROLLED_BACK and not committed: the half-built TARGET
 *     (only if it carries nxmove-<moveId>) and its received dataset
 * Best-effort: a failure here is logged and reported, never blocks the
 * customer's deletion. Returns a human summary for the DELETE log.
 */
export async function teardownMoveLeftoversForServer(serverId: string): Promise<string[]> {
  const notes: string[] = [];
  if (SANDBOX) return notes;
  const moves = await db.vmMove.findMany({ where: { serverId, status: { in: ["DONE", "RUNNING", "FAILED", "ROLLED_BACK", "PLANNED"] } } });
  for (const m of moves) {
    const plan = (m.plan as MovePlan | null) ?? null;
    const cp = ((m.checkpoints as MoveCheckpoints | null) ?? {}) as MoveCheckpoints;
    try {
      if (m.status === "DONE" && cp.committedAt) {
        const source = await loadMoveNode(m.sourceNodeId);
        if (!source) {
          notes.push(`move ${m.id}: source node row gone; vmid ${m.sourceVmid} left as is`);
          continue;
        }
        const conn = pveFor(source);
        const v = await verifyKeptSource(conn, m.sourceVmid, plan, cp);
        if (v.state === "absent") {
          notes.push(`move ${m.id}: kept source ${m.sourceVmid} already absent`);
        } else if (v.state === "running" || !v.ok) {
          notes.push(`move ${m.id}: kept source ${m.sourceVmid} on ${source.name} NOT destroyed (${v.state === "running" ? "running" : v.reason})`);
          await notifyAdmins(`Server deleted but moved-source vm ${m.sourceVmid} left on ${source.name}`, `Move ${m.id}: ${v.state === "running" ? "the source is running" : v.reason}. Inspect and destroy by hand if it really is the leftover.`, "/admin/ops");
          continue;
        } else {
          const outcome = await destroyVmIdempotent(destroyHost(conn), m.sourceVmid);
          await deleteSnippet(source, snippetStorageFor(source), `nxeon-${m.sourceVmid}.yaml`);
          if (plan?.addressing.kind === "DEDICATED" && plan.addressing.sourceService) await ovhReleaseVirtualMac(plan.addressing.sourceService, plan.addressing.address, plan.addressing.sourceVirtualMac).catch(() => {});
          notes.push(`move ${m.id}: kept source ${m.sourceVmid} on ${source.name}: ${outcome.detail}`);
        }
        await db.vmMove.update({ where: { id: m.id }, data: { status: "CLEANED", sourceCleanedAt: new Date() } }).catch(() => {});
        await db.auditLog.create({ data: { action: "server.vm_move_cleanup", category: "server", target: serverId, detail: `on server delete: ${notes[notes.length - 1]}` } }).catch(() => {});
      } else if (!cp.committedAt && plan && (cp.targetVmCreated || cp.fullSentAt)) {
        const target = await loadMoveNode(m.targetNodeId);
        if (!target) continue;
        const conn = pveFor(target);
        if (cp.targetVmCreated) {
          let cfg: Record<string, unknown> | null = null;
          try {
            cfg = await conn.get(`/nodes/${conn.node}/qemu/${plan.targetVmid}/config`);
          } catch (e) {
            if (!isVmAbsentError(e, plan.targetVmid)) throw e;
          }
          if (cfg && isOurTargetVm(cfg, m.id, plan.carriedConfig.name)) {
            const outcome = await destroyVmIdempotent(destroyHost(conn), plan.targetVmid);
            notes.push(`move ${m.id}: half-built target ${plan.targetVmid} on ${target.name}: ${outcome.detail}`);
          } else if (cfg) {
            notes.push(`move ${m.id}: vm ${plan.targetVmid} on ${target.name} lacks ${moveTargetTag(m.id)} — NOT touched`);
          }
        } else {
          await zfsHostFor(target).destroyDataset(plan.targetDataset).catch((e) => notes.push(`move ${m.id}: dataset ${plan.targetDataset} not destroyed: ${e?.message ?? e}`));
          notes.push(`move ${m.id}: partial dataset ${plan.targetDataset} on ${target.name} removed`);
        }
        if (cp.targetSnippetWritten) await deleteSnippet(target, plan.targetSnippetStorage, `nxeon-${plan.targetVmid}.yaml`);
        await db.vmMove.update({ where: { id: m.id }, data: { status: m.status === "RUNNING" ? "FAILED" : m.status, error: `${m.error ?? ""} | server deleted mid-move; target side torn down`.slice(0, 1900) } }).catch(() => {});
      }
    } catch (e: any) {
      notes.push(`move ${m.id}: leftover teardown error: ${String(e?.message ?? e).slice(0, 200)}`);
      await notifyAdmins(`Server deleted; move ${m.id} leftovers need a look`, String(e?.message ?? e).slice(0, 600), "/admin/ops");
    }
  }
  for (const n of notes) console.log(`[vm-move] delete-hook: ${n}`);
  return notes;
}

/** Vmids that belong to a move in a state where destroying them would be a
 *  disaster: every RUNNING/PLANNED move's source+target, and every DONE
 *  move's kept source. lib/admin-ops/drift.ts + opOrphanVmDestroy consult it. */
export async function moveProtectedVmids(): Promise<Map<number, { moveId: string; role: "source" | "target"; status: string }>> {
  const out = new Map<number, { moveId: string; role: "source" | "target"; status: string }>();
  const moves = await db.vmMove.findMany({ where: { status: { in: ["RUNNING", "PLANNED", "DONE", "FAILED"] } }, select: { id: true, status: true, sourceVmid: true, targetVmid: true, dryRun: true } });
  for (const m of moves) {
    if (m.dryRun) continue;
    if (m.status !== "DONE" || true) out.set(m.sourceVmid, { moveId: m.id, role: "source", status: m.status });
    if (m.targetVmid > 0 && m.status !== "DONE") out.set(m.targetVmid, { moveId: m.id, role: "target", status: m.status });
  }
  return out;
}

/**
 * Sweep: a RUNNING move whose job is gone (FAILED by exhausted worker
 * restarts, or deleted) would otherwise sit dark forever — the source stopped,
 * the target half-built, nobody retrying. Re-queue a VM_MOVE job (the engine
 * resumes from its checkpoints, or finishes an interrupted rollback) up to a
 * bounded number of times, then escalate.
 */
export async function vmMoveWatchdogSweep(): Promise<void> {
  if (SANDBOX) return;
  const stale = new Date(Date.now() - 10 * 60_000);
  const running = await db.vmMove.findMany({ where: { status: "RUNNING", updatedAt: { lt: stale } }, select: { id: true, serverId: true, phase: true } });
  for (const m of running) {
    const live = await db.job.count({ where: { type: "VM_MOVE", status: { in: ["QUEUED", "RUNNING"] }, payload: { path: ["vmMoveId"], equals: m.id } } });
    if (live > 0) continue;
    const total = await db.job.count({ where: { type: "VM_MOVE", payload: { path: ["vmMoveId"], equals: m.id } } });
    if (total >= 8) {
      await notifyAdmins(`VM move ${m.id} is stuck in ${m.phase}`, `No live job and ${total} jobs already spent. The engine will not retry on its own any more — inspect /admin/ops and roll back or finish by hand.`, "/admin/ops");
      continue;
    }
    await db.job.create({ data: { type: "VM_MOVE", serverId: m.serverId, payload: { vmMoveId: m.id, _watchdog: true } } });
    await appendLogRow(m.id, "WATCHDOG", `no live job found for a RUNNING move in ${m.phase} — re-queued (job ${total + 1})`);
    await notifyAdmins(`VM move ${m.id} re-queued by the watchdog`, `The move was RUNNING in ${m.phase} with no live job (worker restarts exhausted?). A resume job was queued.`, "/admin/ops");
  }
}

/** Tags on a Proxmox VM that mark it as part of a move (never an "orphan"). */
export function vmHasMoveTag(tags: unknown): boolean {
  return splitTags(tags).some((t) => t === MOVED_SOURCE_TAG || /^nxmove-[a-z0-9]{10,40}$/.test(t));
}

export { parseVmDataset };

