/**
 * In-memory fleet for lib/vm-move/engine.ts: two Proxmox nodes with VMs and
 * ZFS datasets, an OVH routing table, the DB rows a move touches, NAT/DNS/
 * notification recorders — and a FAULT INJECTOR that can make any step
 * throw, hang (→ the engine's own timeouts) or "crash the worker" (abort the
 * run so the next run has to resume from the checkpoints).
 *
 * Every mutation records an event in `events` and re-checks the live
 * invariants (`assertLiveInvariants`): never both VMs running, the source
 * dataset never receives/destroys, the source VM never destroyed.
 */
import { PassThrough, Readable } from "node:stream";
import type { Hypervisor, HvState, MoveNodeFacts, MoveRowFacts, MoveServerFacts, MoveWorld, SourceZfs, TargetZfs } from "../lib/vm-move/engine.ts";
import type { MoveCheckpoints, MovePhase, MovePlan } from "../lib/vm-move/types.ts";
import type { ZfsDatasetInfo } from "../lib/vm-move/zfs-host.ts";
import { datasetDestroyAllowed, parseVmDataset } from "../lib/vm-move/plan.ts";

export class WorkerCrash extends Error {
  constructor(public readonly step: string) {
    super(`worker crashed at ${step}`);
    this.name = "WorkerCrash";
  }
}

export type FaultMode = "throw" | "crash";
export type Fault = { step: string; mode: FaultMode; times?: number };

type FakeVm = { vmid: number; state: "running" | "stopped"; cfg: Record<string, unknown>; snapshots: string[] };
type FakeDataset = { bytes: number; snapshots: string[]; partial: boolean; resumeToken: string | null; data: string[] };

export class FakeNode {
  vms = new Map<number, FakeVm>();
  datasets = new Map<string, FakeDataset>();
  agentUp = true;
  constructor(public readonly facts: MoveNodeFacts, public readonly pool: string) {}
  cfgExists(vmid: number) {
    return this.vms.has(vmid);
  }
}

export class FakeFleet {
  events: string[] = [];
  faults: Fault[] = [];
  stepLog: string[] = [];
  readonly src: FakeNode;
  readonly tgt: FakeNode;
  ovhRoute = new Map<string, string>(); // ip -> service
  ovhMacs = new Map<string, Map<string, string>>(); // service -> ip -> mac
  ovhMoveDelayFail = false;
  // DB
  move: MoveRowFacts;
  server: MoveServerFacts & { dedicatedIpAddress: string | null; dedicatedNodeId: string | null; dedicatedMac: string | null };
  dbReservedIps = new Set<string>();
  highWater = 600;
  natSyncs: string[] = [];
  natFail = false;
  dnsQueued: string[] = [];
  notices: { kind: string; title: string }[] = [];
  audits: string[] = [];
  jobAttempts = 1;
  clock = Date.parse("2026-10-01T10:00:00Z");
  sshAnswers = true;
  gameAnswers = true;
  guestAgentAnswers = true;
  shutdownHangs = false;
  plan: MovePlan;

  constructor(opts: { dedicated: boolean; sourceRunning?: boolean; moveId?: string }) {
    const moveId = opts.moveId ?? "cmvmove0000000000000000001";
    this.src = new FakeNode({ id: "n1", name: "primary", publicIp: "51.79.162.10", isPrimary: true }, "data/vms");
    this.tgt = new FakeNode({ id: "n4", name: "node-4", publicIp: "139.99.125.20", isPrimary: false }, "data");
    const dedicatedAddr = "51.79.181.111";
    const running = opts.sourceRunning ?? true;
    this.src.vms.set(109, {
      vmid: 109,
      state: running ? "running" : "stopped",
      cfg: { name: "terraria-i2ydef", cores: 1, memory: 2048, balloon: 2048, agent: "enabled=1", scsi0: "vmdata:vm-109-disk-0,discard=on,size=25G", ide2: "vmdata:vm-109-cloudinit,media=cdrom", net0: opts.dedicated ? "virtio=02:00:00:fa:28:b1,bridge=vmbr0" : "virtio=BC:24:11:D1:57:FB,bridge=vmbr1", ipconfig0: opts.dedicated ? `ip=${dedicatedAddr}/32,gw=51.79.162.254` : "ip=10.20.0.101/24,gw=10.20.0.1", tags: "nxeon;user-abc", onboot: 1, ostype: "l26", scsihw: "virtio-scsi-single", boot: "order=scsi0" },
      snapshots: [],
    });
    this.src.datasets.set("data/vms/vm-109-disk-0", { bytes: 10 * 2 ** 30, snapshots: [], partial: false, resumeToken: null, data: ["blk0", "blk1", "blk2"] });
    if (opts.dedicated) {
      this.ovhRoute.set(dedicatedAddr, "ns5002569.ip-51-79-162.net");
      this.ovhMacs.set("ns5002569.ip-51-79-162.net", new Map([[dedicatedAddr, "02:00:00:fa:28:b1"]]));
    }
    this.server = {
      id: "srv1",
      hostname: "terraria-i2ydef",
      status: running ? "RUNNING" : "STOPPED",
      vmid: 109,
      nodeId: "n1",
      ipAddress: opts.dedicated ? dedicatedAddr : "10.20.0.101",
      sshPort: opts.dedicated ? null : 20109,
      subdomain: opts.dedicated ? null : "terra",
      userId: "u1",
      userEmail: "c@example.com",
      dedicatedIpAssigned: opts.dedicated,
      otherJobsInFlight: 0,
      dedicatedIpAddress: opts.dedicated ? dedicatedAddr : null,
      dedicatedNodeId: opts.dedicated ? "n1" : null,
      dedicatedMac: opts.dedicated ? "02:00:00:fa:28:b1" : null,
    };
    this.plan = {
      version: 1,
      serverId: "srv1",
      hostname: "terraria-i2ydef",
      sourceNodeId: "n1",
      sourceNodeName: "primary",
      targetNodeId: "n4",
      targetNodeName: "node-4",
      sourceVmid: 109,
      targetVmid: 601,
      planRamMB: 2048,
      planVcpu: 1,
      diskSizeGB: 25,
      sourceUsedBytes: 10 * 2 ** 30,
      sourceDataset: "data/vms/vm-109-disk-0",
      targetDataset: "data/vm-601-disk-0",
      sourceStorage: "vmdata",
      targetStorage: "vmdata",
      targetSnippetStorage: "vmdata-hdd",
      targetBridge: opts.dedicated ? "vmbr0" : "vmbr1",
      addressing: opts.dedicated
        ? { kind: "DEDICATED", address: dedicatedAddr, sourceGateway: "51.79.162.254", targetGateway: "139.99.125.254", sourceService: "ns5002569.ip-51-79-162.net", targetService: "ns564103.ip-139-99-125.net", sourceVirtualMac: "02:00:00:fa:28:b1" }
        : { kind: "NAT", sourcePrivateIp: "10.20.0.101", targetPrivateIpPlanned: "10.20.3.100", targetGateway: "10.20.3.1", sshPort: 20109, forwardPorts: [25565], sourcePublicIp: "51.79.162.10", targetPublicIp: "139.99.125.20" },
      carriedConfig: { name: "terraria-i2ydef", cores: "1", memory: "2048", balloon: "2048", agent: "enabled=1", tags: "nxeon;user-abc", ostype: "l26", scsihw: "virtio-scsi-single", boot: "order=scsi0", onboot: "1" },
      target: { nodeId: "n4", name: "node-4", region: "sgp1", realAvailRamMB: 20000, realTotalRamMB: 64000, committedRamMB: 10000, capacityRamMB: 56000, poolFreeBytes: 500 * 2 ** 30, poolTotalBytes: 900 * 2 ** 30, cpuThreads: 12, committedVcpu: 10, cpuLoad: 0.1 },
      checks: [],
      ok: true,
      estimatedDowntimeSec: 200,
      estimatedFullSendSec: 180,
      createdAt: new Date(this.clock).toISOString(),
      sourceStatusAtPreflight: running ? "RUNNING" : "STOPPED",
      shutdownTimeoutS: 180,
      gameProbe: { port: opts.dedicated ? 7777 : 25565, protocol: "tcp", family: "terraria" },
    };
    this.move = { id: moveId, serverId: "srv1", status: "PLANNED", phase: "PREFLIGHT", dryRun: false, plan: null, checkpoints: {}, requestedById: "admin1", startedAt: null };
  }

  // ---- fault injection ------------------------------------------------------------
  step(label: string): void {
    this.stepLog.push(label);
    for (const f of this.faults) {
      if (f.step !== label) continue;
      if (f.times !== undefined && f.times <= 0) continue;
      if (f.times !== undefined) f.times--;
      if (f.mode === "crash") throw new WorkerCrash(label);
      throw new Error(`injected failure at ${label}`);
    }
  }

  // ---- live invariants ---------------------------------------------------------------
  assertLiveInvariants(where: string): void {
    const s = this.src.vms.get(109);
    const t = this.tgt.vms.get(this.plan.targetVmid) ?? this.tgt.vms.get(601);
    if (s?.state === "running" && t?.state === "running") throw new Error(`INVARIANT I4 violated at ${where}: source and target both running`);
  }

  // ---- adapters -------------------------------------------------------------------------
  private hv(node: FakeNode, role: "source" | "target"): Hypervisor {
    const fleet = this;
    const get = (vmid: number) => node.vms.get(vmid);
    return {
      nodeName: node.facts.name,
      async vmState(vmid) {
        fleet.step(`${role}.hv.vmState`);
        const v = get(vmid);
        return (v ? v.state : "absent") as HvState;
      },
      async vmConfig(vmid) {
        fleet.step(`${role}.hv.vmConfig`);
        const v = get(vmid);
        return v ? { ...v.cfg } : null;
      },
      async setConfig(vmid, patch) {
        fleet.step(`${role}.hv.setConfig`);
        const v = get(vmid);
        if (!v) throw new Error(`vm ${vmid} absent`);
        Object.assign(v.cfg, patch);
        fleet.events.push(`${role}.setConfig ${vmid} ${JSON.stringify(patch)}`);
      },
      async listSnapshots(vmid) {
        fleet.step(`${role}.hv.listSnapshots`);
        return [...(get(vmid)?.snapshots ?? [])];
      },
      async createSnapshot(vmid, name) {
        fleet.step(`${role}.hv.createSnapshot`);
        const v = get(vmid);
        if (!v) throw new Error("absent");
        v.snapshots.push(name);
        const ds = node.datasets.get(`${node.pool}/vm-${vmid}-disk-0`);
        if (ds) ds.snapshots.push(name);
        fleet.events.push(`${role}.snapshot ${vmid}@${name}`);
      },
      async deleteSnapshot(vmid, name) {
        fleet.step(`${role}.hv.deleteSnapshot`);
        const v = get(vmid);
        if (v) v.snapshots = v.snapshots.filter((s) => s !== name);
        const ds = node.datasets.get(`${node.pool}/vm-${vmid}-disk-0`);
        if (ds) ds.snapshots = ds.snapshots.filter((s) => s !== name);
      },
      async shutdown(vmid) {
        fleet.step(`${role}.hv.shutdown`);
        const v = get(vmid);
        if (!v) throw new Error("absent");
        if (fleet.shutdownHangs) throw new Error("guest ignored ACPI shutdown");
        v.state = "stopped";
        fleet.events.push(`${role}.shutdown ${vmid}`);
      },
      async stop(vmid) {
        fleet.step(`${role}.hv.stop`);
        const v = get(vmid);
        if (!v) throw new Error("absent");
        v.state = "stopped";
        fleet.events.push(`${role}.stop ${vmid}`);
      },
      async start(vmid) {
        fleet.step(`${role}.hv.start`);
        const v = get(vmid);
        if (!v) throw new Error("absent");
        v.state = "running";
        fleet.events.push(`${role}.start ${vmid}`);
        fleet.assertLiveInvariants(`${role}.start`);
        // Booting the target writes the new IP into the disk (cloud-init re-IP).
        if (role === "target") {
          const ds = node.datasets.get(`${node.pool}/vm-${vmid}-disk-0`);
          if (ds) ds.data = [...ds.data, "netplan-rewritten"];
        }
      },
      async createVm(cfg) {
        fleet.step(`${role}.hv.createVm`);
        if (role === "source") throw new Error("INVARIANT I1: createVm on the source");
        const vmid = Number(cfg.vmid);
        if (node.vms.has(vmid)) throw new Error(`vm ${vmid} exists`);
        node.vms.set(vmid, { vmid, state: "stopped", cfg: { ...cfg }, snapshots: [] });
        fleet.events.push(`${role}.createVm ${vmid}`);
      },
      async destroyVm(vmid) {
        fleet.step(`${role}.hv.destroyVm`);
        if (role === "source") throw new Error("INVARIANT I1: destroyVm on the source");
        const v = node.vms.get(vmid);
        if (!v) throw new Error(`Configuration file 'nodes/x/qemu-server/${vmid}.conf' does not exist`);
        node.vms.delete(vmid);
        node.datasets.delete(`${node.pool}/vm-${vmid}-disk-0`);
        fleet.events.push(`${role}.destroyVm ${vmid}`);
      },
      async waitGuestAgent(vmid) {
        fleet.step(`${role}.hv.waitGuestAgent`);
        return fleet.guestAgentAnswers && get(vmid)?.state === "running";
      },
      async readGuestFile() {
        return null;
      },
    };
  }

  private sourceZfs(): SourceZfs {
    const fleet = this;
    const node = this.src;
    return {
      async dataset(d) {
        fleet.step("source.zfs.dataset");
        return fleet.dsInfo(node, d);
      },
      async snapshot(d, snap) {
        fleet.step("source.zfs.snapshot");
        const ds = node.datasets.get(d);
        if (!ds) throw new Error("does not exist");
        ds.snapshots.push(snap);
        fleet.events.push(`source.zfs.snapshot ${d}@${snap}`);
      },
      async deleteSnapshot(d, snap) {
        fleet.step("source.zfs.deleteSnapshot");
        if (!/^nxmove[12]-/.test(snap)) throw new Error("INVARIANT: deleting a non-move snapshot on the source");
        const ds = node.datasets.get(d);
        if (ds) ds.snapshots = ds.snapshots.filter((s) => s !== snap);
      },
      async sendStream(d, snap, from, opts) {
        fleet.step("source.zfs.sendStream");
        const ds = node.datasets.get(d);
        if (!ds || !ds.snapshots.includes(snap)) throw new Error(`cannot send ${d}@${snap}`);
        const payload = { kind: opts?.resumeToken ? "resume" : from ? "incremental" : "full", snap, from, data: ds.data, resume: opts?.resumeToken ?? null };
        const r = new PassThrough();
        r.end(Buffer.from(JSON.stringify(payload)));
        return r;
      },
    };
  }

  private targetZfs(): TargetZfs {
    const fleet = this;
    const node = this.tgt;
    return {
      async dataset(d) {
        fleet.step("target.zfs.dataset");
        return fleet.dsInfo(node, d);
      },
      async deleteSnapshot(d, snap) {
        fleet.step("target.zfs.deleteSnapshot");
        const ds = node.datasets.get(d);
        if (ds) ds.snapshots = ds.snapshots.filter((s) => s !== snap);
      },
      async destroyDataset(d) {
        fleet.step("target.zfs.destroyDataset");
        const p = parseVmDataset(d);
        if (!p) throw new Error("bad dataset");
        const ds = node.datasets.get(d);
        const verdict = datasetDestroyAllowed({ exists: !!ds, snapshots: ds?.snapshots ?? [], vmConfigExists: node.cfgExists(p.vmid) });
        if (!verdict.ok) throw new Error(`refusing: ${verdict.reason}`);
        node.datasets.delete(d);
        fleet.events.push(`target.zfs.destroyDataset ${d}`);
      },
      async vmConfigExists(vmid) {
        return node.cfgExists(vmid);
      },
      async recv(d, stream) {
        fleet.step("target.zfs.recv");
        const p = parseVmDataset(d);
        if (!p) throw new Error("bad dataset");
        if (node.cfgExists(p.vmid)) throw new Error(`refusing receive: vm ${p.vmid} has a config`);
        const chunks: Buffer[] = [];
        for await (const c of stream as Readable) chunks.push(Buffer.from(c));
        const payload = JSON.parse(Buffer.concat(chunks).toString("utf8"));
        fleet.step("target.zfs.recv.body"); // a failure HERE = interrupted mid-stream
        let ds = node.datasets.get(d);
        if (payload.kind === "full") {
          node.datasets.set(d, { bytes: fleet.plan.sourceUsedBytes, snapshots: [payload.snap], partial: false, resumeToken: null, data: [...payload.data] });
        } else if (payload.kind === "resume") {
          if (!ds || ds.resumeToken !== payload.resume) throw new Error("resume token mismatch");
          ds.partial = false;
          ds.resumeToken = null;
          ds.snapshots.push(payload.snap);
          ds.data = [...payload.data];
        } else {
          if (!ds || !ds.snapshots.includes(payload.from)) throw new Error("incremental source snapshot missing on target");
          ds.snapshots.push(payload.snap);
          ds.data = [...payload.data];
        }
        fleet.events.push(`target.zfs.recv ${d} ${payload.kind}@${payload.snap}`);
      },
    };
  }

  /** Simulate an interrupted receive: dataset exists, partial, with a resume token. */
  leavePartialReceive(d: string, withToken: boolean): void {
    this.tgt.datasets.set(d, { bytes: 1, snapshots: [], partial: true, resumeToken: withToken ? "1-abcdefabcdef-1234567890abcdef" : null, data: ["half"] });
  }

  private dsInfo(node: FakeNode, d: string): ZfsDatasetInfo {
    const ds = node.datasets.get(d);
    if (!ds) return { exists: false };
    return { exists: true, usedBytes: ds.bytes, referencedBytes: ds.bytes, volsizeBytes: 25 * 2 ** 30, snapshots: [...ds.snapshots], resumeToken: ds.resumeToken };
  }

  world(): MoveWorld {
    const fleet = this;
    return {
      now: () => new Date((fleet.clock += 1000)),
      keepSourceDays: 7,
      stallTimeoutMs: 60_000,
      async loadMove() {
        return { ...fleet.move, checkpoints: { ...fleet.move.checkpoints }, plan: fleet.move.plan ? { ...fleet.move.plan } : null };
      },
      async updateMove(data) {
        fleet.step("db.updateMove");
        Object.assign(fleet.move, data);
      },
      async saveCheckpoints(patch, phase?: MovePhase) {
        fleet.step("db.saveCheckpoints");
        fleet.move.checkpoints = { ...fleet.move.checkpoints, ...patch };
        if (phase) fleet.move.phase = phase;
        return { ...fleet.move.checkpoints };
      },
      async appendLog(phase, msg) {
        fleet.events.push(`log ${phase}: ${msg}`);
      },
      async progress() {},
      async loadServer() {
        fleet.step("db.loadServer");
        const { dedicatedIpAddress: _a, dedicatedNodeId: _n, dedicatedMac: _m, ...s } = fleet.server;
        return { ...s };
      },
      async setServerStatus(status) {
        fleet.step("db.setServerStatus");
        fleet.server.status = status;
        fleet.events.push(`db.status ${status}`);
      },
      async commitCutover(a) {
        fleet.step("db.commitCutover");
        if (a.ipAddress && fleet.dbReservedIps.has(a.ipAddress)) throw new Error("unique violation: ipAddress");
        fleet.server.nodeId = a.targetNodeId;
        fleet.server.vmid = a.targetVmid;
        fleet.server.status = a.status;
        if (a.ipAddress) fleet.server.ipAddress = a.ipAddress;
        if (a.dedicated) {
          fleet.server.dedicatedNodeId = a.targetNodeId;
          fleet.server.dedicatedMac = a.dedicated.virtualMac;
        }
        fleet.events.push(`db.commit node=${a.targetNodeId} vmid=${a.targetVmid}`);
      },
      async claimTargetVmid(floor) {
        fleet.step("db.claimTargetVmid");
        fleet.highWater = Math.max(fleet.highWater + 1, floor);
        return fleet.highWater;
      },
      async preflight() {
        fleet.step("preflight");
        return { ...fleet.plan, checks: [...fleet.plan.checks] };
      },
      async allocateTargetPrivateIp() {
        fleet.step("ipam.allocate");
        return "10.20.3.100";
      },
      async rootPassword() {
        return "root-pw";
      },
      source: { node: fleet.src.facts, hv: fleet.hv(fleet.src, "source"), zfs: fleet.sourceZfs() },
      target: { node: fleet.tgt.facts, hv: fleet.hv(fleet.tgt, "target"), zfs: fleet.targetZfs() },
      snippets: {
        async write(node, _storage, filename) {
          fleet.step("snippets.write");
          fleet.events.push(`snippet.write ${node.name} ${filename}`);
        },
        async delete(node, _storage, filename) {
          fleet.step("snippets.delete");
          fleet.events.push(`snippet.delete ${node.name} ${filename}`);
        },
      },
      ovh: {
        async moveIp(ip, to) {
          fleet.step("ovh.moveIp");
          if (fleet.ovhRoute.get(ip) === to) return null;
          if (fleet.ovhMoveDelayFail) throw new Error("OVH task error");
          fleet.ovhRoute.set(ip, to);
          fleet.events.push(`ovh.moveIp ${ip} -> ${to}`);
          return 42;
        },
        async ensureVirtualMac(service, ip) {
          fleet.step("ovh.ensureVirtualMac");
          let m = fleet.ovhMacs.get(service);
          if (!m) fleet.ovhMacs.set(service, (m = new Map()));
          if (!m.has(ip)) m.set(ip, `02:00:00:${service.slice(2, 4)}:00:01`);
          return m.get(ip)!;
        },
        async releaseVirtualMac(service, ip) {
          fleet.step("ovh.releaseVirtualMac");
          fleet.ovhMacs.get(service)?.delete(ip);
        },
        async routedTo(ip) {
          return fleet.ovhRoute.get(ip) ?? null;
        },
      },
      net: {
        async syncPortForwards(ctx) {
          fleet.step("net.syncPortForwards");
          fleet.natSyncs.push(ctx);
          return fleet.natFail ? new Error("agent unreachable") : null;
        },
        async checkSsh() {
          fleet.step("net.checkSsh");
          return { ok: fleet.sshAnswers, error: fleet.sshAnswers ? undefined : "timeout" };
        },
        async checkGamePort() {
          fleet.step("net.checkGamePort");
          return { ok: fleet.gameAnswers, error: fleet.gameAnswers ? undefined : "timeout" };
        },
        async targetReachable() {
          return fleet.tgt.agentUp;
        },
      },
      dns: {
        async queueGameDnsSync(serverId) {
          fleet.step("dns.queue");
          fleet.dnsQueued.push(serverId);
        },
      },
      notify: {
        async customer(_u, title) {
          fleet.notices.push({ kind: "customer", title });
        },
        async email(_to, subject) {
          fleet.notices.push({ kind: "email", title: subject });
        },
        async admins(title) {
          fleet.notices.push({ kind: "admins", title });
        },
      },
      async audit(action, _t, detail) {
        fleet.audits.push(`${action} ${detail}`);
      },
      isFinalAttempt: () => fleet.jobAttempts >= 3,
    };
  }

  // ---- assertions used by every scenario ----------------------------------------------
  sourceIntact(): boolean {
    const s = this.src.vms.get(109);
    const ds = this.src.datasets.get("data/vms/vm-109-disk-0");
    return !!s && !!ds && ds.data.slice(0, 3).join() === "blk0,blk1,blk2";
  }
}

