import { test } from "node:test";
import assert from "node:assert/strict";
import { runMove, partialReceiveDecision, MoveAbort } from "../lib/vm-move/engine.ts";
import { MOVE_PHASES, type MoveCheckpoints } from "../lib/vm-move/types.ts";
import { inDarkWindow, nextPhase, remainingRollbackSteps, rollbackInterrupted, rollbackSteps } from "../lib/vm-move/plan.ts";
import { FakeFleet, WorkerCrash, type Fault } from "./_vm-move-fake-world.ts";

/**
 * The VM move engine driven end to end against an in-memory fleet, with a
 * failure injected at EVERY step boundary. The point is not that each
 * scenario "passes" — it is that after ANY failure the invariants from
 * docs/VM-MOVE-DEEP-ANALYSIS.md hold:
 *
 *   I1  source VM + disk never destroyed / never written destructively
 *   I2  only the move's own tagged target VM / move-owned dataset is destroyed
 *   I3  automatic rollback only inside the dark window (or final attempt pre-commit)
 *   I4  never both VMs running
 *   I5  a crash anywhere resumes (forward or the interrupted rollback) to a clean end state
 *   I6  rollback leaves the customer exactly as before
 */

/** Drive the engine like the worker does: attempt until a terminal outcome. */
async function drive(fleet: FakeFleet, opts?: { maxRuns?: number }): Promise<{ outcome: string; runs: number; errors: string[] }> {
  const errors: string[] = [];
  const maxRuns = opts?.maxRuns ?? 12;
  for (let run = 1; run <= maxRuns; run++) {
    fleet.jobAttempts = Math.min(3, run); // the worker burns an attempt per throw (restarts don't)
    try {
      const o = await runMove(fleet.world());
      return { outcome: o, runs: run, errors };
    } catch (e: any) {
      errors.push(String(e?.message ?? e));
      if (e instanceof WorkerCrash) {
        fleet.jobAttempts = Math.max(1, fleet.jobAttempts - 1); // a restart is not the job's fault
        continue;
      }
      if (["DONE", "ROLLED_BACK", "FAILED", "CLEANED"].includes(fleet.move.status)) return { outcome: fleet.move.status, runs: run, errors };
    }
  }
  return { outcome: fleet.move.status, runs: maxRuns, errors };
}

function assertCleanDone(fleet: FakeFleet, dedicated: boolean) {
  const tgtVmid = fleet.plan.targetVmid === 601 ? fleet.highWater : fleet.plan.targetVmid;
  assert.equal(fleet.move.status, "DONE");
  assert.ok(fleet.move.checkpoints.committedAt && fleet.move.checkpoints.finalizedAt, "commit + finalize checkpoints");
  // DB points at the target
  assert.equal(fleet.server.nodeId, "n4");
  assert.equal(fleet.server.vmid, tgtVmid);
  assert.equal(fleet.server.status, "RUNNING");
  // Target running, source stopped + neutralised, never destroyed (I1)
  const t = fleet.tgt.vms.get(tgtVmid)!;
  assert.ok(t, "target vm exists");
  assert.equal(t.state, "running");
  assert.ok(String(t.cfg.tags).includes(`nxmove-${fleet.move.id}`), "target carries the ownership tag");
  const s = fleet.src.vms.get(109)!;
  assert.ok(s, "source vm still exists (kept)");
  assert.equal(s.state, "stopped");
  assert.equal(s.cfg.onboot, 0);
  assert.ok(String(s.cfg.tags).includes("nxeon-moved"));
  assert.match(String(s.cfg.net0), /link_down=1/);
  assert.ok(fleet.sourceIntact(), "source disk bytes untouched");
  assert.ok(!fleet.events.some((e) => e.startsWith("source.destroyVm") || e.startsWith("source.createVm")), "I1: no destroy/create on source");
  // the received disk carries the full data + the re-IP
  const ds = fleet.tgt.datasets.get(`data/vm-${tgtVmid}-disk-0`)!;
  assert.ok(ds && ds.data.slice(0, 3).join() === "blk0,blk1,blk2", "target disk == source disk");
