}

function assertCleanRollback(fleet: FakeFleet, dedicated: boolean, wasRunning = true) {
  assert.equal(fleet.move.status, "ROLLED_BACK", `expected ROLLED_BACK, got ${fleet.move.status}: ${fleet.move.checkpoints.rollback?.errors?.join(" | ")}`);
  const s = fleet.src.vms.get(109)!;
  assert.ok(s, "source vm exists");
  assert.equal(s.state, wasRunning ? "running" : "stopped", "source back to its previous power state");
  assert.ok(fleet.sourceIntact());
  assert.equal(fleet.server.nodeId, "n1");
  assert.equal(fleet.server.vmid, 109);
  assert.equal(fleet.server.status, wasRunning ? "RUNNING" : "STOPPED");
  // nothing of ours left on the target
  for (const [vmid, v] of fleet.tgt.vms) assert.ok(!String(v.cfg.tags).includes("nxmove-"), `target vm ${vmid} left behind`);
  for (const [name] of fleet.tgt.datasets) assert.ok(!/vm-6\d\d-disk-0/.test(name), `target dataset ${name} left behind`);
  if (dedicated) {
    assert.equal(fleet.ovhRoute.get("51.79.181.111"), "ns5002569.ip-51-79-162.net", "IP routed back to the source");
    assert.equal(fleet.server.dedicatedNodeId, "n1");
    assert.match(String(s.cfg.ipconfig0), /51\.79\.181\.111\/32,gw=51\.79\.162\.254/);
  }
  assert.ok(!fleet.events.some((e) => e.startsWith("source.destroyVm")), "I1");
  assert.ok(!(s.cfg.tags as string).includes("nxeon-moved"), "no post-commit tag after a rollback");
}

