// Fault injection at EVERY step boundary (I3 / I5 / I6)
// ---------------------------------------------------------------------------

async function recordSteps(dedicated: boolean): Promise<string[]> {
  const f = new FakeFleet({ dedicated });
  await drive(f);
  // unique, in first-seen order
  return [...new Set(f.stepLog)];
}

for (const dedicated of [false, true]) {
  test(`${dedicated ? "DEDICATED" : "NAT"}: a THROWN failure at every step boundary ends DONE or ROLLED_BACK with invariants intact`, async () => {
    const steps = await recordSteps(dedicated);
    assert.ok(steps.length > 25, `expected a rich step log, got ${steps.length}`);
    const summary: Record<string, number> = {};
    for (const step of steps) {
      const fleet = new FakeFleet({ dedicated });
      fleet.faults = [{ step, mode: "throw", times: 1 }];
      const r = await drive(fleet);
      summary[r.outcome] = (summary[r.outcome] ?? 0) + 1;
      const ctx = `fault@${step} → ${r.outcome} (${r.errors.join(" | ")})`;
      assert.ok(["DONE", "ROLLED_BACK"].includes(r.outcome), `unexpected terminal state: ${ctx}`);
      assert.ok(fleet.sourceIntact(), `I1 source intact: ${ctx}`);
      assert.ok(!fleet.events.some((e) => e.startsWith("source.destroyVm")), `I1: ${ctx}`);
      if (r.outcome === "DONE") assertCleanDone(fleet, dedicated);
      else assertCleanRollback(fleet, dedicated);
      // Rollback happened only inside the dark window or on the final attempt (I3)
      if (r.outcome === "ROLLED_BACK") {
        const cp = fleet.move.checkpoints;
        assert.ok(!cp.committedAt, `I3 no rollback after commit: ${ctx}`);
      }
    }
    assert.ok(summary.DONE > 0 && summary.ROLLED_BACK > 0, `expected both outcomes across steps: ${JSON.stringify(summary)}`);
  });

  test(`${dedicated ? "DEDICATED" : "NAT"}: a WORKER CRASH at every step boundary resumes to a clean end state (I5)`, async () => {
    const steps = await recordSteps(dedicated);
    for (const step of steps) {
      const fleet = new FakeFleet({ dedicated });
      fleet.faults = [{ step, mode: "crash", times: 1 }];
      const r = await drive(fleet);
      const ctx = `crash@${step} → ${r.outcome} (${r.errors.join(" | ")})`;
      assert.ok(["DONE", "ROLLED_BACK"].includes(r.outcome), ctx);
      if (r.outcome === "DONE") assertCleanDone(fleet, dedicated);
      else assertCleanRollback(fleet, dedicated);
    }
  });

  test(`${dedicated ? "DEDICATED" : "NAT"}: a crash DURING ROLLBACK resumes the rollback, not the forward path`, async () => {
    // Fail inside the dark window (start of target) to trigger rollback, then crash on the first rollback step.
    const fleet = new FakeFleet({ dedicated });
    fleet.guestAgentAnswers = false; // START_TARGET verification fails → rollback
    fleet.sshAnswers = false;
    fleet.faults = [{ step: dedicated ? "ovh.releaseVirtualMac" : "target.hv.stop", mode: "crash", times: 1 }];
    const r = await drive(fleet);
    assert.equal(r.outcome, "ROLLED_BACK", r.errors.join(" | "));
    assertCleanRollback(fleet, dedicated);
    assert.ok(fleet.move.checkpoints.rollback?.finishedAt);
    assert.ok(!fleet.events.some((e) => e.startsWith("db.commit")), "never committed");
  });
}

