// ---------------------------------------------------------------------------
// Property-style checks on the pure state machine
// ---------------------------------------------------------------------------

function rng(seed: number) {
  let s = seed >>> 0;
  return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 2 ** 32);
}

const CP_KEYS: (keyof MoveCheckpoints)[] = ["liveSnapshotName", "fullSentAt", "sourceStoppedAt", "incrementalSnapshotName", "incrementalSentAt", "targetVmCreated", "targetSnippetWritten", "ipMovedAt", "targetVirtualMac", "targetStartedAt", "targetVerified", "committedAt", "finalizedAt", "sourceWasRunning"];

test("fuzz: nextPhase is monotonic in the phase order and never skips an incomplete phase", () => {
  const r = rng(7);
  for (let i = 0; i < 2000; i++) {
    const cp: MoveCheckpoints = {};
    for (const k of CP_KEYS) if (r() < 0.5) (cp as any)[k] = k === "targetVmCreated" || k === "targetSnippetWritten" || k === "targetVerified" ? true : k === "sourceWasRunning" ? r() < 0.5 : "x";
    const dedicated = r() < 0.5;
    const p = nextPhase(cp, { dedicated });
    const idx = MOVE_PHASES.indexOf(p);
    assert.ok(idx > 0, "never PREFLIGHT");
    // every phase BEFORE p must be complete
    for (let j = 1; j < idx; j++) {
      const q = MOVE_PHASES[j];
      const complete =
        (q === "SNAPSHOT_LIVE" && !!cp.liveSnapshotName) ||
        (q === "SEND_FULL" && !!cp.fullSentAt) ||
        (q === "STOP_SOURCE" && !!cp.sourceStoppedAt) ||
        (q === "SEND_INCREMENTAL" && !!cp.incrementalSentAt) ||
        (q === "CREATE_TARGET" && !!cp.targetVmCreated) ||
        (q === "MOVE_IP" && (!dedicated || !!cp.ipMovedAt)) ||
        (q === "START_TARGET" && !!cp.targetVerified) ||
        (q === "COMMIT" && !!cp.committedAt) ||
        (q === "FINALIZE" && !!cp.finalizedAt);
      assert.ok(complete, `phase ${q} incomplete but nextPhase returned ${p}: ${JSON.stringify(cp)}`);
    }
    // DONE iff committed+finalized
    assert.equal(p === "DONE", !!cp.committedAt && !!cp.finalizedAt);
    // dark window definition
    assert.equal(inDarkWindow(cp), !!cp.sourceStoppedAt && !cp.committedAt);
  }
});

test("fuzz: rollbackSteps is a safe-ordered inventory of exactly what exists", () => {
  const r = rng(11);
  const order = ["MOVE_IP_BACK", "STOP_TARGET", "DESTROY_TARGET_VM", "DESTROY_TARGET_DATASET", "DELETE_TARGET_SNIPPET", "DELETE_SOURCE_INCREMENTAL_SNAPSHOT", "START_SOURCE", "RESTORE_DB_STATUS"];
  for (let i = 0; i < 2000; i++) {
    const cp: MoveCheckpoints = {};
    for (const k of CP_KEYS) if (r() < 0.5) (cp as any)[k] = k === "sourceWasRunning" ? r() < 0.5 : k.endsWith("Created") || k.endsWith("Written") || k.endsWith("Verified") ? true : "x";
    const dedicated = r() < 0.5;
    const steps = rollbackSteps(cp, { dedicated });
    // strictly increasing in the canonical order (IP back first, DB last)
    const idx = steps.map((s) => order.indexOf(s));
    for (let j = 1; j < idx.length; j++) assert.ok(idx[j] > idx[j - 1], `order violated: ${steps.join(",")}`);
    assert.equal(steps[steps.length - 1], "RESTORE_DB_STATUS");
    assert.equal(steps.includes("MOVE_IP_BACK"), dedicated && !!cp.ipMovedAt);
    assert.equal(steps.includes("DESTROY_TARGET_VM"), !!cp.targetVmCreated);
    assert.equal(steps.includes("DESTROY_TARGET_DATASET"), !cp.targetVmCreated && !!cp.fullSentAt, "dataset destroy only when no VM references it");
    assert.equal(steps.includes("START_SOURCE"), !!cp.sourceStoppedAt && cp.sourceWasRunning !== false);
    if (cp.targetStartedAt) assert.ok(steps.indexOf("STOP_TARGET") < steps.indexOf("START_SOURCE") || !steps.includes("START_SOURCE"), "target stopped before source started (I4)");
