// Happy paths
// ---------------------------------------------------------------------------

test("NAT move completes end to end and leaves the fleet in the documented end state", async () => {
  const fleet = new FakeFleet({ dedicated: false });
  const r = await drive(fleet);
  assert.equal(r.outcome, "DONE", r.errors.join(" | "));
  assertCleanDone(fleet, false);
  // The customer-visible dark window: stop → start, never both running (I4 checked live too)
  const stopIdx = fleet.events.findIndex((e) => e.startsWith("source.shutdown"));
  const startIdx = fleet.events.findIndex((e) => e.startsWith("target.start"));
  assert.ok(stopIdx > 0 && startIdx > stopIdx);
  // The private IP reservation is persisted BEFORE the target VM exists
  const resIdx = fleet.events.findIndex((e) => e.startsWith("target.createVm"));
  assert.ok(fleet.move.checkpoints.targetPrivateIp === "10.20.3.100" && resIdx > 0);
});

test("dedicated-IP move carries the address, binds a new vMAC and never emails the customer", async () => {
  const fleet = new FakeFleet({ dedicated: true });
  const r = await drive(fleet);
  assert.equal(r.outcome, "DONE", r.errors.join(" | "));
  assertCleanDone(fleet, true);
  const t = fleet.tgt.vms.get(fleet.highWater)!;
  assert.match(String(t.cfg.net0), /^virtio=02:00:00:[0-9a-z]{2}:00:01,bridge=vmbr0$/);
  assert.match(String(t.cfg.ipconfig0), /ip=51\.79\.181\.111\/32,gw=139\.99\.125\.254/);
  // The IP moved only AFTER the source was stopped and BEFORE the target started
  const order = fleet.events.map((e) => e.split(" ")[0]);
  assert.ok(order.indexOf("source.shutdown") < order.indexOf("ovh.moveIp") && order.indexOf("ovh.moveIp") < order.indexOf("target.start"));
});

test("a server the customer had STOPPED is booted once for the re-IP, then stopped again; DB says STOPPED", async () => {
  const fleet = new FakeFleet({ dedicated: false, sourceRunning: false });
  const r = await drive(fleet);
  assert.equal(r.outcome, "DONE", r.errors.join(" | "));
  assert.equal(fleet.server.status, "STOPPED");
  assert.equal(fleet.tgt.vms.get(fleet.highWater)!.state, "stopped");
  assert.equal(fleet.move.checkpoints.sourceWasRunning, false);
  assert.ok(!fleet.events.some((e) => e.startsWith("source.start")), "a stopped source is never started by the move");
});

test("the target vmid is CLAIMED from the fleet high-water mark, not the preflight candidate", async () => {
  const fleet = new FakeFleet({ dedicated: false });
  fleet.highWater = 700; // somebody provisioned up to 700 since the plan said 601
  await drive(fleet);
  assert.equal(fleet.move.plan!.targetVmid, 701);
  assert.equal(fleet.move.plan!.targetDataset, "data/vm-701-disk-0");
  assert.equal(fleet.server.vmid, 701);
});

// ---------------------------------------------------------------------------
// Fault injection at EVERY step boundary (I3 / I5 / I6)
// ---------------------------------------------------------------------------

async function recordSteps(dedicated: boolean): Promise<string[]> {
  const f = new FakeFleet({ dedicated });
  await drive(f);
  // unique, in first-seen order
  return [...new Set(f.stepLog)];
}

for (const dedicated of [false, true]) {
  test(`${dedicated ? "DEDICATED" : "NAT"}: a THROWN failure at every step boundary ends DONE or ROLLED_BACK with invariants intact`, async () => {
    const steps = await recordSteps(dedicated);
    assert.ok(steps.length > 25, `expected a rich step log, got ${steps.length}`);
    const summary: Record<string, number> = {};
    for (const step of steps) {
      const fleet = new FakeFleet({ dedicated });
      fleet.faults = [{ step, mode: "throw", times: 1 }];
      const r = await drive(fleet);
      summary[r.outcome] = (summary[r.outcome] ?? 0) + 1;
      const ctx = `fault@${step} → ${r.outcome} (${r.errors.join(" | ")})`;
      assert.ok(["DONE", "ROLLED_BACK"].includes(r.outcome), `unexpected terminal state: ${ctx}`);
      assert.ok(fleet.sourceIntact(), `I1 source intact: ${ctx}`);
      assert.ok(!fleet.events.some((e) => e.startsWith("source.destroyVm")), `I1: ${ctx}`);
      if (r.outcome === "DONE") assertCleanDone(fleet, dedicated);
      else assertCleanRollback(fleet, dedicated);
      // Rollback happened only inside the dark window or on the final attempt (I3)
      if (r.outcome === "ROLLED_BACK") {
        const cp = fleet.move.checkpoints;
        assert.ok(!cp.committedAt, `I3 no rollback after commit: ${ctx}`);
      }
    }
    assert.ok(summary.DONE > 0 && summary.ROLLED_BACK > 0, `expected both outcomes across steps: ${JSON.stringify(summary)}`);
  });

  test(`${dedicated ? "DEDICATED" : "NAT"}: a WORKER CRASH at every step boundary resumes to a clean end state (I5)`, async () => {
    const steps = await recordSteps(dedicated);
    for (const step of steps) {
      const fleet = new FakeFleet({ dedicated });
      fleet.faults = [{ step, mode: "crash", times: 1 }];
      const r = await drive(fleet);
      const ctx = `crash@${step} → ${r.outcome} (${r.errors.join(" | ")})`;
      assert.ok(["DONE", "ROLLED_BACK"].includes(r.outcome), ctx);
      if (r.outcome === "DONE") assertCleanDone(fleet, dedicated);
      else assertCleanRollback(fleet, dedicated);
    }
  });

  test(`${dedicated ? "DEDICATED" : "NAT"}: a crash DURING ROLLBACK resumes the rollback, not the forward path`, async () => {
    // Fail inside the dark window (start of target) to trigger rollback, then crash on the first rollback step.
    const fleet = new FakeFleet({ dedicated });
    fleet.guestAgentAnswers = false; // START_TARGET verification fails → rollback
    fleet.sshAnswers = false;
    fleet.faults = [{ step: dedicated ? "ovh.releaseVirtualMac" : "target.hv.stop", mode: "crash", times: 1 }];
    const r = await drive(fleet);
    assert.equal(r.outcome, "ROLLED_BACK", r.errors.join(" | "));
    assertCleanRollback(fleet, dedicated);
    assert.ok(fleet.move.checkpoints.rollback?.finishedAt);
    assert.ok(!fleet.events.some((e) => e.startsWith("db.commit")), "never committed");
  });
}

test("two consecutive failures before the dark window retry from the checkpoint; the full stream is never re-sent", async () => {
  const fleet = new FakeFleet({ dedicated: false });
  fleet.faults = [{ step: "source.hv.shutdown", mode: "throw", times: 2 }];
  const r = await drive(fleet);
  assert.equal(r.outcome, "DONE", r.errors.join(" | "));
  const fullSends = fleet.events.filter((e) => /target\.zfs\.recv .* full@/.test(e)).length;
  assert.equal(fullSends, 1, "the 10 GB full pass streamed exactly once");
  assert.equal(r.runs, 3);
});

test("the FINAL attempt before the dark window cleans up the target side and rolls back (source never stopped)", async () => {
  const fleet = new FakeFleet({ dedicated: false });
  fleet.faults = [{ step: "source.hv.shutdown", mode: "throw" }]; // every time
  const r = await drive(fleet);
  assert.equal(r.outcome, "ROLLED_BACK");
  assert.equal(fleet.src.vms.get(109)!.state, "running");
  assert.ok(!fleet.tgt.datasets.has("data/vm-601-disk-0"), "received dataset removed");
  assert.ok(!fleet.events.some((e) => e.startsWith("db.status STOPPED")), "customer never went dark");
});

test("post-commit failures never roll back: FINALIZE is retried step by step, the DB keeps pointing at the target", async () => {
  const fleet = new FakeFleet({ dedicated: false });
  fleet.natFail = true;
  fleet.faults = [];
  // run 1: commits, FINALIZE fails on NAT → retry; run 2: same; run 3 (final) → FAILED post-commit
  const r = await drive(fleet);
  assert.equal(r.outcome, "FAILED");
  assert.ok(fleet.move.checkpoints.committedAt);
  assert.ok(!fleet.move.checkpoints.rollback, "no rollback after commit (I3)");
  assert.equal(fleet.server.nodeId, "n4", "DB still points at the target");
