  assert.ok(fleet.notices.some((n) => n.kind === "admins" && /post-commit/.test(n.title)));
  // the source was still neutralised in the first FINALIZE pass (idempotent sub-step)
  assert.equal(fleet.src.vms.get(109)!.cfg.onboot, 0);
  // now fix NAT and run again: the remainder completes without redoing anything
  fleet.natFail = false;
  fleet.move.status = "RUNNING"; // operator "retry" (what the admin UI's re-queue does)
  fleet.jobAttempts = 1;
  const o = await runMove(fleet.world());
  assert.equal(o, "DONE");
  assert.equal(fleet.natSyncs.length, 4, "NAT sync attempted 3 times failed + once ok");
  assert.equal(fleet.dnsQueued.length, 1, "DNS queued exactly once");
  assert.equal(fleet.notices.filter((n) => n.kind === "email").length, 1, "customer emailed exactly once");
});

