test("a FOREIGN VM at the claimed target vmid is neither reused nor destroyed; the move rolls back", async () => {
  const fleet = new FakeFleet({ dedicated: false });
  // Someone provisioned vmid 601 on node-4 *after* our claim (should be impossible with the high-water mark; prove the engine still refuses).
  fleet.tgt.vms.set(601, { vmid: 601, state: "stopped", cfg: { name: "someone-else", tags: "nxeon;user-zzz" }, snapshots: [] });
  fleet.highWater = 600; // so the claim yields 601
  const r = await drive(fleet);
  assert.equal(r.outcome, "FAILED", r.errors.join(" | "));
  assert.ok(fleet.tgt.vms.has(601), "foreign VM untouched");
  assert.equal(fleet.tgt.vms.get(601)!.cfg.name, "someone-else");
  assert.equal(fleet.src.vms.get(109)!.state, "running");
});

test("a VM at the target vmid that appears mid-move (after the claim) aborts and rolls back without destroying it", async () => {
  const fleet = new FakeFleet({ dedicated: false });
  // Inject the foreign VM right before CREATE_TARGET reads the target config (after the full send, during the dark window).
  const origStep = fleet.step.bind(fleet);
  let planted = false;
  fleet.step = (label: string) => {
    if (label === "target.hv.vmConfig" && fleet.move.checkpoints.incrementalSentAt && !planted) {
      planted = true;
      fleet.tgt.vms.set(fleet.highWater, { vmid: fleet.highWater, state: "stopped", cfg: { name: "intruder", tags: "nxeon" }, snapshots: [] });
    }
    origStep(label);
  };
  const r = await drive(fleet);
  assert.equal(r.outcome, "ROLLED_BACK", r.errors.join(" | "));
  assert.ok(fleet.tgt.vms.has(fleet.highWater), "intruder VM not destroyed (I2)");
  assert.equal(fleet.tgt.vms.get(fleet.highWater)!.cfg.name, "intruder");
  assert.ok(fleet.move.checkpoints.rollback!.errors.some((e) => /NOT destroyed/.test(e)), "the refusal is recorded, not hidden");
  assert.equal(fleet.src.vms.get(109)!.state, "running", "source back up");
  assert.equal(fleet.move.status, "ROLLED_BACK");
});

test("a dataset at the target with FOREIGN snapshots is never destroyed (destroy guard), the move fails safe", async () => {
  const fleet = new FakeFleet({ dedicated: false });
  fleet.tgt.datasets.set("data/vm-601-disk-0", { bytes: 5, snapshots: ["autosnap_2026"], partial: false, resumeToken: null, data: ["theirs"] });
  fleet.highWater = 600;
  const r = await drive(fleet);
  assert.ok(["FAILED", "ROLLED_BACK"].includes(r.outcome), r.errors.join(" | "));
  assert.deepEqual(fleet.tgt.datasets.get("data/vm-601-disk-0")!.data, ["theirs"], "foreign dataset intact");
  assert.ok(fleet.sourceIntact());
});

test("an interrupted full send RESUMES from the receive token instead of re-streaming", async () => {
  const fleet = new FakeFleet({ dedicated: false });
  fleet.highWater = 600;
  // Pretend the previous attempt died mid-stream and left a resumable partial dataset
  fleet.leavePartialReceive("data/vm-601-disk-0", true);
  fleet.move.plan = { ...fleet.plan, version: 2, targetVmid: 601 };
  fleet.move.status = "RUNNING";
  fleet.move.phase = "SEND_FULL";
  fleet.move.checkpoints = { liveSnapshotName: `nxmove1-${fleet.move.id}` };
  fleet.src.datasets.get("data/vms/vm-109-disk-0")!.snapshots.push(`nxmove1-${fleet.move.id}`);
  const r = await drive(fleet);
  assert.equal(r.outcome, "DONE", r.errors.join(" | "));
  assert.ok(fleet.events.some((e) => /target\.zfs\.recv .* resume@/.test(e)), "resume path used");
  assert.ok(!fleet.events.some((e) => e.startsWith("target.zfs.destroyDataset")), "partial dataset was not thrown away");
});

test("an interrupted full send WITHOUT a resume token restarts the dataset (move-owned, so destroy is allowed)", async () => {
  const fleet = new FakeFleet({ dedicated: false });
  fleet.highWater = 600;
  fleet.leavePartialReceive("data/vm-601-disk-0", false);
  fleet.move.plan = { ...fleet.plan, version: 2, targetVmid: 601 };
  fleet.move.status = "RUNNING";
  fleet.move.phase = "SEND_FULL";
  fleet.move.checkpoints = { liveSnapshotName: `nxmove1-${fleet.move.id}` };
  fleet.src.datasets.get("data/vms/vm-109-disk-0")!.snapshots.push(`nxmove1-${fleet.move.id}`);
  const r = await drive(fleet);
  assert.equal(r.outcome, "DONE", r.errors.join(" | "));
  assert.ok(fleet.events.some((e) => e.startsWith("target.zfs.destroyDataset data/vm-601-disk-0")));
});

test("the pre-stop gate refuses to open the dark window when the world changed (SUSPEND landed, IP released, target down)", async () => {
  for (const mutate of [
    (f: FakeFleet) => (f.server.status = "SUSPENDED"),
    (f: FakeFleet) => (f.server.otherJobsInFlight = 1),
    (f: FakeFleet) => (f.tgt.agentUp = false),
  ]) {
    const fleet = new FakeFleet({ dedicated: false });
    const orig = fleet.step.bind(fleet);
    fleet.step = (l: string) => {
      if (l === "source.hv.vmState" && fleet.move.checkpoints.fullSentAt && !fleet.move.checkpoints.sourceStoppedAt) mutate(fleet);
      orig(l);
