/**
 * VM move rehearsal runner — docs/VM-MOVE-DEEP-ANALYSIS.md §5 (Stages 1–2).
 *
 * Drives the REAL engine through the job queue (the running worker executes
 * the VM_MOVE job, exactly what an admin click does) against a THROWAWAY test
 * VM, takes a guest fingerprint before and after (scripts/vm-move-fingerprint.sh
 * over the platform's own SSH path), diffs them, and prints a verdict.
 *
 * SAFETY RAILS (all enforced before anything is enqueued):
 *   - DRY RUN BY DEFAULT. `--execute` is required for a real move.
 *   - Refuses any server whose Proxmox VM is not tagged `qa-move-test`.
 *   - Refuses any server whose owner is not the rehearsal account
 *     (VM_MOVE_REHEARSAL_ACCOUNT, default qa-move@nxeon-internal.test).
 *   - Refuses a server with a plan it did not expect for a rehearsal
 *     (paid customers never have the tag; this is belt and braces).
 *   - Never touches the primary as a TARGET unless --allow-primary-target.
 *   - Never runs two rehearsals at once (one RUNNING VmMove for the server).
 *
 * Usage (from the primary, repo root, with the prod .env so the worker picks up the job):
 *   npx tsx scripts/vm-move-rehearsal.ts --server <serverId|hostname> --target <nodeName>            # dry run (preflight only)
 *   npx tsx scripts/vm-move-rehearsal.ts --server … --target … --execute [--force-stop] [--cleanup]  # the real thing
 *   npx tsx scripts/vm-move-rehearsal.ts --prepare --server …   # install the rehearsal payload in the guest (docker+db+cron+file+ssh key+listener)
 *
 * Output: a JSON report in /root/vm-move-rehearsals/<moveId>.json plus before/after fingerprints and the diff.
 */
import { mkdirSync, writeFileSync, readFileSync } from "node:fs";
import { PrismaClient } from "@prisma/client";
import { withServerSsh, exec } from "../lib/ssh-exec";
import { pveFor } from "../lib/proxmox";
import { buildMovePlan } from "../lib/vm-move/preflight";
import { splitTags } from "../lib/vm-move/plan";
import type { MoveLogLine, MovePlan } from "../lib/vm-move/types";

const db = new PrismaClient();
const REHEARSAL_TAG = "qa-move-test";
const ACCOUNT = process.env.VM_MOVE_REHEARSAL_ACCOUNT ?? "qa-move@nxeon-internal.test";
const OUT_DIR = process.env.VM_MOVE_REHEARSAL_DIR ?? "/root/vm-move-rehearsals";
const FINGERPRINT = readFileSync(new URL("./vm-move-fingerprint.sh", import.meta.url), "utf8");
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

function arg(name: string): string | undefined {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 ? process.argv[i + 1] : undefined;
}
const flag = (name: string) => process.argv.includes(`--${name}`);

/** The payload that makes a plain test VM look like a real customer box: docker + a DB + a file + a key + a listener + cron. */
const PREPARE_SCRIPT = `set -e
export DEBIAN_FRONTEND=noninteractive
command -v docker >/dev/null 2>&1 || (curl -fsSL https://get.docker.com | sh)
command -v mariadb >/dev/null 2>&1 || apt-get install -y -q mariadb-server >/dev/null
systemctl enable --now mariadb >/dev/null 2>&1 || true
mysql -e "create database if not exists rehearsal; create table if not exists rehearsal.t (id int primary key, v text); insert ignore into rehearsal.t values (1,'before-move'),(2,'$(date -Is)');"
docker volume create rehearsal-vol >/dev/null
docker run -d --name rehearsal-redis --restart unless-stopped -v rehearsal-vol:/data redis:7-alpine redis-server --appendonly yes >/dev/null 2>&1 || docker start rehearsal-redis
docker exec rehearsal-redis redis-cli set moved-from "$(hostname) $(date -Is)" >/dev/null
mkdir -p /opt/rehearsal && head -c 50M /dev/urandom > /opt/rehearsal/blob.bin && sha256sum /opt/rehearsal/blob.bin > /opt/rehearsal/blob.sha256
ssh-keygen -q -t ed25519 -N '' -f /root/.ssh/rehearsal_key <<<y >/dev/null 2>&1 || true
grep -q rehearsal_key /root/.ssh/authorized_keys 2>/dev/null || cat /root/.ssh/rehearsal_key.pub >> /root/.ssh/authorized_keys
cat > /etc/systemd/system/rehearsal-listener.service <<'U'
[Unit]
Description=rehearsal game-like UDP+TCP listener
After=network.target
[Service]
ExecStart=/usr/bin/python3 -c "import socket,threading;t=socket.socket();t.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1);t.bind(('0.0.0.0',27015));t.listen();u=socket.socket(socket.AF_INET,socket.SOCK_DGRAM);u.bind(('0.0.0.0',27015));threading.Thread(target=lambda:[u.recvfrom(1) for _ in iter(int,1)],daemon=True).start();[t.accept()[0].close() for _ in iter(int,1)]"
Restart=always
[Install]
WantedBy=multi-user.target
U
systemctl daemon-reload && systemctl enable --now rehearsal-listener
(crontab -l 2>/dev/null | grep -v rehearsal-cron; echo "*/5 * * * * echo \\"$(date -Is)\\" >> /opt/rehearsal/cron.log # rehearsal-cron") | crontab -
command -v ufw >/dev/null 2>&1 && (ufw allow 27015 >/dev/null 2>&1 || true)
echo PREPARED
`;

type ServerRow = NonNullable<Awaited<ReturnType<typeof loadServer>>>;
async function loadServer(ref: string) {
  return db.server.findFirst({
    where: { OR: [{ id: ref }, { hostname: ref }] },
    include: { node: true, user: { select: { email: true } }, dedicatedIp: { select: { address: true } }, plan: true, gamePlan: true },
  });
}

async function assertRehearsalEligible(server: ServerRow): Promise<void> {
  const problems: string[] = [];
  if ((server.user?.email ?? "").toLowerCase() !== ACCOUNT.toLowerCase()) problems.push(`owner ${server.user?.email ?? "?"} is not the rehearsal account ${ACCOUNT}`);
  if (!server.vmid || !server.node) problems.push("server has no VM/node");
  else {
    const conn = pveFor(server.node);
    const cfg = await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`).catch(() => null);
    const tags = splitTags(cfg?.tags);
    if (!tags.includes(REHEARSAL_TAG)) problems.push(`vm ${server.vmid} on ${server.node.name} is not tagged ${REHEARSAL_TAG} (tags: ${tags.join(";") || "none"}) — tag it with: qm set ${server.vmid} --tags "$(qm config ${server.vmid} | awk '/^tags:/{print $2}');${REHEARSAL_TAG}"`);
  }
  if (!server.isFree && (server.plan?.monthlyCents ?? 0) > 0 && !flag("allow-paid-plan")) problems.push("server has a paid plan — a rehearsal VM must be the QA order (or pass --allow-paid-plan)");
  if (problems.length) {
    console.error(`REFUSED — this is not a rehearsal VM:\n  - ${problems.join("\n  - ")}`);
    process.exit(2);
  }
}

async function fingerprint(server: ServerRow, label: string): Promise<string> {
  const text = await withServerSsh(server as any, async (conn) => {
    const r = await exec(conn, `bash -s <<'NXFP'\n${FINGERPRINT}\nNXFP`, { timeoutMs: 600_000 } as any);
    return (r as any).stdout ?? String(r);
  });
  const file = `${OUT_DIR}/${server.hostname}-${label}.txt`;
  writeFileSync(file, text);
  return file;
}

function diffFingerprints(before: string, after: string): { changed: string[]; unexpected: string[]; missing: string[] } {
  const parse = (f: string) => Object.fromEntries(readFileSync(f, "utf8").split("\n").filter(Boolean).map((l) => l.split("\t") as [string, string]));
  const a = parse(before);
  const b = parse(after);
  const changed: string[] = [];
  const unexpected: string[] = [];
  const missing: string[] = [];
  for (const k of Object.keys(a)) {
    if (!(k in b)) {
      missing.push(k);
      continue;
    }
    if (a[k] !== b[k]) {
      changed.push(`${k}: ${a[k]} → ${b[k]}`);
      if (!/EXPECTED_CHANGE|VOLATILE|^ci\.(status|result|previous_instance_ids)|^disk\.root_df_used|^svc\.running|^ports\.listen\.procs|^fs\.var_lib_docker\.meta/.test(k)) unexpected.push(k);
    }
  }
  return { changed, unexpected, missing };
}

async function main() {
  const ref = arg("server");
  if (!ref) {
    console.error("usage: --server <id|hostname> --target <nodeName> [--execute] [--force-stop] [--cleanup] [--prepare]");
    process.exit(1);
  }
  mkdirSync(OUT_DIR, { recursive: true });
  const server = await loadServer(ref);
  if (!server) throw new Error(`server ${ref} not found`);
  await assertRehearsalEligible(server);

  if (flag("prepare")) {
    console.log(`[prepare] installing the rehearsal payload into ${server.hostname}…`);
    const out = await withServerSsh(server as any, async (conn) => exec(conn, PREPARE_SCRIPT, { timeoutMs: 900_000 } as any));
    console.log(String((out as any).stdout ?? out).trim().split("\n").slice(-5).join("\n"));
    return;
  }

  const targetName = arg("target");
  if (!targetName) throw new Error("--target <nodeName> is required");
  const target = await db.node.findFirst({ where: { OR: [{ name: targetName }, { id: targetName }] } });
  if (!target) throw new Error(`node ${targetName} not found`);
  if (target.isPrimary && !flag("allow-primary-target")) {
    console.error("REFUSED — the primary is never a rehearsal target (pass --allow-primary-target to override)");
    process.exit(2);
  }
  if (await db.vmMove.count({ where: { serverId: server.id, status: "RUNNING" } })) throw new Error("a move is already RUNNING for this server");

  // ---- preflight (always) ---------------------------------------------------------
  const plan: MovePlan = await buildMovePlan({ serverId: server.id, targetNodeId: target.id });
  console.log(`\n=== PREFLIGHT ${server.hostname} (${server.node?.name} vmid ${server.vmid}) → ${target.name} ===`);
  for (const c of plan.checks) console.log(`  ${c.ok ? "PASS" : c.blocking ? "FAIL" : "WARN"}  ${c.id.padEnd(26)} ${c.detail}`);
  console.log(`  addressing=${plan.addressing.kind} used=${(plan.sourceUsedBytes / 2 ** 30).toFixed(1)}GB est.full=${plan.estimatedFullSendSec}s est.dark=${plan.estimatedDowntimeSec}s`);
  if (!flag("execute")) {
    console.log(`\nDRY RUN — nothing was changed. Re-run with --execute to move the rehearsal VM.`);
    return;
  }
  if (!plan.ok) {
    console.error("preflight has blocking failures — not executing");
    process.exit(3);
  }

  // ---- before ---------------------------------------------------------------------
  console.log("\n[1/4] fingerprint BEFORE…");
  const before = await fingerprint(server, "before");

  // ---- enqueue through the same path the admin UI uses (DB rows; worker executes) ---
  console.log("[2/4] enqueuing VM_MOVE…");
  const move = await db.vmMove.create({
    data: {
      serverId: server.id,
      sourceNodeId: server.nodeId ?? plan.sourceNodeId,
      targetNodeId: target.id,
      sourceVmid: server.vmid!,
      targetVmid: 0,
      dryRun: false,
      reason: "rehearsal (scripts/vm-move-rehearsal.ts)",
      checkpoints: flag("force-stop") ? { allowForceStop: true } : {},
    },
  });
  await db.job.create({ data: { type: "VM_MOVE", serverId: server.id, payload: { vmMoveId: move.id } } });
  const t0 = Date.now();
  let lastLen = 0;
  for (;;) {
    await sleep(5000);
    const row = await db.vmMove.findUnique({ where: { id: move.id } });
    if (!row) throw new Error("move row vanished");
    const log = (row.log as MoveLogLine[] | null) ?? [];
    for (const l of log.slice(lastLen)) console.log(`  ${l.at.slice(11, 19)} ${l.phase.padEnd(16)} ${l.msg}`);
    lastLen = log.length;
    if (["DONE", "ROLLED_BACK", "FAILED"].includes(row.status)) {
      console.log(`  → ${row.status} after ${Math.round((Date.now() - t0) / 1000)}s${row.error ? ` (${row.error})` : ""}`);
      if (row.status !== "DONE") {
        writeFileSync(`${OUT_DIR}/${move.id}.json`, JSON.stringify({ move: row, plan, before }, null, 2));
        process.exit(4);
      }
      break;
    }
    if (Date.now() - t0 > 4 * 3600_000) throw new Error("rehearsal timed out after 4h");
  }

  // ---- after ----------------------------------------------------------------------
  console.log("[3/4] fingerprint AFTER (via the NEW address)…");
  const after = await fingerprint((await loadServer(server.id))!, "after");
  const d = diffFingerprints(before, after);
  console.log(`\n=== DIFF (${d.changed.length} changed, ${d.unexpected.length} UNEXPECTED, ${d.missing.length} missing) ===`);
  for (const c of d.changed) console.log(`  ${d.unexpected.some((u) => c.startsWith(u)) ? "!!" : "ok"} ${c}`);
  for (const m of d.missing) console.log(`  !! missing after: ${m}`);
  const verdict = d.unexpected.length === 0 && d.missing.length === 0 ? "PASS" : "FAIL";
  console.log(`\nVERDICT: ${verdict}`);

  // ---- optional cleanup --------------------------------------------------------------
  if (flag("cleanup") && verdict === "PASS") {
    console.log("[4/4] enqueuing VM_MOVE_CLEANUP (force)…");
    await db.job.create({ data: { type: "VM_MOVE_CLEANUP", serverId: server.id, payload: { vmMoveId: move.id, force: true } } });
  } else {
    console.log(`[4/4] source kept on ${server.node?.name} until ${(await db.vmMove.findUnique({ where: { id: move.id } }))?.keepSourceUntil?.toISOString()} — cleanup with requestVmMoveCleanup(${move.id}, { force: true })`);
  }
  writeFileSync(`${OUT_DIR}/${move.id}.json`, JSON.stringify({ verdict, move: await db.vmMove.findUnique({ where: { id: move.id } }), plan, before, after, diff: d }, null, 2));
  if (verdict !== "PASS") process.exit(5);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(() => db.$disconnect());

